-- ===== 00015_append_only_truncate.sql =====

-- Append-only enforcement, part 2 (follow-up to T0013).
--
-- Row-level triggers do NOT fire on TRUNCATE, so the immutability added in
-- 00014 could still be bypassed wholesale with `TRUNCATE <table> CASCADE`,
-- erasing an entire history in one statement. A statement-level BEFORE
-- TRUNCATE trigger closes that hole, reusing the same append_only_guard()
-- function (which reads TG_TABLE_NAME / TG_OP, set for statement-level
-- triggers exactly as for row-level ones).
--
-- Covers the same 13 tables as 00014. If that set changes, both migrations
-- must be extended with a new forward-only migration - never edited in place.

CREATE TRIGGER asset_lineage_no_truncate
  BEFORE TRUNCATE ON asset_lineage FOR EACH STATEMENT
  EXECUTE FUNCTION append_only_guard();

CREATE TRIGGER audit_log_no_truncate
  BEFORE TRUNCATE ON audit_log FOR EACH STATEMENT
  EXECUTE FUNCTION append_only_guard();

CREATE TRIGGER contribution_events_no_truncate
  BEFORE TRUNCATE ON contribution_events FOR EACH STATEMENT
  EXECUTE FUNCTION append_only_guard();

CREATE TRIGGER external_reference_snapshots_no_truncate
  BEFORE TRUNCATE ON external_reference_snapshots FOR EACH STATEMENT
  EXECUTE FUNCTION append_only_guard();

CREATE TRIGGER policy_versions_no_truncate
  BEFORE TRUNCATE ON policy_versions FOR EACH STATEMENT
  EXECUTE FUNCTION append_only_guard();

CREATE TRIGGER project_states_no_truncate
  BEFORE TRUNCATE ON project_states FOR EACH STATEMENT
  EXECUTE FUNCTION append_only_guard();

CREATE TRIGGER relation_versions_no_truncate
  BEFORE TRUNCATE ON relation_versions FOR EACH STATEMENT
  EXECUTE FUNCTION append_only_guard();

CREATE TRIGGER releases_no_truncate
  BEFORE TRUNCATE ON releases FOR EACH STATEMENT
  EXECUTE FUNCTION append_only_guard();

CREATE TRIGGER research_asset_versions_no_truncate
  BEFORE TRUNCATE ON research_asset_versions FOR EACH STATEMENT
  EXECUTE FUNCTION append_only_guard();

CREATE TRIGGER research_events_no_truncate
  BEFORE TRUNCATE ON research_events FOR EACH STATEMENT
  EXECUTE FUNCTION append_only_guard();

CREATE TRIGGER scientific_object_versions_no_truncate
  BEFORE TRUNCATE ON scientific_object_versions FOR EACH STATEMENT
  EXECUTE FUNCTION append_only_guard();

CREATE TRIGGER state_commits_no_truncate
  BEFORE TRUNCATE ON state_commits FOR EACH STATEMENT
  EXECUTE FUNCTION append_only_guard();

CREATE TRIGGER validation_results_no_truncate
  BEFORE TRUNCATE ON validation_results FOR EACH STATEMENT
  EXECUTE FUNCTION append_only_guard();


-- ===== 00016_auth_password.sql =====

-- Email+password authentication (T0101): users.password_hash stores the
-- encoded password hash of an email+password account. NULL means the
-- account authenticates via OIDC only — both account kinds share one
-- identity space, and the credential column is deliberately opaque to
-- everything except the authn application layer (the encoding carries its
-- own parameters, so the KDF can be upgraded in place later).
ALTER TABLE users ADD COLUMN password_hash text NULL;

COMMENT ON COLUMN users.password_hash IS
  'argon2id PHC encoding ($argon2id$v=19$m=65536,t=3,p=2$...); NULL = OIDC-only account';


-- ===== 00017_profiles.sql =====

-- Research profile content (T0102): profiles is the 1:1 profile projection
-- for a person identity (docs/21 lists users and profiles as separate
-- canonical tables). The identity facts (handle, display_name, email) stay
-- on users; the profile content starts with bio and is where later profile
-- settings (per-field visibility etc.) will land without touching identity.
--
-- bio is a current projection, deliberately NOT append-only: the owner may
-- edit it (docs/21 §4 — the append-only set is the history/ledger tables).
-- The backfill materializes a row for every existing identity so the 1:1
-- shape holds from the moment the migration lands; stores also create the
-- row atomically with the user (credential store CTE, T0102).
CREATE TABLE profiles (
  user_id uuid PRIMARY KEY REFERENCES users(id) ON DELETE RESTRICT,
  bio text NOT NULL DEFAULT '',
  updated_at timestamptz NOT NULL DEFAULT now()
);

INSERT INTO profiles (user_id) SELECT id FROM users;


-- ===== 00018_organization_governance.sql =====

-- Organization governance (T0103): organizations.deactivated_at is the
-- only "delete" the domain offers (CLAUDE.md §9.8 — nothing disappears,
-- state only evolves). History keeps referring to deactivated organizations;
-- governance refuses new memberships/role changes on them (enforced by the
-- application layer, checked by tests).
ALTER TABLE organizations ADD COLUMN deactivated_at timestamptz NULL;

COMMENT ON COLUMN organizations.deactivated_at IS
  'soft-delete marker: set when the organization is deactivated by its owner; NULL = active';

-- The membership listing hot path (a user''s organizations) filters and
-- joins on user_id, which the composite PK does not cover from this side.
CREATE INDEX organization_memberships_user_idx ON organization_memberships (user_id);


-- ===== 00019_project_provisioning.sql =====

-- Project creation shell (T0104): provision_status records the GitProvider
-- provisioning state. Every new project starts 'pending'; T0301's Gitea
-- adapter moves it to 'provisioned' (or 'failed'). The column is part of
-- the project row, not a separate queue: the provisioning task derives its
-- work list from provision_status = 'pending'.
ALTER TABLE projects ADD COLUMN provision_status text NOT NULL DEFAULT 'pending'
  CHECK (provision_status IN ('pending', 'provisioned', 'failed'));

COMMENT ON COLUMN projects.provision_status IS
  'GitProvider provisioning state: pending (created, repo not provisioned yet), provisioned (T0301), failed';

-- Personal projects (organization_id IS NULL) are not covered by the
-- UNIQUE (organization_id, slug) constraint — PostgreSQL treats NULLs as
-- distinct there — so their slugs need their own uniqueness rule.
CREATE UNIQUE INDEX projects_personal_slug_idx ON projects (slug) WHERE organization_id IS NULL;


-- ===== 00020_audit_scopes.sql =====

-- Audit log organization scope (T0110): governance events (org.created,
-- org.updated, org.deactivated, org.member.*) are organization-scoped, and
-- the activity query filters by scope. audit_log already carries project_id;
-- the new nullable organization_id gives the organization scope the same
-- shape. The column is appended (ALTER TABLE ADD COLUMN), so it sits after
-- occurred_at in ordinal order.
--
-- Append-only enforcement already covers audit_log (00014 row triggers for
-- UPDATE/DELETE, 00015 statement-level TRUNCATE guard): new rows only, and
-- this column is written once at INSERT like every other column.
ALTER TABLE audit_log ADD COLUMN organization_id uuid REFERENCES organizations(id) ON DELETE RESTRICT;

-- Activity queries walk the log newest-first per scope; the composite
-- indexes order by (scope, occurred_at, id) so the keyset page
-- (occurred_at, id) < (before_ts, before_id) rides one index per scope.
CREATE INDEX audit_log_project_occurred_idx ON audit_log (project_id, occurred_at DESC, id DESC);
CREATE INDEX audit_log_organization_occurred_idx ON audit_log (organization_id, occurred_at DESC, id DESC);
CREATE INDEX audit_log_actor_occurred_idx ON audit_log (actor_id, occurred_at DESC, id DESC);


-- ===== 00022_git_repository_provisioning.sql =====

-- GitProvider repository provisioning (T0301): the canonical record of the
-- platform→GitProvider (Gitea) repository mapping and the push-webhook HMAC
-- secret.
--
-- projects.git_repository_external_id (00003) is filled with the
-- GitProvider-side repository reference ("<owner>/<name>") once the
-- repository exists; the CHECK keeps the row honest — a project can never
-- report provisioned without the external reference.
--
-- Deliberately NOT added to projects: the failure reason. The canonical
-- store records the STATE (provision_status = 'failed', 00019) and the
-- job loop's structured logs carry the redacted reason — a projects column
-- would drag every project read path into the provisioning concern (and
-- sqlc's project queries select whole rows).
--
-- The webhook secret is also NOT a projects column: it is a credential
-- (docs/55 SECRET class), so it lives in its own table, is read only by
-- internal/gitprovider's own queries, and never rides the project
-- read/write paths or any API payload. One row per project IS the
-- project→repo 1:1 invariant at the storage layer (primary key on
-- project_id), with UNIQUE (owner, name) backing the name-derivation rule.
ALTER TABLE projects ADD CONSTRAINT projects_provision_consistent
  CHECK (provision_status <> 'provisioned' OR git_repository_external_id IS NOT NULL);

CREATE TABLE git_repository_provisions (
  project_id uuid PRIMARY KEY REFERENCES projects(id) ON DELETE RESTRICT,
  owner text NOT NULL,
  name text NOT NULL,
  gitea_repo_id bigint NOT NULL,
  webhook_id bigint NOT NULL,
  webhook_secret text NOT NULL,
  provisioned_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (owner, name)
);

COMMENT ON TABLE git_repository_provisions IS
  'The platform→GitProvider repository mapping (T0301): one row per provisioned project (project→repo 1:1). Product domain objects never read Gitea state; this table is the platform-side record of the provider-side facts.';

COMMENT ON COLUMN git_repository_provisions.webhook_secret IS
  'HMAC secret of the push webhook (docs/55 SECRET). Written at provisioning, read only by internal/gitprovider (T0305 push verification); never exposed through the API.';


-- ===== 00024_scientific_object_version_counter.sql =====

-- Scientific object version counter (task T0202): current_version_no is both
-- the materialized current head of the append-only version log (docs/21 §5)
-- and the atomic compare-and-swap cell behind expected_version creation. The
-- version rows themselves stay append-only (migrations 00014/00015); this
-- pointer is the one deliberately mutable projection on scientific_objects
-- and is maintained by the repository inside the same transaction that
-- inserts the version row.
ALTER TABLE scientific_objects
  ADD COLUMN current_version_no integer NOT NULL DEFAULT 0
  CHECK (current_version_no >= 0);

-- Backfill from the version log so the pointer matches history on any
-- database where rows were written before this migration.
UPDATE scientific_objects o
   SET current_version_no = v.latest
  FROM (SELECT object_id, max(version_no) AS latest
          FROM scientific_object_versions
         GROUP BY object_id) v
 WHERE v.object_id = o.id;


-- ===== 00025_relation_version_counter.sql =====

-- Relation version counter (task T0203): current_version_no is both the
-- materialized current head of the append-only relation_versions log
-- (docs/21 §5) and the atomic compare-and-swap cell behind expected_version
-- creation, exactly as 00024 does for scientific objects (T0202). The
-- version rows themselves stay append-only (migrations 00014/00015); this
-- pointer is the one deliberately mutable projection on relations and is
-- maintained by the repository inside the same transaction that inserts the
-- version row.
ALTER TABLE relations
  ADD COLUMN current_version_no integer NOT NULL DEFAULT 0
  CHECK (current_version_no >= 0);

-- Backfill from the version log so the pointer matches history on any
-- database where rows were written before this migration.
UPDATE relations r
   SET current_version_no = v.latest
  FROM (SELECT relation_id, max(version_no) AS latest
          FROM relation_versions
         GROUP BY relation_id) v
 WHERE v.relation_id = r.id;

-- The query-by-type paths (relations of a project filtered by relation
-- type) join relation_versions to relations on the project boundary;
-- relations.project_id had no index (the canonical seed indexes only the
-- relation_versions endpoints).
CREATE INDEX relations_project_idx ON relations(project_id);


-- ===== 00026_state_snapshot_indexes.sql =====

-- State snapshot projection indexes (task T0204). The two projection shapes
-- of the state model (docs/21 §5, docs/07 §7) are:
--
--   1. reading a state's direct members — the scientific object versions and
--      relation versions whose state_id equals the state (the transition each
--      row was created in); and
--   2. walking a branch's state lineage — the project_states chain and the
--      state_commits history, both filtered by branch_id.
--
-- All four projections are rebuildable from the canonical append-only
-- history; these indexes are performance-only, no semantic content.

CREATE INDEX scientific_object_versions_state_idx
  ON scientific_object_versions (state_id);

CREATE INDEX relation_versions_state_idx
  ON relation_versions (state_id);

CREATE INDEX project_states_branch_created_idx
  ON project_states (branch_id, created_at, id);

CREATE INDEX state_commits_branch_created_idx
  ON state_commits (branch_id, created_at, id);


-- ===== 00028_branch_lifecycle_guard.sql =====

-- Branch lifecycle invariants (task T0205): once a research branch is
-- merged or aborted its history is immutable (docs/43: "active → merged |
-- aborted；merged/aborted history immutable"). Enforced by the database
-- itself, for ANY update path — application code, psql, a leaked
-- credential:
--
--   1. the head pointer (branches.base_state_id, the docs/21 §5 "branch
--      current state" projection) must not move on a closed branch —
--      CommitState's compare-and-swap already guards it
--      (queries/rsg.sql UpdateBranchBaseState requires lifecycle_state =
--      'active'), this trigger makes the invariant unconditional;
--   2. the lifecycle itself is terminal: a merged/aborted branch never
--      transitions to another lifecycle (no merged→active, no merged→
--      aborted). The app-side CAS (SetBranchLifecycle requires the active
--      state) is the normal path; this trigger is the backstop.
--
-- branches is deliberately NOT covered by the append-only guards of
-- 00014: it is a mutable row by design (head projection, lifecycle).
-- This is the targeted constraint instead. No existing constraint is
-- changed or dropped; no column semantics are added.

-- +goose StatementBegin
CREATE FUNCTION branch_lifecycle_guard() RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  IF OLD.lifecycle_state <> 'active' AND NEW.lifecycle_state IS DISTINCT FROM OLD.lifecycle_state THEN
    RAISE EXCEPTION 'branch lifecycle is terminal: a % branch cannot move to % (docs/43: active -> merged | aborted only)',
      OLD.lifecycle_state, NEW.lifecycle_state
      USING ERRCODE = 'P0001';
  END IF;
  IF OLD.lifecycle_state <> 'active' AND NEW.base_state_id IS DISTINCT FROM OLD.base_state_id THEN
    RAISE EXCEPTION 'branch head is immutable on a % branch (merged/aborted history is immutable, docs/43)',
      OLD.lifecycle_state
      USING ERRCODE = 'P0001';
  END IF;
  RETURN NEW;
END;
$$;
-- +goose StatementEnd

CREATE TRIGGER branch_lifecycle_guard_trigger
  BEFORE UPDATE ON branches
  FOR EACH ROW EXECUTE FUNCTION branch_lifecycle_guard();

-- Branches are listed per project in creation order
-- (ListBranchesByProject); performance-only index, same discipline as
-- 00026 — the UNIQUE(project_id, name) constraint does not cover the
-- ordering.
CREATE INDEX branches_project_created_idx
  ON branches (project_id, created_at, id);


-- ===== 00031_branch_git_ref_sync.sql =====

-- Semantic branch ↔ Git ref consistency (T0303): the canonical mapping
-- between a branches row and its provider-side ref, and the invariants
-- that make "semantic branch 与 Git ref 一致" unconditional.
--
-- The ref name is DERIVED, never stored twice as an independent fact:
-- branches.git_ref = 'refs/heads/' || name is enforced by
-- branch_git_ref_guard for ANY write path (application code, psql, a leaked
-- credential) — the same discipline as 00028's lifecycle guard. The
-- application service derives the same value on creation
-- (branches.Service.Create), so existing writers are unaffected.
--
-- One mapping row per branches row, created by branch_git_ref_map —
-- branch creation and the mapping can never drift apart, no matter which
-- path inserts the branch.
--
-- Sync state machine (git_branch_refs.sync_state), driven by
-- internal/gitprovider's BranchRefSyncer (the boot sweep plus redelivered
-- jobs re-attempt, the same bounded-retry policy as T0301 provisioning):
--
--   pending → synced | failed | closing      row awaits its ref
--   synced → failed | closing                ref exists, head recorded
--   failed → synced | closing | closed | failed   last attempt failed; retryable
--   closing → closed | failed                branch closed; ref deletion pending
--   closed                                   terminal: ref deleted, final head recorded
--
-- The direction is carried by the row itself: close_requested_at set (or
-- sync_state = 'closing') means "delete the ref"; otherwise "ensure the ref
-- exists". git_branch_ref_guard enforces the machine for ANY update path.
--
-- Ref strategy on branch close (docs/43: active → merged | aborted): the
-- provider ref is DELETED in both cases, after its final head sha is
-- recorded in head_sha (the reconstruction pointer). The semantic history
-- is unaffected — branches / project_states / state_commits stay immutable
-- (00028) — and docs/46 retention applies to scientific history, not to
-- git ref pointers: a dangling research ref must not keep accepting pushes
-- once the semantic path is closed. The deletion is asynchronous:
-- branch_git_ref_close marks the row 'closing' and the syncer performs the
-- provider call; a provider outage leaves the row in the retry backlog.
--
-- main is mapped too (one row per branch, no exceptions). The syncer never
-- creates or deletes refs/heads/main on purpose: for main the fork point
-- resolves to the repository's default branch, which in an empty
-- repository does not exist — so main's row waits (retryable 'failed')
-- until T0302 creates the ref, then adopts it and records the head.
-- main's ref lifecycle belongs to T0302 (initial commit + protection) and
-- the T0406 merge service, not to this table's syncer.

CREATE TABLE git_branch_refs (
  branch_id uuid PRIMARY KEY REFERENCES branches(id) ON DELETE RESTRICT,
  git_ref text NOT NULL,
  -- fork_sha: the provider-side commit the ref was created at — the base
  -- state's project_states.git_commit_sha when recorded (T0305 fills those
  -- on ingestion), otherwise the repository's default branch was used (the
  -- pre-T0305 fallback; every state is an ancestor of the accepted head in
  -- the normal flow).
  fork_sha text,
  -- head_sha: the ref's last known tip, written by the syncer at create,
  -- adopt and close time. On close it is the final head recorded BEFORE
  -- the ref is deleted — the pointer that keeps the closed path
  -- reconstructable. T0305 keeps it fresh on push ingestion.
  head_sha text,
  sync_state text NOT NULL DEFAULT 'pending'
    CHECK (sync_state IN ('pending','synced','failed','closing','closed')),
  close_requested_at timestamptz,
  synced_at timestamptz,
  closed_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);

COMMENT ON TABLE git_branch_refs IS
  'The semantic branch → GitProvider ref mapping and sync record (T0303): one row per branches row (maintained by trigger), the provider-side fork/head commits, and the sync state machine that keeps semantic branch and Git ref consistent. Provider-side calls are internal/gitprovider''s alone; every other product path may only read head_sha.';

COMMENT ON COLUMN git_branch_refs.head_sha IS
  'Last known provider-side tip of the ref; on close, the final head recorded before deletion (the reconstruction pointer — docs/46 retention applies to semantic history; a closed git ref must not keep accepting pushes).';

-- ---------------------------------------------------------------------------
-- branch_git_ref_guard: the branches-side invariants.
--   1. git_ref is DERIVED — it must always equal 'refs/heads/' || name
--      (the 1:1 mapping the acceptance criterion names);
--   2. the branch name is immutable: the git ref is the branch's address,
--      so renaming would be a new branch (V1 has no rename path; a future
--      rename feature changes this migration deliberately, not by accident).
-- ---------------------------------------------------------------------------
-- +goose StatementBegin
CREATE FUNCTION branch_git_ref_guard() RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  IF NEW.git_ref <> 'refs/heads/' || NEW.name THEN
    RAISE EXCEPTION 'branch git_ref must be refs/heads/<name>: % does not name %',
      NEW.git_ref, NEW.name
      USING ERRCODE = 'P0001';
  END IF;
  IF TG_OP = 'UPDATE' AND NEW.name IS DISTINCT FROM OLD.name THEN
    RAISE EXCEPTION 'branch name is immutable: the git ref is the branch address, renaming is a new branch'
      USING ERRCODE = 'P0001';
  END IF;
  RETURN NEW;
END;
$$;
-- +goose StatementEnd

CREATE TRIGGER branch_git_ref_guard_trigger
  BEFORE INSERT OR UPDATE ON branches
  FOR EACH ROW EXECUTE FUNCTION branch_git_ref_guard();

-- branch_git_ref_map: every branch row gets its mapping row, so the sync
-- backlog is self-maintaining — a branch that exists but is unmapped is
-- impossible, whatever path inserted it. A branch born closed (lifecycle
-- already merged/aborted at insert) starts in 'closing': its ref must be
-- removed, never created.
-- +goose StatementBegin
CREATE FUNCTION branch_git_ref_map() RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  IF NEW.lifecycle_state IN ('merged','aborted') THEN
    INSERT INTO git_branch_refs (branch_id, git_ref, sync_state, close_requested_at)
    VALUES (NEW.id, NEW.git_ref, 'closing', now());
  ELSE
    INSERT INTO git_branch_refs (branch_id, git_ref)
    VALUES (NEW.id, NEW.git_ref);
  END IF;
  RETURN NEW;
END;
$$;
-- +goose StatementEnd

CREATE TRIGGER branch_git_ref_map_trigger
  AFTER INSERT ON branches
  FOR EACH ROW EXECUTE FUNCTION branch_git_ref_map();

-- branch_git_ref_close: the abort/merge ref strategy's storage half — when
-- the semantic lifecycle closes (00028's guard enforces the active →
-- merged | aborted direction itself), the mapping row moves to 'closing':
-- the syncer then records the final head and deletes the provider ref.
-- The lifecycle transition commits first; the provider call happens later
-- in the job loop, so a provider outage can never roll back a semantic
-- merge.
-- +goose StatementBegin
CREATE FUNCTION branch_git_ref_close() RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  IF OLD.lifecycle_state = 'active' AND NEW.lifecycle_state IN ('merged','aborted') THEN
    UPDATE git_branch_refs
       SET sync_state = 'closing', close_requested_at = now(), updated_at = now()
     WHERE branch_id = NEW.id;
  END IF;
  RETURN NEW;
END;
$$;
-- +goose StatementEnd

CREATE TRIGGER branch_git_ref_close_trigger
  AFTER UPDATE OF lifecycle_state ON branches
  FOR EACH ROW EXECUTE FUNCTION branch_git_ref_close();

-- git_branch_ref_guard: the mapping-row invariants — the stored git_ref
-- matches the branch's derived ref (backstop for the guard above and for
-- the backfill below), the sync state machine only moves forward, and
-- 'closed' is terminal (a deleted ref's row never reopens).
-- +goose StatementBegin
CREATE FUNCTION git_branch_ref_guard() RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
  want text;
BEGIN
  SELECT 'refs/heads/' || name INTO want FROM branches WHERE id = NEW.branch_id;
  IF want IS NULL OR NEW.git_ref <> want THEN
    RAISE EXCEPTION 'git_branch_refs.git_ref must name its branch: % does not name branch %',
      NEW.git_ref, NEW.branch_id
      USING ERRCODE = 'P0001';
  END IF;
  IF TG_OP = 'INSERT' AND NEW.sync_state = 'closed' THEN
    RAISE EXCEPTION 'a mapping row is born with work to do: closed is only reached through closing'
      USING ERRCODE = 'P0001';
  END IF;
  IF TG_OP = 'UPDATE' THEN
    IF NEW.git_ref IS DISTINCT FROM OLD.git_ref THEN
      RAISE EXCEPTION 'git_branch_refs.git_ref is immutable'
        USING ERRCODE = 'P0001';
    END IF;
    IF OLD.sync_state = 'closed' THEN
      RAISE EXCEPTION 'closed is terminal: a deleted ref''s row does not reopen'
        USING ERRCODE = 'P0001';
    END IF;
    IF OLD.sync_state = 'pending' AND NEW.sync_state NOT IN ('synced','failed','closing') THEN
      RAISE EXCEPTION 'pending may only move to synced, failed or closing'
        USING ERRCODE = 'P0001';
    END IF;
    IF OLD.sync_state = 'synced' AND NEW.sync_state NOT IN ('failed','closing') THEN
      RAISE EXCEPTION 'synced may only move to failed or closing'
        USING ERRCODE = 'P0001';
    END IF;
    IF OLD.sync_state = 'failed' AND NEW.sync_state NOT IN ('synced','closing','failed','closed') THEN
      RAISE EXCEPTION 'failed may only retry, reach synced, close, or reach closed'
        USING ERRCODE = 'P0001';
    END IF;
    IF OLD.sync_state = 'closing' AND NEW.sync_state NOT IN ('closed','failed') THEN
      RAISE EXCEPTION 'closing may only reach closed or fail back for retry'
        USING ERRCODE = 'P0001';
    END IF;
  END IF;
  NEW.updated_at = now();
  RETURN NEW;
END;
$$;
-- +goose StatementEnd

CREATE TRIGGER git_branch_ref_guard_trigger
  BEFORE INSERT OR UPDATE ON git_branch_refs
  FOR EACH ROW EXECUTE FUNCTION git_branch_ref_guard();

-- Backfill: branches that predate this migration get their mapping row,
-- derived from the name (never copied from a possibly drifted git_ref).
-- Closed branches (merged/aborted) are born 'closing' with a close
-- timestamp, mirroring branch_git_ref_map above: their refs must be
-- removed by the sweep, never created — a dangling ref must not keep
-- accepting pushes once the semantic path is closed, and no close trigger
-- can ever fire for those terminal rows again (00028). Live branches start
-- 'pending': the next startup sweep adopts or creates every ref.
INSERT INTO git_branch_refs (branch_id, git_ref, sync_state, close_requested_at)
SELECT id, 'refs/heads/' || name,
       CASE WHEN lifecycle_state IN ('merged','aborted') THEN 'closing' ELSE 'pending' END,
       CASE WHEN lifecycle_state IN ('merged','aborted') THEN now() ELSE NULL END
FROM branches;

-- The sync backlog is the hot query (boot sweep + redelivered jobs); a
-- partial index keeps the terminal rows out of it. Same discipline as
-- 00026/00028 performance indexes.
CREATE INDEX git_branch_refs_sync_backlog_idx
  ON git_branch_refs (sync_state)
  WHERE sync_state IN ('pending','failed','closing');


-- ===== 00032_git_user_access.sql =====

-- Git user access (T0304): scoped git tokens, revocation and the
-- platform→GitProvider repo access mapping.
--
-- Product identity is never Gitea identity (ADR-019): a platform user who
-- wants to use a real git client gets
--
--   1. a provider-side shadow account (git_user_identities, login
--      "u-<user uuid>" — deterministic, like the repository naming rule
--      in 00022), created token-only: the platform generates an
--      unguessable password at creation and discards it, so the account
--      is usable exclusively through tokens the platform mints;
--   2. one repo access grant per project (git_repo_access): the shadow
--      account becomes a collaborator on the project's provisioned
--      repository with a permission derived from the platform role
--      (viewer → read, contributor/maintainer/owner → write);
--   3. scoped access tokens minted per grant (git_access_tokens): the
--      token carries the narrowest provider scopes (read:repository,
--      or +write:repository) and the collaborator grant above decides
--      which repository the account can reach — that pair
--      (collaborator grant + scoped token) is the "scoped git token"
--      of docs/16 §2 identity mapping. NOTE: a Gitea token is an
--      INSTANCE-scoped capability — it can reach any repository the
--      account can see, a public one included; the platform's tokens
--      are project-scoped in effect only because every platform
--      repository is private. A public-repository feature must revisit
--      this premise.
--
-- Revocation has two levels, and both keep their history (domain
-- invariant 8: nothing disappears, state only evolves):
--
--   - token revocation: the provider-side token is deleted and the row
--     moves to status 'revoked' with revoked_at — the credential dies,
--     the audit trail stays;
--   - access revocation: the collaborator grant is removed provider-side
--     (every token of that user on that repository dies with it) and
--     git_repo_access.revoked_at records when.
--
-- The token VALUE is never stored anywhere on the platform (docs/55
-- SECRET class): Gitea returns it exactly once at mint time, the API
-- hands it to the user exactly once, and only the provider-side token id
-- (gitea_token_id) is kept for revocation. Nothing here can be read back
-- into a credential.

CREATE TABLE git_user_identities (
  user_id uuid PRIMARY KEY REFERENCES users(id) ON DELETE RESTRICT,
  gitea_username text UNIQUE NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now()
);

COMMENT ON TABLE git_user_identities IS
  'The platform→GitProvider user identity mapping (T0304): one shadow Gitea account per platform user (login "u-<user uuid>"). The account is token-only; the platform discards its creation password, so every credential the user ever receives is a scoped token from git_access_tokens.';

CREATE TABLE git_repo_access (
  project_id uuid NOT NULL REFERENCES projects(id) ON DELETE RESTRICT,
  user_id uuid NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
  permission text NOT NULL CHECK (permission IN ('read','write')),
  granted_at timestamptz NOT NULL DEFAULT now(),
  revoked_at timestamptz,
  PRIMARY KEY (project_id, user_id),
  CHECK (revoked_at IS NULL OR revoked_at >= granted_at)
);

COMMENT ON TABLE git_repo_access IS
  'The repo access mapping (T0304): which platform user holds which Git-layer permission on which project''s provisioned repository. The provider-side enforcement is the collaborator membership this row mirrors; revoking access sets revoked_at (nothing disappears, domain invariant 8).';

COMMENT ON COLUMN git_repo_access.permission IS
  'Git-layer permission derived from the platform role: read (viewer) or write (contributor/maintainer/owner). Never wider than the platform role — Git access is a projection of platform membership, not a parallel permission system.';

CREATE TABLE git_access_tokens (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  project_id uuid NOT NULL REFERENCES projects(id) ON DELETE RESTRICT,
  user_id uuid NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
  gitea_username text NOT NULL REFERENCES git_user_identities(gitea_username) ON DELETE RESTRICT,
  token_name text NOT NULL,
  gitea_token_id bigint NOT NULL,
  scope text NOT NULL CHECK (scope IN ('read','write')),
  status text NOT NULL DEFAULT 'active' CHECK (status IN ('active','revoked')),
  issued_at timestamptz NOT NULL DEFAULT now(),
  revoked_at timestamptz,
  CHECK (revoked_at IS NULL OR revoked_at >= issued_at),
  CHECK (status = 'active' OR revoked_at IS NOT NULL)
);

COMMENT ON TABLE git_access_tokens IS
  'Issued scoped git tokens (T0304): one row per minted provider-side access token. The token value itself is never stored (docs/55 SECRET — Gitea shows it once); gitea_token_id is the revocation handle. Rows are never deleted: revocation flips status and sets revoked_at.';

COMMENT ON COLUMN git_access_tokens.scope IS
  'The Gitea scope set the token was minted with: read (read:repository) or write (read:repository + write:repository). Bounded by the user''s collaborator grants — a token can only reach repositories the user holds a git_repo_access row for.';


-- ===== 00033_policy_versioning.sql =====

-- T0603 policy versioning (docs/12 §5): per-scope version uniqueness and
-- the version shape guard. policy_versions itself is append-only
-- (00014/00015 reject UPDATE/DELETE/TRUNCATE at the database): a policy
-- never mutates in place, a change is always a NEW version row, so old
-- versions stay queryable by construction. Each scope line now also has
-- a unique version string — a version number is never reused, not even
-- across a gap.
CREATE UNIQUE INDEX policy_versions_org_version_idx
  ON policy_versions (organization_id, version)
  WHERE organization_id IS NOT NULL;

CREATE UNIQUE INDEX policy_versions_project_version_idx
  ON policy_versions (project_id, version)
  WHERE project_id IS NOT NULL;

-- The version string is a required, bounded label (the app layer allows
-- [A-Za-z0-9._-], this guard only enforces the shape that belongs in the
-- database itself).
ALTER TABLE policy_versions
  ADD CONSTRAINT policy_versions_version_check
  CHECK (char_length(version) BETWEEN 1 AND 64);


-- ===== 00034_push_ingestion.sql =====

-- Push ingestion (T0305): the canonical record of every verified push
-- webhook delivery, the inspected changed-file set, and the candidate
-- semantic diff derived from known scientific manifests (docs/16 §4:
-- webhook → inspect changed paths/manifests → validate known scientific
-- manifests → generate candidate RSG diff).
--
-- Idempotency is the acceptance criterion "重复 webhook 不重复 state":
-- the dedupe key is (gitea_repo_id, git_ref, after_sha) — the provider's
-- own per-attempt delivery id (X-Gitea-Delivery) is regenerated on every
-- redelivery (checked against the running instance), so it cannot dedupe;
-- the pushed head commit is the stable identity of the push's content.
-- Two deliveries of the same push therefore collide on the key and the
-- whole ingestion (changes, candidates, head pointer, state row) is a
-- no-op — INSERT ... ON CONFLICT DO NOTHING inside one transaction.
--
-- Consequence, by design: a force-push that returns a ref to a commit
-- whose tree was already ingested is skipped too — the state at that head
-- already exists, so nothing new to record.
--
-- The ref's head pointer is GUARDED, not a free fact of the push, in
-- both advance paths:
--   * a push whose before names the current head advances only while the
--     pointer is still there — head_sha = before_sha — so a delivery
--     whose before no longer matches is refused and the row marks
--     head_skip_reason = 'stale_before';
--   * a creation push (before is zeros) advances only while the ref is
--     still unborn — head_sha IS NULL — or already at the pushed head; a
--     creation delivery that arrives after the ref gained a head (a
--     later sync, or a newer push) is refused and the row marks
--     head_skip_reason = 'stale_creation'.
-- A refused advance still records the delivery in full (the audit rows
-- are facts of the delivery); only the pointer is held. An older push
-- whose first attempt 503'd and whose redelivery arrives after a newer
-- push was ingested therefore can never rewind the pointer past the
-- newer head, in either path. An exact duplicate is a complete no-op
-- including the pointer. Residual provider/state drift that no push can
-- express is T0309's reconciliation job, not this table's.
--
-- project_states: every pushed branch head is also recorded as a state
-- row (append-only, 00014-guarded — the provider commit arrives WITH the
-- row, never by UPDATE), so a later branch creation can fork its provider
-- ref at the base state's git_commit_sha (T0303's fork-point resolution)
-- and the branch's state history includes its git pushes. The state hash
-- is content-derived: sha256 over the canonical JSON {"git_commit_sha":
-- "<after>"} — the git-compat state identity, distinct from the domain's
-- transition hashes by construction (it hashes the pinned commit, not a
-- parent + operations pair).

CREATE TABLE git_push_ingestions (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  -- The provider's per-attempt delivery id (X-Gitea-Delivery), for
  -- correlating with the provider's delivery log only — NOT the dedupe
  -- key (redeliveries mint a new one).
  delivery_id text,
  gitea_repo_id bigint NOT NULL,
  -- The canonical project, resolved from git_repository_provisions at
  -- ingestion time. NULL when the repository is not provisioned (a
  -- delivery for a repository this platform does not own — recorded for
  -- audit, mapped to no branch and no state).
  project_id uuid REFERENCES projects(id) ON DELETE RESTRICT,
  branch_name text NOT NULL,
  git_ref text NOT NULL,
  before_sha text NOT NULL,
  after_sha text NOT NULL,
  -- The provider's own commit count (may exceed the delivered commit
  -- list — the provider truncates it; the authoritative changed-path set
  -- comes from the git diff, never from the list).
  commit_count integer NOT NULL DEFAULT 0,
  -- Provider login of the pusher (not mapped to a platform user — T0304
  -- owns identity mapping).
  pusher text,
  -- The delivered commit list as the provider sent it (already bounded
  -- by the provider), for audit; the ingestion pipeline does not consume
  -- it.
  commits jsonb NOT NULL DEFAULT '[]'::jsonb,
  -- Why the head-pointer advance was refused for this delivery, when it
  -- was: 'stale_before' means git_branch_refs.head_sha no longer equalled
  -- before_sha when the delivery arrived — a stale redelivery of an older
  -- push (its first attempt failed before recording anything, and a newer
  -- push was ingested in between), or a ref that was never synced to the
  -- claimed base. 'stale_creation' means the delivery created the ref
  -- (before is zeros) but the ref already carried a head this push did
  -- not create — a creation push whose first attempt 503'd and whose
  -- redelivery arrived after a later sync or a newer push set the
  -- pointer. The refusal is recorded, never silent: the audit rows of
  -- the delivery are kept, only the pointer is not moved. NULL when the
  -- advance happened (or there was no pointer to guard).
  head_skip_reason text CHECK (head_skip_reason IS NULL OR head_skip_reason IN ('stale_before', 'stale_creation')),
  created_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (gitea_repo_id, git_ref, after_sha)
);

COMMENT ON TABLE git_push_ingestions IS
  'The canonical record of every accepted push webhook delivery (T0305): one row per distinct pushed head per ref per repository. The dedupe key (gitea_repo_id, git_ref, after_sha) makes redelivered webhooks a no-op — the acceptance criterion 重复 webhook 不重复 state. The head pointer advance is guarded: it happens only when the pointer is still where the push started, and a refused advance is recorded in head_skip_reason, never silently dropped. Rows are append-only (guard below).';

-- git_push_changes: the inspection result — every changed path of the
-- push, classified. semantic_manifest means the file''s content validated
-- against a known scientific schema; everything else is unstructured
-- (T0306 builds the branch completeness flag on this).
CREATE TABLE git_push_changes (
  ingestion_id uuid NOT NULL REFERENCES git_push_ingestions(id) ON DELETE RESTRICT,
  path text NOT NULL,
  change_kind text NOT NULL CHECK (change_kind IN ('added','modified','removed')),
  file_kind text NOT NULL CHECK (file_kind IN ('semantic_manifest','unstructured')),
  -- The matched schema id for semantic_manifest files (the registry''s
  -- canonical $id, e.g. https://open-rd.example/schemas/material.schema.json —
  -- the shape the validation surface stores); NULL for unstructured.
  schema_id text,
  -- sha256 hex of the file content the classification inspected (the
  -- pushed content for added/modified, the pre-push content for removed);
  -- NULL for unstructured files (never read) and oversize files.
  content_sha256 text,
  PRIMARY KEY (ingestion_id, path)
);

COMMENT ON TABLE git_push_changes IS
  'The inspected changed-file set of one ingested push (T0305): path, change kind and the manifest classification (semantic_manifest vs unstructured). The authoritative path set comes from the git diff — the provider payload''s commit list is truncated (checked against the running instance).';

-- git_push_semantic_candidates: the candidate RSG diff — one row per
-- changed manifest file whose content matched a known scientific schema.
-- The candidate is the PROPOSAL the push implies (create/update/delete of
-- the manifest''s content), not an applied semantic change: applying it
-- requires the semantic validation pipeline (T0207 machinery); until then
-- it stays status = ''candidate''. T0306 derives the branch completeness
-- flag from candidates vs unstructured changes.
CREATE TABLE git_push_semantic_candidates (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  ingestion_id uuid NOT NULL REFERENCES git_push_ingestions(id) ON DELETE RESTRICT,
  path text NOT NULL,
  change_kind text NOT NULL CHECK (change_kind IN ('added','modified','removed')),
  schema_id text NOT NULL,
  -- The manifest content the candidate proposes, bounded (the
  -- ingestion reads at most 1 MiB per file).
  candidate jsonb NOT NULL,
  -- candidate is the only state T0305 writes; later tasks move rows to
  -- validated (semantic validation passed), applied (the RSG transition
  -- committed) or rejected (validation failed).
  status text NOT NULL DEFAULT 'candidate' CHECK (status IN ('candidate','validated','applied','rejected')),
  created_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (ingestion_id, path)
);

COMMENT ON TABLE git_push_semantic_candidates IS
  'The candidate semantic diff of one ingested push (T0305): per changed manifest file, the proposed content and its matched schema, awaiting the semantic validation pipeline. Never an applied RSG change by itself.';

-- The ingestion record and the inspection result are append-only facts
-- (docs/21 §4, 00014's discipline): a delivery once recorded is never
-- rewritten — the dedupe no-op and the T0309 reconciliation both depend
-- on it.
CREATE TRIGGER git_push_ingestions_append_only
  BEFORE UPDATE OR DELETE ON git_push_ingestions
  FOR EACH ROW EXECUTE FUNCTION append_only_guard();

CREATE TRIGGER git_push_changes_append_only
  BEFORE UPDATE OR DELETE ON git_push_changes
  FOR EACH ROW EXECUTE FUNCTION append_only_guard();

-- The TRUNCATE halves (00015's discipline: row triggers do not fire on
-- TRUNCATE) — the push record is history, not even wholesale erasure is a
-- legal update path.
CREATE TRIGGER git_push_ingestions_no_truncate
  BEFORE TRUNCATE ON git_push_ingestions FOR EACH STATEMENT
  EXECUTE FUNCTION append_only_guard();

CREATE TRIGGER git_push_changes_no_truncate
  BEFORE TRUNCATE ON git_push_changes FOR EACH STATEMENT
  EXECUTE FUNCTION append_only_guard();

CREATE TRIGGER git_push_semantic_candidates_no_truncate
  BEFORE TRUNCATE ON git_push_semantic_candidates FOR EACH STATEMENT
  EXECUTE FUNCTION append_only_guard();

-- Candidate rows are content-immutable but their status transitions
-- (candidate → validated | applied | rejected, the validation pipeline's
-- later tasks). The guard pins everything except the status: the proposed
-- content of a delivery is a fact of that delivery, and a candidate row is
-- never deleted (its ingestion is append-only).
-- +goose StatementBegin
CREATE FUNCTION git_push_semantic_candidate_guard() RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'git_push_semantic_candidates rows are never deleted: a candidate is a fact of its delivery'
      USING ERRCODE = 'P0001';
  END IF;
  IF NEW.ingestion_id IS DISTINCT FROM OLD.ingestion_id
     OR NEW.path IS DISTINCT FROM OLD.path
     OR NEW.change_kind IS DISTINCT FROM OLD.change_kind
     OR NEW.schema_id IS DISTINCT FROM OLD.schema_id
     OR NEW.candidate IS DISTINCT FROM OLD.candidate THEN
    RAISE EXCEPTION 'git_push_semantic_candidates content is immutable: only status transitions'
      USING ERRCODE = 'P0001';
  END IF;
  RETURN NEW;
END;
$$;
-- +goose StatementEnd

CREATE TRIGGER git_push_semantic_candidate_guard_trigger
  BEFORE UPDATE OR DELETE ON git_push_semantic_candidates
  FOR EACH ROW EXECUTE FUNCTION git_push_semantic_candidate_guard();

-- The head-pointer refresh (T0303 assigned it to T0305): 00031's
-- git_branch_ref_guard forbids ANY update that does not move sync_state —
-- the syncer was the only writer when it was written. Push ingestion must
-- keep head_sha fresh without being a state-machine transition, so the
-- guard is REPLACED with the same machine plus a fast path: an update
-- that changes NOTHING but the tip pointer (head_sha; the guard itself
-- maintains updated_at) is allowed in every state except 'closed'
-- (terminal — a deleted ref's row does not reopen, its final head is
-- already recorded). The fast path is a WHITELIST over every other
-- column — to_jsonb(NEW) and to_jsonb(OLD) compared with head_sha and
-- updated_at removed — so a column added to this table later is covered
-- automatically (a fixed enumeration would let the next new column slip
-- through, as it let branch_id and created_at). The transition rules are
-- otherwise copied verbatim from 00031.
-- +goose StatementBegin
CREATE OR REPLACE FUNCTION git_branch_ref_guard() RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
  want text;
BEGIN
  SELECT 'refs/heads/' || name INTO want FROM branches WHERE id = NEW.branch_id;
  IF want IS NULL OR NEW.git_ref <> want THEN
    RAISE EXCEPTION 'git_branch_refs.git_ref must name its branch: % does not name branch %',
      NEW.git_ref, NEW.branch_id
      USING ERRCODE = 'P0001';
  END IF;
  IF TG_OP = 'INSERT' AND NEW.sync_state = 'closed' THEN
    RAISE EXCEPTION 'a mapping row is born with work to do: closed is only reached through closing'
      USING ERRCODE = 'P0001';
  END IF;
  IF TG_OP = 'UPDATE' THEN
    IF NEW.git_ref IS DISTINCT FROM OLD.git_ref THEN
      RAISE EXCEPTION 'git_branch_refs.git_ref is immutable'
        USING ERRCODE = 'P0001';
    END IF;
    IF OLD.sync_state = 'closed' THEN
      RAISE EXCEPTION 'closed is terminal: a deleted ref''s row does not reopen'
        USING ERRCODE = 'P0001';
    END IF;
    IF to_jsonb(NEW) - 'head_sha' - 'updated_at' = to_jsonb(OLD) - 'head_sha' - 'updated_at' THEN
      -- T0305 head-pointer refresh: the tip moved, nothing else did.
      NEW.updated_at = now();
      RETURN NEW;
    END IF;
    IF OLD.sync_state = 'pending' AND NEW.sync_state NOT IN ('synced','failed','closing') THEN
      RAISE EXCEPTION 'pending may only move to synced, failed or closing'
        USING ERRCODE = 'P0001';
    END IF;
    IF OLD.sync_state = 'synced' AND NEW.sync_state NOT IN ('failed','closing') THEN
      RAISE EXCEPTION 'synced may only move to failed or closing'
        USING ERRCODE = 'P0001';
    END IF;
    IF OLD.sync_state = 'failed' AND NEW.sync_state NOT IN ('synced','closing','failed','closed') THEN
      RAISE EXCEPTION 'failed may only retry, reach synced, close, or reach closed'
        USING ERRCODE = 'P0001';
    END IF;
    IF OLD.sync_state = 'closing' AND NEW.sync_state NOT IN ('closed','failed') THEN
      RAISE EXCEPTION 'closing may only reach closed or fail back for retry'
        USING ERRCODE = 'P0001';
    END IF;
  END IF;
  NEW.updated_at = now();
  RETURN NEW;
END;
$$;
-- +goose StatementEnd


-- ===== 00035_blob_attachment_state.sql =====

-- Blob attachments carry the state they were created in (T0206). The domain
-- contract names blob attachments among the state members whose state_id
-- column makes a state's content enumerable from its id alone
-- (internal/domain/state.go), but 00008 created blob_attachments without the
-- column. Without it the manifest export (ListManifestBlobRefs) can only
-- filter on the owning object version's state, so an attachment made in a
-- later state would appear in earlier states' manifests and move their
-- hashes — a state's hash must be a pure function of the state's own
-- recorded content, so the attachment's own state is the only column the
-- export may filter on.
--
-- Existing rows are backfilled from the owning object version's state_id —
-- the only defensible source available. This is an approximation for
-- pre-existing rows, not a claim about when they were attached: an
-- attachment created in state S for a version that lives in an ancestor
-- state is recorded under the ancestor's state. New attachments (AttachBlob)
-- always write the committing state, so the approximation applies only to
-- rows predating this migration.
ALTER TABLE blob_attachments
  ADD COLUMN state_id uuid REFERENCES project_states(id) ON DELETE RESTRICT;
UPDATE blob_attachments ba
SET state_id = sov.state_id
FROM scientific_object_versions sov
WHERE sov.id = ba.scientific_object_version_id;
ALTER TABLE blob_attachments
  ALTER COLUMN state_id SET NOT NULL;

-- The manifest export's blob-ref filter (ListManifestBlobRefs) walks this
-- column on every export; the index keeps it an indexed lineage lookup
-- instead of a per-export seq scan (same shape as the version tables'
-- state indexes from 00026).
CREATE INDEX blob_attachments_state_idx ON blob_attachments(state_id);


-- ===== 00036_rsg_query_indexes.sql =====

-- RSG query surface index (T0209). The query API's candidate scan is
-- project-scoped with the object-type filter as the index's second
-- column; the relations-by-project scan already uses the
-- relations_project_idx created by migration 00025. Performance-only, no
-- semantic content — every shape remains rebuildable from the canonical
-- append-only history.

CREATE INDEX scientific_objects_project_type_idx
  ON scientific_objects (project_id, object_type);


-- ===== 00038_project_schema_profiles.sql =====

-- T0213 project schema profiles (docs/21 §8): a project registers namespaced,
-- versioned JSON Schema profiles that extend an official base schema with
-- project-specific typed fields — custom metadata never requires changing
-- platform core. Profile versions are immutable: an id+version pair, once
-- registered, is never overwritten or deleted (the append_only_guard trigger
-- below); new content takes a new version. Every scientific object version
-- pins its (schema_id, schema_version), so a profile v2 never invalidates
-- history written under v1 (docs/21 §8: old schema data always stays valid).
--
-- schema_id is the profile's namespaced registry id, the form
-- "project:<project_id>:<name>" — derived server-side, so two projects can
-- never squat the same id and no profile can squat a canonical id (the
-- registry refuses the canonical namespace at registration too).
CREATE TABLE project_schema_profiles (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  project_id uuid NOT NULL REFERENCES projects(id) ON DELETE RESTRICT,
  schema_id text NOT NULL,
  version text NOT NULL,
  -- The official base schema this profile extends, pinned by id+version:
  -- which canonical type the profile governs is a stored fact, not a guess.
  base_schema_id text NOT NULL,
  base_schema_version text NOT NULL,
  -- The exact generated profile document bytes (Go-canonical JSON). TEXT,
  -- not jsonb: the content hash must pin the exact bytes the registry
  -- registered, and jsonb normalization would break byte equality.
  content text NOT NULL,
  content_hash text NOT NULL,
  created_by uuid NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
  created_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (project_id, schema_id, version),
  CONSTRAINT project_schema_profiles_schema_id_check
    CHECK (schema_id LIKE '%:%' AND char_length(schema_id) <= 512),
  CONSTRAINT project_schema_profiles_version_check
    CHECK (version ~ '^[A-Za-z0-9._-]{1,64}$'),
  CONSTRAINT project_schema_profiles_base_check
    CHECK (char_length(base_schema_id) BETWEEN 1 AND 512
           AND char_length(base_schema_version) BETWEEN 1 AND 64),
  CONSTRAINT project_schema_profiles_content_check
    CHECK (jsonb_typeof(content::jsonb) = 'object'),
  CONSTRAINT project_schema_profiles_hash_check
    CHECK (content_hash ~ '^[0-9a-f]{64}$')
);

CREATE INDEX project_schema_profiles_project_idx
  ON project_schema_profiles (project_id, schema_id, created_at DESC, id DESC);

CREATE TRIGGER project_schema_profiles_append_only
  BEFORE UPDATE OR DELETE ON project_schema_profiles
  FOR EACH ROW EXECUTE FUNCTION append_only_guard();

-- Row-level triggers do not fire on TRUNCATE (00015): the immutability above
-- could still be bypassed wholesale with `TRUNCATE ... CASCADE`. The
-- statement-level half reuses the same append_only_guard() function.
CREATE TRIGGER project_schema_profiles_no_truncate
  BEFORE TRUNCATE ON project_schema_profiles FOR EACH STATEMENT
  EXECUTE FUNCTION append_only_guard();


-- ===== 00040_question_hypothesis_relationship_guards.sql =====

-- Research Question ↔ Hypothesis relationship guards (task T0501).
--
-- The question↔hypothesis model rests on four structural references:
--
--   1. hypothesis.question_id names the research question the hypothesis
--      answers (hypothesis.schema.json makes it required; docs/08 gives
--      Hypothesis a question_ref);
--   2. research_question.parent_question_id nests a sub-question under
--      its parent (research_question.schema.json) — this is what makes
--      subquestions structural, not just textual;
--   3. relation "addresses_question" (knowledge category, docs/44): a
--      hypothesis addresses the target research question;
--   4. relation "tests_hypothesis" (knowledge category, docs/44): an
--      experiment or calculation tests the target hypothesis.
--
-- The endpoint-type table declares the endpoint object types the two
-- knowledge edges' NAMES pin (the docs/44 semantics lines): "addresses
-- the target research question" pins addresses_question's target to
-- research_question; "tests the target hypothesis" pins tests_hypothesis's
-- target to hypothesis. Only the end the name states is declared — the
-- source end stays NULL ("unconstrained"), because no spec says who may
-- point at a question or a hypothesis: inventing a source set turned out
-- to contradict the main-line domain model (findings address questions;
-- T0209's rsg_query_test pins that shape). The table mirrors the Go
-- relation catalog (internal/rsg/relationcatalog); an integration test
-- pins the two to each other so the DB declaration can never drift from
-- the catalog. Relations whose type is not declared there are untouched —
-- the catalog itself remains the authority on which relation types
-- exist. A full endpoint-declaration spec for core edges is a separate
-- ADR-level decision (issue #183), not this task's.
--
-- The guards enforce the mechanically decidable half of the model for ANY
-- write path (application code, psql, a leaked credential), in the
-- 00014/00015/00028 discipline: the app services validate on the happy
-- path, the database makes the invariant unconditional.
--
-- Deliberately NOT enforced here:
--
--   * question_state (research_question) and assessment (hypothesis)
--     enums: they are schema-governed scientific content, and they are
--     NOT issue states. An issue row (open → closed) is project
--     coordination; closing an issue never touches a question's or
--     hypothesis's versioned content, so nothing here reads issues.
--     A DB CHECK on the enums would couple every future schema enum
--     change to a migration; the schemareg + gate ladder already validate
--     them per write.
--   * transitions between question_state/assessment values: docs/43 says
--     these assessments are not linear upgrade levels, and an object's
--     lifecycle already allows active → aborted → reopened, so a content
--     regression is a legitimate new version, not an illegal transition.
--
-- The triggers are DEFERRABLE INITIALLY DEFERRED constraint triggers:
-- they fire once, at COMMIT, when every row of the transaction is
-- visible, so a parent and child (or an object and its knowledge
-- relation) may be written in one transaction in any order.

CREATE TABLE knowledge_relation_endpoint_types (
  relation_type text PRIMARY KEY,
  source_object_types text[], -- NULL = the source end is unconstrained
  target_object_types text[] NOT NULL
);

INSERT INTO knowledge_relation_endpoint_types
  (relation_type, source_object_types, target_object_types)
VALUES
  ('addresses_question', NULL, ARRAY['research_question']),
  ('tests_hypothesis', NULL, ARRAY['hypothesis']);

-- +goose StatementBegin
CREATE FUNCTION knowledge_relation_endpoint_guard() RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
  allowed_src text[];
  allowed_tgt text[];
  rel_project uuid;
  src_type text;
  src_project uuid;
  tgt_type text;
  tgt_project uuid;
BEGIN
  SELECT source_object_types, target_object_types
    INTO allowed_src, allowed_tgt
    FROM knowledge_relation_endpoint_types
   WHERE relation_type = NEW.relation_type;
  IF NOT FOUND THEN
    -- Not a declared knowledge relation: nothing to enforce here.
    RETURN NEW;
  END IF;

  SELECT project_id INTO rel_project FROM relations WHERE id = NEW.relation_id;

  SELECT so.object_type, so.project_id INTO src_type, src_project
    FROM scientific_object_versions sov
    JOIN scientific_objects so ON so.id = sov.object_id
   WHERE sov.id = NEW.source_object_version_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'knowledge relation %: source object version % does not exist',
      NEW.relation_type, NEW.source_object_version_id
      USING ERRCODE = 'P0001';
  END IF;

  SELECT so.object_type, so.project_id INTO tgt_type, tgt_project
    FROM scientific_object_versions sov
    JOIN scientific_objects so ON so.id = sov.object_id
   WHERE sov.id = NEW.target_object_version_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'knowledge relation %: target object version % does not exist',
      NEW.relation_type, NEW.target_object_version_id
      USING ERRCODE = 'P0001';
  END IF;

  -- A knowledge edge is a claim about one project's research: both
  -- endpoints must live in the relation's project.
  IF src_project IS DISTINCT FROM rel_project THEN
    RAISE EXCEPTION 'knowledge relation %: source object version % belongs to a different project',
      NEW.relation_type, NEW.source_object_version_id
      USING ERRCODE = 'P0001';
  END IF;
  IF tgt_project IS DISTINCT FROM rel_project THEN
    RAISE EXCEPTION 'knowledge relation %: target object version % belongs to a different project',
      NEW.relation_type, NEW.target_object_version_id
      USING ERRCODE = 'P0001';
  END IF;

  -- NULL means the end is unconstrained: only the end the edge's NAME
  -- states is ever declared, so the source end is NULL for both edges
  -- and the check below only fires once a declaration exists.
  IF allowed_src IS NOT NULL AND NOT (src_type = ANY(allowed_src)) THEN
    RAISE EXCEPTION 'knowledge relation %: source object type % is not allowed (allowed: %)',
      NEW.relation_type, src_type, allowed_src
      USING ERRCODE = 'P0001';
  END IF;
  IF allowed_tgt IS NOT NULL AND NOT (tgt_type = ANY(allowed_tgt)) THEN
    RAISE EXCEPTION 'knowledge relation %: target object type % is not allowed (allowed: %)',
      NEW.relation_type, tgt_type, allowed_tgt
      USING ERRCODE = 'P0001';
  END IF;
  RETURN NEW;
END;
$$;
-- +goose StatementEnd

CREATE CONSTRAINT TRIGGER relation_versions_knowledge_endpoints
  AFTER INSERT ON relation_versions
  DEFERRABLE INITIALLY DEFERRED
  FOR EACH ROW EXECUTE FUNCTION knowledge_relation_endpoint_guard();

-- +goose StatementBegin
CREATE FUNCTION scientific_object_reference_guard() RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
  obj_type text;
  obj_project uuid;
  ref text;
  ref_field text;
  target_type text;
  target_project uuid;
  cur text;
  parent_of_cur text;
  visited text[];
  i int;
BEGIN
  SELECT object_type, project_id INTO obj_type, obj_project
    FROM scientific_objects WHERE id = NEW.object_id;
  IF NOT FOUND THEN
    -- Cannot happen through the FK; guard against misleading errors.
    RETURN NEW;
  END IF;

  IF obj_type = 'research_question' THEN
    ref_field := 'parent_question_id';
  ELSIF obj_type = 'hypothesis' THEN
    ref_field := 'question_id';
  ELSE
    RETURN NEW;
  END IF;

  -- Absent (or JSON null, or empty/whitespace) means "no reference": a
  -- draft hypothesis may not know its question yet, a root question has
  -- no parent. The gate ladder decides whether that omission is
  -- acceptable at this point; the guard only polices a reference that IS
  -- given (an explicitly empty string is still a hard error in the
  -- application-level semantic checks, which run before the write).
  ref := NULLIF(btrim(NEW.payload->>ref_field), '');
  IF ref IS NULL THEN
    RETURN NEW;
  END IF;

  IF ref !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$' THEN
    RAISE EXCEPTION 'scientific object % (%): % reference % is not a uuid',
      NEW.object_id, obj_type, ref_field, ref
      USING ERRCODE = 'P0001';
  END IF;

  SELECT object_type, project_id INTO target_type, target_project
    FROM scientific_objects WHERE id = ref::uuid;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'scientific object % (%): % reference % does not name an existing object',
      NEW.object_id, obj_type, ref_field, ref
      USING ERRCODE = 'P0001';
  END IF;
  IF target_type <> 'research_question' THEN
    RAISE EXCEPTION 'scientific object % (%): % reference % names a % object, not a research_question',
      NEW.object_id, obj_type, ref_field, ref, target_type
      USING ERRCODE = 'P0001';
  END IF;
  IF target_project IS DISTINCT FROM obj_project THEN
    RAISE EXCEPTION 'scientific object % (%): % reference % names a research question of another project',
      NEW.object_id, obj_type, ref_field, ref
      USING ERRCODE = 'P0001';
  END IF;

  -- Parent chains must be acyclic. Walk up from the named parent through
  -- each question's LATEST version row (max(version_no) is the log's own
  -- truth; current_version_no is a projection only the repository
  -- maintains, so a guard that must hold for ANY write path cannot trust
  -- it). A revisit is a cycle and the depth is capped at 64 (a legitimate
  -- question hierarchy is nowhere near that).
  IF obj_type = 'research_question' THEN
    cur := ref;
    visited := ARRAY[NEW.object_id::text];
    FOR i IN 1..64 LOOP
      IF cur = NEW.object_id::text THEN
        RAISE EXCEPTION 'scientific object % (research_question): parent chain forms a cycle through %',
          NEW.object_id, cur
          USING ERRCODE = 'P0001';
      END IF;
      IF cur = ANY(visited) THEN
        RAISE EXCEPTION 'scientific object % (research_question): parent chain forms a cycle at %',
          NEW.object_id, cur
          USING ERRCODE = 'P0001';
      END IF;
      visited := array_append(visited, cur);
      SELECT sov.payload->>'parent_question_id'
        INTO parent_of_cur
        FROM scientific_object_versions sov
       WHERE sov.object_id = cur::uuid
       ORDER BY sov.version_no DESC
       LIMIT 1;
      IF parent_of_cur IS NULL OR btrim(parent_of_cur) = '' THEN
        RETURN NEW; -- the chain ends at a root question
      END IF;
      IF parent_of_cur !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$' THEN
        -- An ancestor row written before this guard existed may carry a
        -- non-uuid parent; the chain cannot be walked through it, and
        -- refusing every new subquestion over old garbage would be wrong.
        RETURN NEW;
      END IF;
      cur := parent_of_cur;
    END LOOP;
    RAISE EXCEPTION 'scientific object % (research_question): parent chain exceeds the depth cap of 64',
      NEW.object_id
      USING ERRCODE = 'P0001';
  END IF;
  RETURN NEW;
END;
$$;
-- +goose StatementEnd

CREATE CONSTRAINT TRIGGER scientific_object_versions_reference_guard
  AFTER INSERT ON scientific_object_versions
  DEFERRABLE INITIALLY DEFERRED
  FOR EACH ROW EXECUTE FUNCTION scientific_object_reference_guard();


-- ===== 00041_claims.sql =====

-- Claim structured projection (task T0502): the queryable, structured
-- face of a claim object version — claim type, subject/property/value,
-- scope, causal basis and assessment as columns instead of payload
-- digging (docs/08 §Claim, docs/21 §7, docs/10 §5, docs/43).
--
-- The source of truth stays scientific_object_versions.payload; this row
-- is a REBUILDABLE projection (docs/21 §5: projections can be rebuilt and
-- are not the historical source of truth), so it deliberately carries no
-- append-only trigger (00014/00015 guard the version logs, not their
-- projections).
--
-- One row per claim VERSION (version_id is the PK): a Finding pins fixed
-- claim versions, so a new claim version is a new row and can never
-- silently rewrite what an older Finding saw (T0503 acceptance).
--
-- scope is the structured claim scope (docs/21 §7: structured JSONB);
-- scope_conditions is its normalized common-fields subset (temperature,
-- pressure, ...) kept as a separate array so projections and indexes
-- reach the conditions without parsing the whole scope.
--
-- basis is the declared causal basis (docs/10 §5: controlled
-- intervention, temporal ordering, confounders considered, dose-response,
-- mechanistic characterization, computational intervention), one
-- {"type","detail"} entry per basis. Causal/mechanistic claims must
-- declare at least one — the semantic check warns when they do not
-- (T0502 acceptance: causal 无 basis 产生 validation warning).
CREATE TABLE claims (
  version_id uuid PRIMARY KEY REFERENCES scientific_object_versions(id) ON DELETE RESTRICT,
  object_id uuid NOT NULL REFERENCES scientific_objects(id) ON DELETE RESTRICT,
  claim_type text NOT NULL CHECK (claim_type IN ('descriptive','quantitative','comparative','associational','predictive','causal','mechanistic')),
  subject_ref text,
  property text,
  value jsonb,
  scope jsonb NOT NULL DEFAULT '{}'::jsonb CHECK (jsonb_typeof(scope) = 'object'),
  scope_conditions jsonb NOT NULL DEFAULT '[]'::jsonb CHECK (jsonb_typeof(scope_conditions) = 'array'),
  basis jsonb NOT NULL DEFAULT '[]'::jsonb CHECK (jsonb_typeof(basis) = 'array'),
  assessment text CHECK (assessment IN ('preliminary','supported','contested','unresolved','superseded','aborted')),
  created_at timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX claims_object_idx ON claims(object_id);
CREATE INDEX claims_type_idx ON claims(claim_type);
CREATE INDEX claims_subject_idx ON claims(subject_ref) WHERE subject_ref IS NOT NULL;
CREATE INDEX claims_scope_conditions_gin ON claims USING gin(scope_conditions);
CREATE INDEX claims_basis_gin ON claims USING gin(basis);


-- ===== 00042_unstructured_change_state.sql =====

-- Unstructured change state (T0306): the branch semantic completeness flag
-- and the two DB-enforced gates that make an incomplete branch unmergeable.
--
-- docs/16 §4: after a push is ingested, the branch is marked
-- `semantic_complete` or `unstructured_changes`. Files the platform cannot
-- parse are RETAINED — every changed path of every push is recorded in
-- git_push_changes (00034), nothing is dropped — but a branch carrying
-- unresolved unstructured content must not reach a mergeable formal PR
-- until the Agent/API has filled in the required scientific semantics:
--   * pull_requests INSERT is refused while the source branch is
--     `unstructured_changes` (the branch cannot OPEN a formal PR);
--   * the branch lifecycle transition active -> merged is refused while the
--     flag is `unstructured_changes` (the merge cannot COMPLETE — the
--     backstop for any path that skips PR creation, today's branches.Merge
--     and T0409's merge governance alike).
-- Both gates are database triggers: they hold for ANY write path —
-- application code, psql, a leaked credential — the same discipline as
-- 00028/00031. That is what "不可绕过 semantic validation merge" means
-- mechanically: no code path can merge an incomplete branch.
--
-- The flag itself is a STORED PROJECTION, not a new fact: its only writer
-- is the push-ingestion store (internal/gitprovider), which recomputes it
-- from the append-only ingestion evidence inside the same transaction that
-- records the delivery and moves the head pointer — so flag and head can
-- never diverge observably. The derivation walks the branch's ingested
-- push chain from git_branch_refs.head_sha backwards over the
-- (before_sha, after_sha) links of git_push_ingestions and keeps, per
-- path, the nearest-to-head record in git_push_changes:
--   * unstructured added/modified  -> outstanding (the file exists at the
--     head in a form the platform does not understand);
--   * semantic_manifest            -> resolved (a later push replaced the
--     content with a known scientific manifest at the same path);
--   * removed                      -> resolved (the file is gone, there is
--     nothing left to understand).
-- A chain that ends at a commit without an ingestion row (a syncer-set
-- head, or the fork point) contributes no evidence and stops the walk —
-- the flag reports only what the evidence shows. The branch returns to
-- `semantic_complete` exactly when the evidence at the head resolves every
-- outstanding path. API state commits do NOT move the flag: there is no
-- linkage between an API commit and the files it would resolve, and
-- clearing on any commit would be the bypass the acceptance criterion
-- forbids.
--
-- One row per branch, born with the branch (branch_semantic_state_map,
-- the same pattern as 00031's branch_git_ref_map) and backfilled here for
-- branches that predate this migration. The row is upserted by ingestion;
-- it is deliberately NOT append-only (it is a projection of other tables'
-- append-only facts) and carries no transition guard — the CHECK on the
-- values is its shape constraint, and its sole writer is ingestion code.
--
-- Trust boundary (recorded, L1): the gates read the projection. A writer
-- that could UPDATE git_branch_semantic_states out-of-band is already a
-- direct-database actor of the kind every guard in this file set exists to
-- bound; the derivation's integrity is enforced by the ingestion store's
-- tests (the flag always equals the derivation from the change rows).

CREATE TABLE git_branch_semantic_states (
  branch_id uuid PRIMARY KEY REFERENCES branches(id) ON DELETE RESTRICT,
  semantic_state text NOT NULL DEFAULT 'semantic_complete'
    CHECK (semantic_state IN ('semantic_complete','unstructured_changes')),
  updated_at timestamptz NOT NULL DEFAULT now()
);

COMMENT ON TABLE git_branch_semantic_states IS
  'The branch semantic completeness flag (T0306, docs/16 §4): semantic_complete while the pushed content at the git head pointer is fully understood, unstructured_changes while at least one pushed path is an unresolved unstructured change. A projection of the append-only git_push_changes evidence, recomputed by the push-ingestion store in the delivery transaction; the pull_requests INSERT gate and the branch merge gate read it. Never appended: upserted per branch.';

-- Every branch that already exists gets its row (default: complete —
-- nothing was ever pushed and inspected for it); branches created from
-- here on get theirs from branch_semantic_state_map.
INSERT INTO git_branch_semantic_states (branch_id)
SELECT id FROM branches;

-- branch_semantic_state_map: one flag row per branch row, so a branch
-- without a flag row is impossible whatever path inserted it — the same
-- self-maintaining pattern as 00031's branch_git_ref_map.
-- +goose StatementBegin
CREATE FUNCTION branch_semantic_state_map() RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  INSERT INTO git_branch_semantic_states (branch_id)
  VALUES (NEW.id);
  RETURN NEW;
END;
$$;
-- +goose StatementEnd

CREATE TRIGGER branch_semantic_state_map_trigger
  AFTER INSERT ON branches
  FOR EACH ROW EXECUTE FUNCTION branch_semantic_state_map();

-- branch_merge_semantic_gate: the merge cannot COMPLETE while the branch
-- is unstructured_changes (docs/16 §4: the branch cannot become mergeable
-- until the required scientific semantics are filled). Fired on the
-- lifecycle transition to merged — the transition that lands the diff as
-- accepted state — and only on that transition: reaching merged is the
-- merge, staying merged is not a re-merge. A missing flag row (a branch
-- predating 00042 that was never backfilled — impossible, the backfill
-- above ran — or a manual row deletion) counts as complete: absence of
-- evidence is not evidence of unstructured content.
-- +goose StatementBegin
CREATE FUNCTION branch_merge_semantic_gate() RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  IF TG_OP = 'UPDATE'
     AND NEW.lifecycle_state = 'merged'
     AND OLD.lifecycle_state IS DISTINCT FROM 'merged' THEN
    IF EXISTS (
      SELECT 1 FROM git_branch_semantic_states
      WHERE branch_id = NEW.id AND semantic_state = 'unstructured_changes'
    ) THEN
      RAISE EXCEPTION 'branch % cannot merge: its semantic state is unstructured_changes — the pushed content carries changes the platform cannot parse, and docs/16 §4 forbids merging until the required scientific semantics are filled',
        NEW.id
        USING ERRCODE = 'P0001';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;
-- +goose StatementEnd

CREATE TRIGGER branch_merge_semantic_gate_trigger
  BEFORE UPDATE ON branches
  FOR EACH ROW EXECUTE FUNCTION branch_merge_semantic_gate();

-- pull_request_semantic_gate: the branch cannot OPEN a formal PR while it
-- is unstructured_changes. The gate checks the SOURCE branch at INSERT —
-- the branch whose diff the PR proposes. The PR row is created by T0402's
-- domain (not yet built); the gate exists now so the constraint is
-- canonical-store-level before any writer exists, exactly like 00009's
-- schema itself. An UPDATE that later refreshes the PR's proposed state
-- stays inside the same source branch; completeness at merge time is
-- re-checked by branch_merge_semantic_gate.
-- +goose StatementBegin
CREATE FUNCTION pull_request_semantic_gate() RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  IF EXISTS (
    SELECT 1 FROM git_branch_semantic_states
    WHERE branch_id = NEW.source_branch_id AND semantic_state = 'unstructured_changes'
  ) THEN
    RAISE EXCEPTION 'pull request cannot be opened from branch %: its semantic state is unstructured_changes — the pushed content carries changes the platform cannot parse, and docs/16 §4 forbids a formal PR until the required scientific semantics are filled',
      NEW.source_branch_id
      USING ERRCODE = 'P0001';
  END IF;
  RETURN NEW;
END;
$$;
-- +goose StatementEnd

CREATE TRIGGER pull_request_semantic_gate_trigger
  BEFORE INSERT ON pull_requests
  FOR EACH ROW EXECUTE FUNCTION pull_request_semantic_gate();


-- ===== 00043_provenance_graph_projection.sql =====

-- Provenance graph projection (task T0505, docs/10): a rebuildable read
-- model of every provenance-category relation version (docs/44: the
-- provenance/structure and lineage/network types), with both endpoint
-- display labels resolved into the row. This is the graph the provenance
-- reads walk: lineage ("where did this come from") and impact ("what
-- depends on this").
--
-- The projection is derived data, not history — unlike the version logs it
-- is deliberately NOT append-only protected (migrations 00014/00015): it
-- can be truncated and rebuilt from canonical truth at any time
-- (rebuild_provenance_edges()). It is maintained incrementally by an AFTER
-- INSERT trigger on relation_versions; because relation_versions is
-- append-only, a projected row is written exactly once and never needs
-- updating or deleting, so INSERT is the only maintenance path.
--
-- The provenance type set is pinned here AND by
-- relationcatalog.ProvenanceTypes() in Go; tests/integration/
-- provenance_test.go seeds one edge per catalog type and asserts projection
-- membership both ways, so the two copies cannot drift silently. The table
-- itself enforces the membership invariant too: the CHECK added after
-- provenance_relation_types() below (the constraint needs the function to
-- exist) keeps any row outside the provenance set out, as defense-in-depth
-- beyond the trigger filter and the rebuild's WHERE clause.
--
-- Additive only: no existing object is altered. The backfill at the end
-- projects the relation versions that already exist when a database
-- upgrades; a fresh install has none and the backfill is a no-op.

CREATE TABLE provenance_edges (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  project_id uuid NOT NULL REFERENCES projects(id) ON DELETE RESTRICT,
  relation_id uuid NOT NULL REFERENCES relations(id) ON DELETE RESTRICT,
  relation_version_id uuid NOT NULL REFERENCES relation_versions(id) ON DELETE RESTRICT,
  relation_type text NOT NULL,
  source_object_id uuid NOT NULL REFERENCES scientific_objects(id) ON DELETE RESTRICT,
  source_object_version_id uuid NOT NULL REFERENCES scientific_object_versions(id) ON DELETE RESTRICT,
  source_object_type text NOT NULL,
  source_title text NOT NULL,
  source_version_no integer NOT NULL,
  target_object_id uuid NOT NULL REFERENCES scientific_objects(id) ON DELETE RESTRICT,
  target_object_version_id uuid NOT NULL REFERENCES scientific_object_versions(id) ON DELETE RESTRICT,
  target_object_type text NOT NULL,
  target_title text NOT NULL,
  target_version_no integer NOT NULL,
  created_by uuid NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
  created_at timestamptz NOT NULL,
  UNIQUE(relation_version_id)
);
CREATE INDEX provenance_edges_project_idx ON provenance_edges(project_id, relation_type);
CREATE INDEX provenance_edges_source_version_idx ON provenance_edges(source_object_version_id);
CREATE INDEX provenance_edges_target_version_idx ON provenance_edges(target_object_version_id);

-- provenance_relation_types is the SQL copy of relationcatalog's
-- provenance set (docs/44). Keep it in sync with
-- internal/rsg/relationcatalog ProvenanceInference flags — the integration
-- test's catalog cross-check fails when they diverge.
-- +goose StatementBegin
CREATE FUNCTION provenance_relation_types() RETURNS text[]
LANGUAGE sql IMMUTABLE
AS $$
  SELECT ARRAY[
    -- Provenance/structure (docs/44).
    'contains', 'depends_on', 'derived_from', 'follows_protocol',
    'generated_by', 'parameterized_by', 'part_of', 'performed_on',
    'produces', 'references', 'supersedes', 'uses',
    -- Lineage/network (docs/44).
    'derived_asset_from', 'forked_from', 'originates_from',
    'published_from', 'used_by'
  ];
$$;
-- +goose StatementEnd

-- The projection's own invariant, enforced where the table is born: a
-- row's relation_type must be a provenance type. The trigger filter and
-- the rebuild's WHERE already guarantee it, so this CHECK is
-- defense-in-depth against any future write path — it costs nothing at
-- insert time (the same IMMUTABLE list the trigger consults). It is added
-- after the function because CREATE TABLE cannot reference a function
-- defined later in the migration.
ALTER TABLE provenance_edges
  ADD CONSTRAINT provenance_edges_relation_type_check
  CHECK (relation_type = ANY(provenance_relation_types()));

-- provenance_edges_maintain projects one new relation version. The
-- endpoint joins always match: the relation_versions foreign keys
-- guarantee the rows exist at insert time.
-- +goose StatementBegin
CREATE FUNCTION provenance_edges_maintain() RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  IF NEW.relation_type = ANY(provenance_relation_types()) THEN
    INSERT INTO provenance_edges (
      project_id, relation_id, relation_version_id, relation_type,
      source_object_id, source_object_version_id, source_object_type,
      source_title, source_version_no,
      target_object_id, target_object_version_id, target_object_type,
      target_title, target_version_no,
      created_by, created_at)
    SELECT
      r.project_id, NEW.relation_id, NEW.id, NEW.relation_type,
      sov_s.object_id, NEW.source_object_version_id, so_s.object_type,
      sov_s.title, sov_s.version_no,
      sov_t.object_id, NEW.target_object_version_id, so_t.object_type,
      sov_t.title, sov_t.version_no,
      NEW.created_by, NEW.created_at
    FROM relations r
    JOIN scientific_object_versions sov_s ON sov_s.id = NEW.source_object_version_id
    JOIN scientific_objects so_s ON so_s.id = sov_s.object_id
    JOIN scientific_object_versions sov_t ON sov_t.id = NEW.target_object_version_id
    JOIN scientific_objects so_t ON so_t.id = sov_t.object_id
    WHERE r.id = NEW.relation_id;
  END IF;
  RETURN NEW;
END;
$$;
-- +goose StatementEnd

CREATE TRIGGER relation_versions_provenance_projection
  AFTER INSERT ON relation_versions
  FOR EACH ROW EXECUTE FUNCTION provenance_edges_maintain();

-- rebuild_provenance_edges() restores the projection from canonical truth
-- (TRUNCATE + one INSERT SELECT). Concurrent writers are safe: the
-- TRUNCATE's ACCESS EXCLUSIVE lock makes the rebuild atomic for its
-- transaction, and rows inserted after it lands through the trigger.
-- +goose StatementBegin
CREATE FUNCTION rebuild_provenance_edges() RETURNS void
LANGUAGE plpgsql
AS $$
BEGIN
  TRUNCATE provenance_edges;
  INSERT INTO provenance_edges (
    project_id, relation_id, relation_version_id, relation_type,
    source_object_id, source_object_version_id, source_object_type,
    source_title, source_version_no,
    target_object_id, target_object_version_id, target_object_type,
    target_title, target_version_no,
    created_by, created_at)
  SELECT
    r.project_id, rv.relation_id, rv.id, rv.relation_type,
    sov_s.object_id, rv.source_object_version_id, so_s.object_type,
    sov_s.title, sov_s.version_no,
    sov_t.object_id, rv.target_object_version_id, so_t.object_type,
    sov_t.title, sov_t.version_no,
    rv.created_by, rv.created_at
  FROM relation_versions rv
  JOIN relations r ON r.id = rv.relation_id
  JOIN scientific_object_versions sov_s ON sov_s.id = rv.source_object_version_id
  JOIN scientific_objects so_s ON so_s.id = sov_s.object_id
  JOIN scientific_object_versions sov_t ON sov_t.id = rv.target_object_version_id
  JOIN scientific_objects so_t ON so_t.id = sov_t.object_id
  WHERE rv.relation_type = ANY(provenance_relation_types());
END;
$$;
-- +goose StatementEnd

-- Backfill: an upgraded database already holds relation versions — project
-- them now so the projection is complete the moment the migration lands.
SELECT rebuild_provenance_edges();


-- ===== 00045_external_reference_live_identity_and_snapshot.sql =====

-- External Reference live identity + snapshot guards (task T0508).
--
-- The 00011 tables already give the shape: external_references is the
-- LIVE identity (source_type + external_identifier UNIQUE, canonical_url)
-- and external_reference_snapshots is the pinned snapshot log
-- (accessed_at, upstream_version, metadata, snapshot_hash, blob_id),
-- already append-only via 00014/00015. What 00011 left open — and what
-- this migration closes for ANY write path (application code, psql, a
-- leaked credential), in the 00040 discipline — is four things:
--
--   1. THE IDENTITY IS LIVE. The identity row is synced from
--      external_reference scientific object payloads: whenever a version
--      of an external_reference object carries its identity pair
--      (source_type + external_identifier — the schema's required pair),
--      the identity row exists afterwards. One identity per normalized
--      pair, across all projects: every project citing the same DOI
--      shares one identity row (docs/19 §2). The upsert fills a missing
--      canonical_url but never overwrites an existing one (first writer
--      wins; the identity is the shared canonical fact).
--
--   2. IDENTIFIERS ARE NORMALIZED. DOI-shaped identifiers are
--      normalized before the unique pair is formed: the doi:/URL prefix
--      is stripped and the DOI is case-folded (DOI names are
--      case-insensitive, ISO 26324). Without this, "doi:10.1000/XYZ"
--      and "10.1000/xyz" would key two identities for one DOI. The Go
--      side is domain.NormalizeExternalIdentifier; the integration test
--      pins the SQL copy to the Go copy. Both copies trim and match
--      with the SAME explicit deterministic ASCII whitespace set
--      (SPACE TAB LF CR FF VT: Go spells it " \t\n\r\f\v", SQL spells
--      it E' \t\n\r\f\x0b' — E'' strings have no \v escape, so VT is
--      written \x0b) and therefore answer identically for identical
--      inputs. POSIX [[:space:]] and unicode-aware trimming are
--      deliberately NOT used on this surface: [[:space:]] is
--      locale-dependent, and the two copies must never disagree.
--
--   3. SNAPSHOTS CANNOT LIE. metadata must be a JSON object (a snapshot
--      of upstream metadata is a document, never a scalar); accessed_at
--      must not be in the future (it records when upstream WAS
--      observed); and snapshot_hash is derived from the stored metadata
--      bytes: a NULL hash is filled with the sha256 of the
--      jsonb-canonical metadata text, a supplied hash that does not
--      match is refused. The hash therefore always pins the bytes the
--      row actually holds — the same integrity contract as
--      scientific_object_versions.integrity_hash (docs/21 §10).
--
--   4. CITATION/DEPENDENCY IS THE ONLY ADMITTED EDGE. docs/19 §3: a
--      relation pointing AT an external reference is either "references"
--      (citation: background knowledge, upstream changes only notify) or
--      "depends_on" (dependency: actual input, upstream changes trigger
--      impact analysis). No other relation type may target an external
--      reference, and an external reference may never be a relation
--      SOURCE in V1 (relations are claims about the project's research;
--      a claim about what an external source says is an evidence
--      assertion, T0504's surface, not a relation). The two admitted
--      types are declared in external_reference_relation_types, kept in
--      lockstep with internal/rsg/relationcatalog by an integration
--      test.
--
-- PRECONDITION — DATABASE COLLATION. This database must be created with
-- a Unicode-aware collation (an initdb --locale other than C/POSIX, or
-- an explicit ICU/glibc Unicode collation). The identity normalization
-- case-folds with SQL lower(), and lower() folds non-ASCII characters
-- ('Ä' -> 'ä') ONLY under a Unicode-aware collation, while the Go copy
-- (strings.ToLower) folds Unicode unconditionally. On a C-collation
-- database the two copies would disagree on non-ASCII DOI spellings and
-- silently build two identity rows for one DOI. The integration test
-- TestExternalReferenceCollationPrecondition asserts the fold and FAILS
-- on a C-collation database, turning the mismatch from a silent
-- duplicate into a red build. Changing how databases are created
-- (infra/docker-compose, initdb parameters) is outside this migration's
-- scope.
--
-- Deliberately NOT enforced here (documented boundaries, not omissions):
--
--   * source_type enums: they are schema-governed scientific content,
--     validated by the schemareg/gate ladder per write; a DB CHECK would
--     couple every future schema enum change to a migration (the same
--     decision 00040 records for question_state/assessment).
--   * canonical_url shape: external_reference.schema.json declares
--     format: uri and says so itself — "this schema only constrains the
--     data shape". The DB guards enforce invariants (pairing,
--     normalization, hash integrity), never re-litigate schema shape;
--     dereferencing policy (https-only, SSRF guard) lives at FETCH time
--     in internal/rsg/externalref, the only place a URL is ever
--     dereferenced.
--   * snapshot presence on citation: whether a citation must pin a
--     snapshot before it may exist is a product-semantics decision
--     (docs/19 §2 says a snapshot is kept "when the project actually
--     references it" — the refresh flow records it, it is not a
--     citation precondition in V1). Left unenforced.
--   * which projects may share/see an identity: external_references
--     carries no project scope by design (00011 shape); the snapshot
--     READ model and its visibility belong to the consuming API task.
--   * the identity row itself is NOT append-only: it is live state by
--     definition (docs/19 §2), and refresh may fill its canonical_url.
--     History lives in the snapshots, and those ARE append-only.
--   * identity-row visibility timing: identity rows are written by a
--     DEFERRABLE INITIALLY DEFERRED constraint trigger, which fires at
--     the writing transaction's COMMIT — until then the row is invisible
--     to every transaction, the writer's own snapshot included.
--     Consumers that key on an identity row must re-read after commit;
--     the read-model consequences are the consuming API task's to design
--     (T0509, Issue #175).

-- ---------------------------------------------------------------------------
-- Identifier normalization (SQL copy of domain.NormalizeExternalIdentifier)
-- ---------------------------------------------------------------------------

-- The explicit deterministic ASCII whitespace set shared by every trim
-- and match on this migration's identity/snapshot surface: SPACE, TAB,
-- LF, CR, FF, VT. The Go copies (domain.ASCIIWhitespace, the doiShape
-- bracket classes) spell the same set as " \t\n\r\f\v"; SQL spells VT
-- as \x0b because E'' strings have no \v escape (E'\v' is the literal
-- character 'v', which would silently admit 'v' into the class). POSIX
-- [[:space:]] is deliberately NOT used: it is locale-dependent and
-- includes characters outside this set. The integration drift test feeds
-- the same inputs to both copies and asserts equality one by one — any
-- divergence fails there.
-- +goose StatementBegin
CREATE FUNCTION external_reference_trim(v text)
RETURNS text
LANGUAGE sql
IMMUTABLE
AS $$
  SELECT btrim(v, E' \t\n\r\f\x0b');
$$;
-- +goose StatementEnd

-- +goose StatementBegin
CREATE FUNCTION external_reference_normalize_identifier(identifier text)
RETURNS text
LANGUAGE sql
IMMUTABLE
AS $$
  SELECT CASE
    WHEN trimmed ~* E'^(https?://(dx\.)?doi\.org/|doi:[ \t\n\r\f\x0b]*)?10\.[0-9]{4,9}/[^ \t\n\r\f\x0b]+$'
      THEN lower(substring(trimmed FROM E'10\.[0-9]{4,9}/[^ \t\n\r\f\x0b]+$'))
    ELSE trimmed
  END
  FROM (SELECT external_reference_trim(identifier) AS trimmed) t;
$$;
-- +goose StatementEnd

-- ---------------------------------------------------------------------------
-- Live identity: validation + normalization on write
-- ---------------------------------------------------------------------------

-- +goose StatementBegin
CREATE FUNCTION external_references_identity_guard() RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  IF NEW.source_type IS NULL OR external_reference_trim(NEW.source_type) = '' THEN
    RAISE EXCEPTION 'external reference identity: source_type must not be empty'
      USING ERRCODE = 'P0001';
  END IF;
  IF NEW.external_identifier IS NULL OR external_reference_trim(NEW.external_identifier) = '' THEN
    RAISE EXCEPTION 'external reference identity: external_identifier must not be empty'
      USING ERRCODE = 'P0001';
  END IF;
  NEW.external_identifier := external_reference_normalize_identifier(NEW.external_identifier);
  -- The row stores the TRIMMED spelling, not the caller's: without this,
  -- a direct INSERT of ' publication ' would create a SECOND identity
  -- row keyed by the whitespace-wrapped value while the clean spelling
  -- keys the first — one DOI, two identities. The value is trimmed, not
  -- normalized further: source_type is a schema enum, and the enum values
  -- themselves are the gate ladder's business (see the header).
  NEW.source_type := external_reference_trim(NEW.source_type);
  RETURN NEW;
END;
$$;
-- +goose StatementEnd

CREATE TRIGGER external_references_identity_guard
  BEFORE INSERT OR UPDATE ON external_references
  FOR EACH ROW EXECUTE FUNCTION external_references_identity_guard();

-- ---------------------------------------------------------------------------
-- Live identity: sync from external_reference object payloads
-- ---------------------------------------------------------------------------

-- +goose StatementBegin
CREATE FUNCTION external_reference_identity_sync() RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
  obj_type text;
  src_type text;
  ext_id text;
  canon_url text;
BEGIN
  SELECT object_type INTO obj_type
    FROM scientific_objects WHERE id = NEW.object_id;
  IF NOT FOUND THEN
    -- Cannot happen through the FK; guard against misleading errors.
    RETURN NEW;
  END IF;
  IF obj_type <> 'external_reference' THEN
    RETURN NEW;
  END IF;

  -- Absent (or JSON null, or blank) means "no identity yet": a draft
  -- external reference may not know its identifier, and the gate ladder
  -- decides whether that omission is acceptable at this point. The
  -- pairing rule is identical in BOTH worlds (Go and SQL): both sides
  -- absent or blank is a valid draft, and a HALF-given pair — one side
  -- present, the other absent or blank — is a hard error. The
  -- application-level semantic checks (semantics.checkExternalReference)
  -- refuse the half-given pair before the write; this trigger refuses it
  -- for every other write path.
  src_type := NULLIF(external_reference_trim(NEW.payload->>'source_type'), '');
  ext_id := NULLIF(external_reference_trim(NEW.payload->>'external_identifier'), '');

  IF src_type IS NULL AND ext_id IS NULL THEN
    RETURN NEW;
  END IF;
  IF src_type IS NULL OR ext_id IS NULL THEN
    RAISE EXCEPTION 'external_reference object %: source_type and external_identifier must be given together (got source_type=%, external_identifier=%)',
      NEW.object_id, src_type, ext_id
      USING ERRCODE = 'P0001';
  END IF;

  canon_url := NEW.payload->>'canonical_url';
  IF canon_url IS NOT NULL AND external_reference_trim(canon_url) = '' THEN
    canon_url := NULL;
  END IF;

  -- One identity per normalized pair across all projects. The upsert
  -- fills a missing canonical_url from the first object that names it;
  -- an existing canonical_url is never overwritten by a later object.
  INSERT INTO external_references (source_type, external_identifier, canonical_url)
  VALUES (src_type, ext_id, canon_url)
  ON CONFLICT (source_type, external_identifier) DO UPDATE
     SET canonical_url = COALESCE(external_references.canonical_url, EXCLUDED.canonical_url);
  RETURN NEW;
END;
$$;
-- +goose StatementEnd

CREATE CONSTRAINT TRIGGER scientific_object_versions_external_reference_identity
  AFTER INSERT ON scientific_object_versions
  DEFERRABLE INITIALLY DEFERRED
  FOR EACH ROW EXECUTE FUNCTION external_reference_identity_sync();

-- ---------------------------------------------------------------------------
-- Snapshots: metadata shape, accessed_at, derived hash
-- ---------------------------------------------------------------------------

-- snapshot_hash becomes derivable: NULL means "derive it server-side".
-- A supplied non-NULL hash is verified against the stored metadata bytes.
ALTER TABLE external_reference_snapshots
  ALTER COLUMN snapshot_hash DROP NOT NULL;

-- +goose StatementBegin
CREATE FUNCTION external_reference_snapshots_guard() RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
  derived text;
BEGIN
  IF jsonb_typeof(NEW.metadata) IS DISTINCT FROM 'object' THEN
    RAISE EXCEPTION 'external reference snapshot %: metadata must be a JSON object (got %)',
      NEW.id, jsonb_typeof(NEW.metadata)
      USING ERRCODE = 'P0001';
  END IF;
  -- clock_timestamp() is the actual current time: an observation stamped
  -- by the application's clock inside a long transaction must land, and
  -- now() would refuse it — now() is the TRANSACTION start, so any
  -- observation written after the transaction began compares as "future".
  -- The tolerance is zero in both directions: any stamp ahead of the
  -- database's actual clock is still refused, full stop.
  IF NEW.accessed_at IS NULL OR NEW.accessed_at > clock_timestamp() THEN
    RAISE EXCEPTION 'external reference snapshot %: accessed_at % records a future access',
      NEW.id, NEW.accessed_at
      USING ERRCODE = 'P0001';
  END IF;
  IF NEW.upstream_version IS NOT NULL AND external_reference_trim(NEW.upstream_version) = '' THEN
    RAISE EXCEPTION 'external reference snapshot %: upstream_version must not be empty when present',
      NEW.id
      USING ERRCODE = 'P0001';
  END IF;

  -- The hash pins the bytes the row actually holds: sha256 of the
  -- jsonb-canonical metadata text (jsonb normalizes key order and
  -- whitespace, so the digest is a stable function of the stored
  -- document — the same integrity contract as the object version
  -- payload hash, docs/21 §10). NULL derives; a supplied hash that
  -- disagrees is refused rather than silently rewritten, so a caller
  -- can never assert a hash the row does not have.
  derived := encode(digest(NEW.metadata::text, 'sha256'), 'hex');
  IF NEW.snapshot_hash IS NULL THEN
    NEW.snapshot_hash := derived;
  ELSIF NEW.snapshot_hash <> derived THEN
    RAISE EXCEPTION 'external reference snapshot %: snapshot_hash % does not match the stored metadata (sha256 is %)',
      NEW.id, NEW.snapshot_hash, derived
      USING ERRCODE = 'P0001';
  END IF;
  RETURN NEW;
END;
$$;
-- +goose StatementEnd

CREATE TRIGGER external_reference_snapshots_guard
  BEFORE INSERT ON external_reference_snapshots
  FOR EACH ROW EXECUTE FUNCTION external_reference_snapshots_guard();

-- The snapshot log is read per identity; 00011 never indexed the FK.
CREATE INDEX external_reference_snapshots_ref_idx
  ON external_reference_snapshots (external_reference_id);

-- ---------------------------------------------------------------------------
-- Citation/dependency endpoint admission
-- ---------------------------------------------------------------------------

-- The relation types that may point AT an external reference (docs/19
-- §3). The Go relation catalog declares the same set
-- (relationcatalog.ExternalRefTargetTypes); an integration test pins the
-- two copies together. Relations whose type is not declared here are
-- untouched — the catalog remains the authority on which relation types
-- exist, and the guard below only polices edges whose target IS an
-- external reference.
CREATE TABLE external_reference_relation_types (
  relation_type text PRIMARY KEY
);

INSERT INTO external_reference_relation_types (relation_type) VALUES
  ('references'),
  ('depends_on');

-- The policy set is SEALED: no ordinary write path may change which
-- relation types are admitted — a write path that could INSERT 'contains'
-- here would silently rewrite the citation/dependency policy of docs/19
-- §3 past the endpoint guard below. The set may only change through a
-- FUTURE MIGRATION that deliberately drops the seal first:
--   DROP TRIGGER external_reference_relation_types_seal
--     ON external_reference_relation_types;
-- change the rows, then re-create the trigger with the exact CREATE
-- TRIGGER statement below — and update the Go catalog
-- (relationcatalog.ExternalRefTargetTypes) and the drift test in the
-- same change, because the integration test pins the table to the
-- catalog.
-- +goose StatementBegin
CREATE FUNCTION external_reference_relation_types_seal() RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  RAISE EXCEPTION 'external_reference_relation_types is a sealed policy table: drop trigger external_reference_relation_types_seal in a migration, change the rows, then re-create it'
    USING ERRCODE = 'P0001';
END;
$$;
-- +goose StatementEnd

CREATE TRIGGER external_reference_relation_types_seal
  BEFORE INSERT OR UPDATE OR DELETE ON external_reference_relation_types
  FOR EACH ROW EXECUTE FUNCTION external_reference_relation_types_seal();

-- +goose StatementBegin
CREATE FUNCTION external_reference_relation_endpoint_guard() RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
  rel_project uuid;
  src_type text;
  tgt_type text;
  tgt_project uuid;
  admitted boolean;
BEGIN
  SELECT so.object_type INTO src_type
    FROM scientific_object_versions sov
    JOIN scientific_objects so ON so.id = sov.object_id
   WHERE sov.id = NEW.source_object_version_id;
  IF NOT FOUND THEN
    RETURN NEW; -- the endpoint FKs police missing versions
  END IF;
  SELECT so.object_type, so.project_id INTO tgt_type, tgt_project
    FROM scientific_object_versions sov
    JOIN scientific_objects so ON so.id = sov.object_id
   WHERE sov.id = NEW.target_object_version_id;
  IF NOT FOUND THEN
    RETURN NEW;
  END IF;

  IF src_type = 'external_reference' THEN
    RAISE EXCEPTION 'relation %: an external_reference object may not be a relation source in V1 (claims about external sources are evidence assertions, not relations)',
      NEW.relation_type
      USING ERRCODE = 'P0001';
  END IF;
  IF tgt_type <> 'external_reference' THEN
    RETURN NEW; -- edges between ordinary objects are not this guard's business
  END IF;

  SELECT true INTO admitted
    FROM external_reference_relation_types
   WHERE relation_type = NEW.relation_type;
  IF admitted IS NULL THEN
    RAISE EXCEPTION 'relation %: the only types that may target an external reference are references (citation) and depends_on (dependency)',
      NEW.relation_type
      USING ERRCODE = 'P0001';
  END IF;

  -- The external reference object the edge points at must live in the
  -- relation's project: a citation is a claim about the project's
  -- research (the same same-project rule the 00040 knowledge guard
  -- enforces).
  SELECT project_id INTO rel_project FROM relations WHERE id = NEW.relation_id;
  IF tgt_project IS DISTINCT FROM rel_project THEN
    RAISE EXCEPTION 'relation %: target external_reference object belongs to a different project',
      NEW.relation_type
      USING ERRCODE = 'P0001';
  END IF;
  RETURN NEW;
END;
$$;
-- +goose StatementEnd

CREATE CONSTRAINT TRIGGER relation_versions_external_reference_endpoints
  AFTER INSERT ON relation_versions
  DEFERRABLE INITIALLY DEFERRED
  FOR EACH ROW EXECUTE FUNCTION external_reference_relation_endpoint_guard();


-- ===== 00046_outbox_idempotent_publish.sql =====

-- Transactional outbox publish (T1001): the domain writes outbox_events in
-- the same transaction as its state change (docs/53, ADR-013), and the
-- worker publishes each pending row into research_events — the append-only
-- domain event log (00014-guarded). Two gaps close here:
--
--   1. Envelope columns: the published research_event needs actor_id,
--      project_id and visibility, and the publisher must copy them from
--      the outbox row, never re-derive them from the payload (a private
--      event must not be publishable as a public one). event_type,
--      correlation_id and payload exist since 00012. visibility defaults
--      to 'private' — fail closed — so rows written before this migration
--      publish at the least visible level, and an explicit value is the
--      only way an event becomes public.
--
--   2. Idempotent publish (the acceptance criterion: crash/retry
--      不丢事件不重复副作用): the publisher inserts the research_event
--      and marks the outbox row published in ONE transaction, and a crash
--      between the two must not produce a second research_event on retry.
--      research_events.outbox_event_id pins the outbox row each event came
--      from, and the partial unique index below makes the retried insert a
--      no-op (INSERT ... ON CONFLICT DO NOTHING). The index is partial
--      because direct research_events writes (no outbox row) stay legal:
--      NULL is never a conflict, and outbox-published rows are always
--      non-NULL.
--
--   3. Failure record: last_error carries why the last publish attempt
--      failed. Rows are retried forever — no event may be silently lost
--      (docs/26 §2 alerts on outbox backlog) — and the recorded error is
--      how an operator sees a stuck row.

ALTER TABLE outbox_events
  ADD COLUMN actor_id uuid REFERENCES users(id) ON DELETE RESTRICT,
  ADD COLUMN project_id uuid REFERENCES projects(id) ON DELETE RESTRICT,
  ADD COLUMN visibility text NOT NULL DEFAULT 'private',
  ADD COLUMN last_error text;

COMMENT ON COLUMN outbox_events.visibility IS
  'The event''s visibility preset, copied verbatim into the published research_event: public or private (docs/12 — an event is never more visible than its subject). ''private'' is the fail-closed default for rows written before this migration; the outbox recorder always sets an explicit value.';

COMMENT ON COLUMN outbox_events.last_error IS
  'Why the last publish attempt failed, when it did (T1001): a row whose publish fails is retried forever, and this column is the operator''s window onto a stuck row (docs/26 §2 outbox backlog alerting). NULL while never attempted or after a successful publish.';

ALTER TABLE research_events
  ADD COLUMN outbox_event_id uuid REFERENCES outbox_events(id) ON DELETE RESTRICT;

COMMENT ON COLUMN research_events.outbox_event_id IS
  'The outbox row this event was published from (T1001). The partial unique index research_events_outbox_event_uniq makes the publish step idempotent: a retried publish after a crash between the insert and the published-mark is a no-op. NULL for research events written directly, bypassing the outbox.';

-- The publish dedupe: one research_event per outbox row, ever.
CREATE UNIQUE INDEX research_events_outbox_event_uniq
  ON research_events (outbox_event_id)
  WHERE outbox_event_id IS NOT NULL;

-- The publisher's backlog scan (WHERE published_at IS NULL, ordered by
-- created_at, id): only pending rows enter the index, so the scan stays
-- small no matter how long the published history grows.
CREATE INDEX outbox_events_pending_idx
  ON outbox_events (created_at, id)
  WHERE published_at IS NULL;


-- ===== 00047_git_reconciliation.sql =====

-- Git ↔ RSG reconciliation (T0309): the periodic drift check's canonical
-- record — one run row per verification pass, one append-only finding row
-- per drift instance, and one audit_log row per NEW finding (docs/16 §5:
-- every accepted state commit saves git commit/ref + rsg state hash; the
-- background reconciliation job checks drift; ANY drift is a high-severity
-- operational alert).
--
-- The reconciler (internal/gitprovider) verifies three dimensions per
-- pass:
--
--   branch ref  — a synced mapping row's provider ref must exist and its
--                 head must equal git_branch_refs.head_sha; a closed
--                 row's ref must be gone; a provider ref no branch row
--                 names must not exist (unmapped).
--   state hash  — every project_states row with a git_commit_sha must
--                 carry state_hash = GitStateHash(git_commit_sha) (the
--                 T0305-derived identity: the state's hash is a pure
--                 function of its pinned commit).
--   mapping     — the trigger-maintained invariants re-verified: 1:1
--                 branch ↔ git_branch_refs, the derived git_ref, the
--                 provision row of every provisioned project, and the
--                 provider repository behind every provision row.
--
-- The reconciler NEVER repairs: each finding carries a repair_proposal
-- (jsonb, the exact action a repair would take) and applies nothing —
-- the acceptance criterion "repair proposal 不静默修". A finding is
-- deduplicated while open (one open finding per kind+project+subject, the
-- partial unique index below), resolved by the pass that observes the
-- drift gone, and a RECURRING drift after resolution is a NEW finding (a
-- resolved row never reopens — the guard below). New findings append an
-- audit row (via='system', action='git.reconciliation.drift_detected',
-- severity 'high' in metadata) in the same transaction, so drift is
-- visible on the project's Activity feed without a new read surface.

CREATE TABLE git_reconciliation_runs (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  -- A pass opens its run row up front (started_at) and fills the counts
  -- at the end (finished_at). A crashed or failed pass leaves the row
  -- unfinished — visible evidence that a pass did not complete, never a
  -- silently absent check.
  started_at timestamptz NOT NULL DEFAULT now(),
  finished_at timestamptz,
  refs_checked integer NOT NULL DEFAULT 0,
  states_checked integer NOT NULL DEFAULT 0,
  -- The broken mapping invariants the pass FOUND (checkMappings): one per
  -- violation row the canonical-side check returned — problems found, not
  -- points checked.
  mapping_violations integer NOT NULL DEFAULT 0,
  -- The provisioned repositories whose existence the pass VERIFIED
  -- (checkProvider): one per present repository — points checked, not
  -- problems found. A missing repository is a repository_missing finding,
  -- it is not counted here.
  repositories_checked integer NOT NULL DEFAULT 0,
  findings_opened integer NOT NULL DEFAULT 0,
  findings_open integer NOT NULL DEFAULT 0,
  findings_resolved integer NOT NULL DEFAULT 0,
  -- The provider failure that aborted the provider-side checks of this
  -- pass, when one did (redacted by construction — the adapter errors
  -- never carry the token or the configured URLs). Canonical-store checks
  -- still run and their findings still land; provider-side findings are
  -- neither created (a down provider would look like every ref missing —
  -- false findings) nor resolved (they were not re-verified).
  provider_error text
);

COMMENT ON TABLE git_reconciliation_runs IS
  'One row per Git ↔ RSG reconciliation pass (T0309): the pass''s scope counts and its outcome. The row is the reconciler''s own bookkeeping — opened at pass start, updated (never deleted) at pass end; a pass that crashed or failed stays unfinished, so a missing check is visible.';

CREATE TABLE git_reconciliation_findings (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  run_id uuid NOT NULL REFERENCES git_reconciliation_runs(id) ON DELETE RESTRICT,
  project_id uuid NOT NULL REFERENCES projects(id) ON DELETE RESTRICT,
  kind text NOT NULL CHECK (kind IN ('ref_missing','ref_head_moved','dangling_ref','unmapped_ref','repository_missing','state_hash_mismatch','mapping_violation')),
  -- Every drift is high-severity by product rule (docs/16 §5) — the
  -- check pins the rule at the storage layer, the same discipline as
  -- 00031's guards.
  severity text NOT NULL DEFAULT 'high' CHECK (severity = 'high'),
  -- The stable subject of the finding: the git ref for ref findings, the
  -- state id for state-hash findings, the branch id for branch-mapping
  -- violations, "<owner>/<name>" for repository findings. The dedupe key
  -- below keeps at most one OPEN finding per (kind, project, subject).
  subject_ref text NOT NULL,
  -- The observed facts (expected vs actual) — per kind, stable field
  -- names so operators can read the finding without code.
  detail jsonb NOT NULL,
  -- What a repair WOULD do — an exact action (enqueue the branch-ref
  -- sync, record the unrecorded push, restore the derived state hash,
  -- re-provision), never applied by the reconciler. For findings whose
  -- repair is a semantic decision (an unmapped ref: adopt into the RSG
  -- or delete), the proposal names the options instead of choosing.
  repair_proposal jsonb NOT NULL,
  status text NOT NULL DEFAULT 'open' CHECK (status IN ('open','resolved')),
  created_at timestamptz NOT NULL DEFAULT now(),
  resolved_at timestamptz
);

COMMENT ON TABLE git_reconciliation_findings IS
  'One row per Git ↔ RSG drift instance (T0309): what drifted, the observed facts, the repair proposal that is NOT applied, and the finding''s lifecycle. Open findings dedupe per (kind, project, subject); a resolved finding stays resolved (the guard) and a recurring drift is a new row. Append-only except the status transition, and never deleted.';

-- One open finding per (kind, project, subject): the pass that observes a
-- drift again re-uses the open finding (no alert spam), and the pass that
-- observes it gone resolves it. The index doubles as the dedupe lookup.
CREATE UNIQUE INDEX git_reconciliation_findings_open_dedupe_idx
  ON git_reconciliation_findings (kind, project_id, subject_ref)
  WHERE status = 'open';

-- The finding lifecycle guard: rows are facts of their run — only the
-- status may transition, forward only (open → resolved), and a resolved
-- finding never reopens (a recurring drift is a new row, so each drift
-- episode keeps its own resolved_at). The resolved_at bookkeeping is
-- maintained here for ANY update path, like 00031's guards.
-- +goose StatementBegin
CREATE FUNCTION git_reconciliation_finding_guard() RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'git_reconciliation_findings rows are never deleted: a drift finding is a fact of its run'
      USING ERRCODE = 'P0001';
  END IF;
  IF NEW.id IS DISTINCT FROM OLD.id
     OR NEW.run_id IS DISTINCT FROM OLD.run_id
     OR NEW.project_id IS DISTINCT FROM OLD.project_id
     OR NEW.kind IS DISTINCT FROM OLD.kind
     OR NEW.severity IS DISTINCT FROM OLD.severity
     OR NEW.subject_ref IS DISTINCT FROM OLD.subject_ref
     OR NEW.detail IS DISTINCT FROM OLD.detail
     OR NEW.repair_proposal IS DISTINCT FROM OLD.repair_proposal THEN
    RAISE EXCEPTION 'git_reconciliation_findings content is immutable: only the status transitions'
      USING ERRCODE = 'P0001';
  END IF;
  IF OLD.status = 'resolved' AND NEW.status <> 'resolved' THEN
    RAISE EXCEPTION 'a resolved finding never reopens: a recurring drift is a new finding'
      USING ERRCODE = 'P0001';
  END IF;
  IF NEW.status = 'open' AND NEW.resolved_at IS NOT NULL THEN
    RAISE EXCEPTION 'an open finding has no resolved_at'
      USING ERRCODE = 'P0001';
  END IF;
  IF NEW.status = 'resolved' AND NEW.resolved_at IS NULL THEN
    NEW.resolved_at = now();
  END IF;
  RETURN NEW;
END;
$$;
-- +goose StatementEnd

CREATE TRIGGER git_reconciliation_finding_guard_trigger
  BEFORE UPDATE OR DELETE ON git_reconciliation_findings
  FOR EACH ROW EXECUTE FUNCTION git_reconciliation_finding_guard();

-- The TRUNCATE halves (00015's discipline: row triggers do not fire on
-- TRUNCATE) — the drift history is history, not even wholesale erasure is
-- a legal update path. Runs are the reconciler's bookkeeping and are
-- updatable by design (the pass fills its counts), but a pass history is
-- still not truncated away.
CREATE TRIGGER git_reconciliation_findings_no_truncate
  BEFORE TRUNCATE ON git_reconciliation_findings FOR EACH STATEMENT
  EXECUTE FUNCTION append_only_guard();

CREATE TRIGGER git_reconciliation_runs_no_truncate
  BEFORE TRUNCATE ON git_reconciliation_runs FOR EACH STATEMENT
  EXECUTE FUNCTION append_only_guard();


-- ===== 00051_pull_request_state_and_fixity.sql =====

-- Pull request state machine and fixity invariants (task T0402).
--
-- The pull_requests row is a proposal whose address is its identity:
-- docs/09 §4 ("PR 包含：source/target branch、base state、RSG diff、…")
-- and docs/43 ("open → review_required → changes_requested/approved →
-- merge_ready → merged；也可 closed/aborted"). Three families of
-- invariants, enforced by the database itself for ANY update path —
-- application code, psql, a leaked credential — with the one stated
-- exception at the end of this header (the proposed-state gate):
--
--   1. state vocabulary: the CHECK names the canonical PR states; no
--      invalid state is storable;
--   2. lifecycle: pull_request_guard enforces the docs/43 transition
--      map — a terminal PR (merged/closed/aborted) never moves again,
--      the machine cannot be skipped (open → merged is refused at the
--      database), and merged_at is consistent (set on merged, cleared
--      only by leaving merged — which the map itself forbids);
--   3. fixity: the PR's base and proposed states are FIXED (task
--      requirement "base/proposed state fixed"). project, number and
--      the branch pair are structural identity and immutable too.
--      base_state_id never changes — the acceptance "PR base 不随 main
--      漂移" holds even against code that would re-read the target
--      branch's head. proposed_state_id moves ONLY through the explicit
--      head refresh: the transaction-scoped session flag
--      post.pr_head_refresh='on' (set by the refresh adapter path, and
--      only there) — the acceptance "head update 可显式 refresh", and
--      exactly one sanctioned write path for it.
--
-- Scope of the proposed-state gate, stated precisely: the flag blocks
-- IMPLICIT or accidental writes by application code — a rogue UPDATE
-- without the flag fails, and no query in this schema sets the flag.
-- It is NOT a defense against hostile or leaked SQL credentials: any
-- session with UPDATE privilege on pull_requests can run
-- set_config('post.pr_head_refresh','on',true) itself and move the
-- proposed state. Everything else in this migration (the CHECK, the
-- transition map, identity/base immutability, merged_at consistency)
-- is unconditional and holds even against such a session.
--
-- pull_requests is deliberately NOT covered by the append-only guards of
-- 00014: it is a mutable row by design (state, proposed head, merged_at).
-- This is the targeted constraint instead, the same discipline as 00028's
-- branch lifecycle guard. No existing constraint is changed or dropped;
-- no column semantics are added (rows exist only with state='open',
-- which the CHECK admits).

ALTER TABLE pull_requests ADD CONSTRAINT pull_requests_state_check
  CHECK (state IN ('open','review_required','changes_requested','approved',
                   'merge_ready','merged','closed','aborted'));

-- +goose StatementBegin
CREATE FUNCTION pull_request_guard() RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
  valid_transition boolean;
BEGIN
  IF TG_OP = 'UPDATE' THEN
    -- Structural identity and the fixed base: immutable for the row's
    -- lifetime. The base state is pinned at creation and must not drift
    -- with the target branch's later heads.
    IF NEW.project_id IS DISTINCT FROM OLD.project_id
       OR NEW.number IS DISTINCT FROM OLD.number
       OR NEW.source_branch_id IS DISTINCT FROM OLD.source_branch_id
       OR NEW.target_branch_id IS DISTINCT FROM OLD.target_branch_id
       OR NEW.base_state_id IS DISTINCT FROM OLD.base_state_id THEN
      RAISE EXCEPTION 'pull request identity is fixed: project, number, branches and base state are immutable (docs/09 §4)'
        USING ERRCODE = 'P0001';
    END IF;
    -- The proposed head moves only through the explicit head refresh,
    -- and never on a terminal PR.
    IF NEW.proposed_state_id IS DISTINCT FROM OLD.proposed_state_id THEN
      IF OLD.state IN ('merged','closed','aborted') THEN
        RAISE EXCEPTION 'a terminal pull request never moves: the proposed state is fixed on a % PR (docs/43)',
          OLD.state
          USING ERRCODE = 'P0001';
      END IF;
      IF coalesce(current_setting('post.pr_head_refresh', true), '') <> 'on' THEN
        RAISE EXCEPTION 'pull request head moves only through the explicit head refresh (T0402)'
          USING ERRCODE = 'P0001';
      END IF;
    END IF;
    -- The docs/43 transition map: the machine cannot be skipped and a
    -- terminal state never moves again. The application's
    -- compare-and-swap is the normal path; this is the backstop.
    IF NEW.state IS DISTINCT FROM OLD.state THEN
      valid_transition :=
        (OLD.state = 'open' AND NEW.state IN ('review_required','closed','aborted'))
        OR (OLD.state = 'review_required' AND NEW.state IN ('changes_requested','approved','closed','aborted'))
        OR (OLD.state = 'changes_requested' AND NEW.state IN ('review_required','closed','aborted'))
        OR (OLD.state = 'approved' AND NEW.state IN ('merge_ready','closed','aborted'))
        OR (OLD.state = 'merge_ready' AND NEW.state IN ('merged','closed','aborted'));
      IF NOT valid_transition THEN
        RAISE EXCEPTION 'illegal pull request state transition: % -> % (docs/43)',
          OLD.state, NEW.state
          USING ERRCODE = 'P0001';
      END IF;
    END IF;
  END IF;
  -- merged_at consistency: only a merged PR carries a merge timestamp;
  -- reaching merged stamps it (any path gets consistent data).
  IF NEW.state = 'merged' AND NEW.merged_at IS NULL THEN
    NEW.merged_at = now();
  ELSIF NEW.state <> 'merged' AND NEW.merged_at IS NOT NULL THEN
    RAISE EXCEPTION 'merged_at is only set on a merged pull request (state %)', NEW.state
      USING ERRCODE = 'P0001';
  END IF;
  RETURN NEW;
END;
$$;
-- +goose StatementEnd

CREATE TRIGGER pull_request_guard_trigger
  BEFORE INSERT OR UPDATE ON pull_requests
  FOR EACH ROW EXECUTE FUNCTION pull_request_guard();


-- ===== 00053_release_governance.sql =====

-- Immutable release governance (T0606): the release row is a complete,
-- self-contained snapshot — the full manifest document, never a join over
-- live state (an old release must render identically no matter how the
-- current state evolves, acceptance: 旧 release 不受 current state 改变).
--
-- The manifest column becomes text: the document is content-addressed —
-- manifest_hash is the sha256 of the canonical bytes, and the export is
-- served verbatim from the stored row. jsonb normalizes key order and
-- whitespace, so the stored bytes would no longer be the bytes the hash
-- was computed over and verification could never close (found by the
-- T0606 e2e: the manifest endpoint 503'd on VerifyHash after the jsonb
-- round trip reordered the nested documents). A byte-preserving column
-- type is the whole point of an immutable snapshot.
--
-- The release manifest pins TWO policy versions (docs/11 §1: the
-- organization lower bound and the project's stricter overlay, docs/12
-- §5); the canonical releases table carried one policy_version_id (the
-- project policy), so the organization pin gets its own column.
--
-- release_creations is the Idempotency-Key ledger (docs/22: an
-- Idempotency-Key governs create/command/publish/merge/release): a key
-- replays the release it created, forever. Append-only like the release
-- itself — a replay is a read, never a rewrite (migration 00014's guard
-- covers releases already; the ledger gets the same treatment, both
-- halves: the 00014 row guard and the 00015 TRUNCATE guard).
--
-- The list index orders a project's releases newest-first without a
-- sort; UNIQUE(project_id, version) keeps the same-version conflict a
-- database guarantee, never a check-then-insert race.

ALTER TABLE releases
  ALTER COLUMN manifest TYPE text USING manifest::text;

ALTER TABLE releases
  ADD COLUMN org_policy_version_id uuid REFERENCES policy_versions(id) ON DELETE RESTRICT;

CREATE TABLE release_creations (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  project_id uuid NOT NULL REFERENCES projects(id) ON DELETE RESTRICT,
  idempotency_key text NOT NULL,
  release_id uuid NOT NULL REFERENCES releases(id) ON DELETE RESTRICT,
  created_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE(project_id, idempotency_key)
);

CREATE TRIGGER release_creations_append_only
  BEFORE UPDATE OR DELETE ON release_creations
  FOR EACH ROW EXECUTE FUNCTION append_only_guard();

CREATE TRIGGER release_creations_no_truncate
  BEFORE TRUNCATE ON release_creations FOR EACH STATEMENT
  EXECUTE FUNCTION append_only_guard();

CREATE INDEX releases_project_created_idx
  ON releases(project_id, created_at DESC);


-- ===== 00054_conflict_resolutions.sql =====

-- Conflict resolutions (T0407): the human decisions the Scientific
-- Conflict Resolution UI records for the three-way state triple
-- (base/source/target) one semantic merge is computed over (docs/09 §8:
-- Accept A / Accept B / Keep both versions / Create validation branch /
-- Scientific conflict 可在 main 中保持 contested/unresolved).
--
-- One row is one decision on one classified conflict of the detector
-- report (internal/rsg/conflict, T0405). The conflict identity is the
-- full classifier key — target kind + id, the conflict code, the fields
-- and payload keys the conflict covers and (identity conflicts) the
-- paired object — so a decision can never be mistaken for a decision on
-- a different conflict, even after the detector's classification
-- vocabulary grows. The triple's three states are pinned: a decision
-- stays bound to the exact states it was made about.
--
-- Decisions are overwritten in place (the latest decision wins, decided_by/
-- decided_at move); the overwrite itself is audit-logged by the store,
-- so no decision change disappears silently. There is no DELETE path —
-- an undecided conflict simply has no row; `unresolved` is an explicit
-- decision, not the absence of one.
CREATE TABLE conflict_resolutions (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  project_id uuid NOT NULL REFERENCES projects(id) ON DELETE RESTRICT,
  base_state_id uuid NOT NULL REFERENCES project_states(id) ON DELETE RESTRICT,
  source_state_id uuid NOT NULL REFERENCES project_states(id) ON DELETE RESTRICT,
  target_state_id uuid NOT NULL REFERENCES project_states(id) ON DELETE RESTRICT,
  -- The conflict identity this decision addresses. target_id is the
  -- object id for object conflicts and the relation id for relation
  -- conflicts (the domain rows, not the version rows).
  target_kind text NOT NULL CHECK (target_kind IN ('object','relation')),
  target_id uuid NOT NULL,
  conflict_code text NOT NULL,
  conflict_fields jsonb NOT NULL DEFAULT '[]'::jsonb,
  conflict_payload_keys jsonb NOT NULL DEFAULT '[]'::jsonb,
  conflict_other_object_id uuid,
  -- The human decision. No computed outcome exists: the merge engine
  -- (T0406) executes exactly the kind chosen, and no kind averages or
  -- derives parameters (docs/09 §7: Protocol 冲突数值折中禁止自动).
  resolution text NOT NULL CHECK (resolution IN ('accept_source','accept_target','keep_both','validation_branch','unresolved')),
  -- The free-form reasoning the decider attaches (e.g. the name they
  -- propose for a validation branch).
  note text NOT NULL DEFAULT '',
  decided_by uuid NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
  decided_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);

-- One decision per conflict identity per triple. NULLS NOT DISTINCT:
-- a conflict without a paired object (conflict_other_object_id NULL) is
-- still one identity — the default NULLS DISTINCT would let two rows for
-- the same NULL key accumulate and the overwrite would append instead of
-- replace.
CREATE UNIQUE INDEX conflict_resolutions_identity_idx ON conflict_resolutions
  (project_id, base_state_id, source_state_id, target_state_id,
   target_kind, target_id, conflict_code, conflict_fields,
   conflict_payload_keys, conflict_other_object_id) NULLS NOT DISTINCT;

-- The plan read: every decision of one triple, ordered for stable
-- rendering.
CREATE INDEX conflict_resolutions_plan_idx
  ON conflict_resolutions (project_id, base_state_id, source_state_id, target_state_id, target_kind, target_id);


-- ===== 00056_project_template_instantiations.sql =====

-- T0214 official project templates: the instantiation record. Creating a
-- project from an official template applies the template's DEFAULTS once
-- — project purpose/visibility, schema profile registrations, the first
-- project policy version, and the initial research-map questions. A
-- template never controls the project afterwards: everything applied is
-- an ordinary project-owned row (schema profile versions, policy
-- versions, scientific objects) the owner evolves through the normal
-- surfaces, and a template upgrade is a new template version that only
-- affects FUTURE instantiations.
--
-- This table records the provenance fact: which template id + version a
-- project was created from (the requirement "记录 template id/version").
-- One project has at most one template origin — UNIQUE (project_id). The
-- template catalog itself is platform code (official templates are not
-- user data), so template_id is a plain label, not a foreign key.
--
-- Rows are append-only provenance (the guard triggers below): the fact
-- that project X came from template Y vZ never changes and never
-- disappears, even if the catalog later retires that template version.
CREATE TABLE project_template_instantiations (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  project_id uuid NOT NULL REFERENCES projects(id) ON DELETE RESTRICT,
  template_id text NOT NULL,
  template_version text NOT NULL,
  -- The template's display name at instantiation time, so the record is
  -- readable without consulting the catalog history of that version.
  template_name text NOT NULL,
  created_by uuid NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
  created_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (project_id),
  CONSTRAINT project_template_instantiations_template_id_check
    CHECK (template_id ~ '^[a-z0-9][a-z0-9-]{0,63}$'),
  CONSTRAINT project_template_instantiations_template_version_check
    CHECK (template_version ~ '^[A-Za-z0-9._-]{1,64}$'),
  CONSTRAINT project_template_instantiations_template_name_check
    CHECK (char_length(template_name) BETWEEN 1 AND 200)
);

CREATE INDEX project_template_instantiations_template_idx
  ON project_template_instantiations (template_id, template_version);

CREATE TRIGGER project_template_instantiations_append_only
  BEFORE UPDATE OR DELETE ON project_template_instantiations
  FOR EACH ROW EXECUTE FUNCTION append_only_guard();

-- Row-level triggers do not fire on TRUNCATE (00015): the immutability above
-- could still be bypassed wholesale with `TRUNCATE ... CASCADE`. The
-- statement-level half reuses the same append_only_guard() function.
CREATE TRIGGER project_template_instantiations_no_truncate
  BEFORE TRUNCATE ON project_template_instantiations FOR EACH STATEMENT
  EXECUTE FUNCTION append_only_guard();


-- ===== 00057_findings.sql =====

-- Finding projection (task T0503): the structured face of a finding object
-- version — finding type, assessment, and the claim versions it pins.
--
-- A Finding is the human-confirmed formal object that aggregates claim
-- VERSIONS (docs/08 §Finding: "contained claim versions"; the schema's
-- claim_version_refs, required, minItems 1). It pins VERSION ids, never
-- object ids: an edit of a claim is a NEW version row in the append-only
-- log (00014/00015), so a later claim version can never silently rewrite
-- what an older Finding aggregated (T0503 acceptance criterion).
--
-- findings is the per-version projection (one row per finding version,
-- the same 00041 shape). Like every projection it is REBUILDABLE
-- (docs/21 §5): the payload in scientific_object_versions stays the
-- historical source of truth, so it deliberately carries no append-only
-- trigger. finding_claim_versions is the projection's materialization of
-- the claim_version_refs array — one row per pinned version, position
-- carrying the array order. It is the references' queryable face:
-- reverse lookups (which findings pin this claim version — the impact
-- analysis input, docs/19 §3) are an index scan here, not a GIN array
-- search.
--
-- The guards enforce the mechanically decidable half of the model for
-- every ROW-LEVEL write path — INSERT, UPDATE and DELETE, whether from
-- application code, psql or a leaked credential — in the
-- 00014/00015/00028/00040 discipline. TRUNCATE is deliberately NOT
-- covered (see "Deliberately NOT enforced here").
--
-- The write paths in question are the ones that reach these two tables:
-- every INSERT, UPDATE and DELETE of a findings row or a ref row is
-- judged, and the judgement is made on the state at COMMIT (below). A
-- write to some OTHER table that could erode an invariant here — moving a
-- referenced claim object to another project, say — is not visible to any
-- trigger in this file and is that table's discipline, the same boundary
-- every cross-table guard in this schema (00040's, 00047's) draws.
--
-- What they enforce:
--
--   * every pinned ref must name a scientific object VERSION whose object
--     is a claim, in the finding's own project — a fixed claim version,
--     not a foreign object or another project's claim;
--   * every findings row must pin at least one claim version (the
--     schema's claim_version_refs minItems 1), and a ref row may only
--     exist together with its findings row — no ref-less findings rows,
--     no orphan refs;
--   * every findings row must name the object its OWN version belongs to:
--     object_id is the denormalized owner of version_id, so a row that
--     paired another object's id with this version would mis-attribute
--     the finding in every object_id-keyed lookup (findings_object_idx
--     first among them);
--   * a finding can never silently lose what it aggregates. Three writes
--     would do it and all three are refused: deleting the last pinned ref,
--     deleting the findings row while refs remain, and RE-POINTING either
--     identity column — finding_claim_versions.finding_version_id or
--     findings.version_id — away from rows that still exist. The last one
--     is why those two guards carry an UPDATE OF <identity column> event:
--     a re-point is a move, and the refs of the version the row left
--     behind would otherwise be stranded (nothing else looks at OLD).
--
-- The triggers are DEFERRABLE INITIALLY DEFERRED constraint triggers:
-- they fire once, at COMMIT, when every row of the transaction is
-- visible, so a projection writer may write the findings row and its
-- refs in one transaction in any order (the 00040 parent/child shape).
-- The two UPDATE OF events are scoped to the identity column on purpose:
-- that column is the ONLY one their invariant depends on, so every UPDATE
-- that could break it is checked, and an UPDATE that does not name it
-- (finding_type, assessment, position, …) cannot orphan a ref. This is
-- also why they are not spelled as a bare UPDATE: a bare UPDATE event
-- would re-run the guard on a row that keeps its identity and refuse a
-- perfectly legal rewrite of it.
--
-- Deliberately NOT enforced here:
--
--   * TRUNCATE. A row-level trigger cannot see it, so the guards above
--     cover INSERT/UPDATE/DELETE and not truncation — and that is the
--     intended scope, not a hole to plug: truncate-then-repopulate is
--     exactly how a REBUILDABLE projection is rebuilt (docs/21 §5). The
--     claims projection (00041) carries no truncate guard either; the
--     append-only logs are the tables that do (00015);
--   * finding_type/assessment VALUES are CHECK-pinned (they are the
--     schema enums of finding.schema.json), but TRANSITIONS between them
--     are not: like claim assessment, docs/43 makes these positions, not
--     a linear ladder, and a new version is the legitimate way to change
--     one (00040's reasoning);
--   * negative_finding carries no extra constraint: what a negative
--     finding must link to (the contradicts/fails_to_reproduce edges of
--     docs/44) is a scientific judgement the relations validate per
--     write, not a projection-column rule.

CREATE TABLE findings (
  version_id uuid PRIMARY KEY REFERENCES scientific_object_versions(id) ON DELETE RESTRICT,
  object_id uuid NOT NULL REFERENCES scientific_objects(id) ON DELETE RESTRICT,
  -- finding_type is NULLABLE because the finding schema leaves it
  -- optional: finding.schema.json's required list names statement and
  -- claim_version_refs, not finding_type (only its enum is pinned). A
  -- projection row must be able to materialize every schema-legal
  -- version, so the column mirrors the schema's requiredness — the same
  -- rule that makes assessment nullable below. The claims table (00041)
  -- holds claim_type NOT NULL for the same rule in the other direction:
  -- claim.schema.json DOES require claim_type. The CHECK still refuses
  -- every value outside the enum; NULL means "no type stated".
  finding_type text CHECK (finding_type IN ('observation','comparison','trend','mechanistic_interpretation','negative_finding','integrated_conclusion')),
  assessment text CHECK (assessment IN ('preliminary','accepted','contested','unresolved','superseded','aborted')),
  created_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE finding_claim_versions (
  finding_version_id uuid NOT NULL REFERENCES scientific_object_versions(id) ON DELETE RESTRICT,
  claim_version_id uuid NOT NULL REFERENCES scientific_object_versions(id) ON DELETE RESTRICT,
  position int NOT NULL DEFAULT 0 CHECK (position >= 0),
  PRIMARY KEY (finding_version_id, claim_version_id),
  UNIQUE (finding_version_id, position)
);

CREATE INDEX findings_object_idx ON findings(object_id);
CREATE INDEX findings_type_idx ON findings(finding_type);
CREATE INDEX finding_claim_versions_claim_idx ON finding_claim_versions(claim_version_id);

-- +goose StatementBegin
CREATE FUNCTION finding_claim_refs_guard() RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
  finding_obj_type text;
  finding_project uuid;
  claim_obj_type text;
  claim_project uuid;
BEGIN
  SELECT so.object_type, so.project_id INTO finding_obj_type, finding_project
    FROM scientific_object_versions sov
    JOIN scientific_objects so ON so.id = sov.object_id
   WHERE sov.id = NEW.finding_version_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'finding claim ref: finding version % does not exist',
      NEW.finding_version_id
      USING ERRCODE = 'P0001';
  END IF;
  IF finding_obj_type <> 'finding' THEN
    RAISE EXCEPTION 'finding claim ref: version % is a %, not a finding version',
      NEW.finding_version_id, finding_obj_type
      USING ERRCODE = 'P0001';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM findings WHERE version_id = NEW.finding_version_id) THEN
    RAISE EXCEPTION 'finding claim ref: no findings projection row for version %',
      NEW.finding_version_id
      USING ERRCODE = 'P0001';
  END IF;

  SELECT so.object_type, so.project_id INTO claim_obj_type, claim_project
    FROM scientific_object_versions sov
    JOIN scientific_objects so ON so.id = sov.object_id
   WHERE sov.id = NEW.claim_version_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'finding claim ref: claim version % does not exist',
      NEW.claim_version_id
      USING ERRCODE = 'P0001';
  END IF;
  IF claim_obj_type <> 'claim' THEN
    RAISE EXCEPTION 'finding claim ref: version % is a %, not a claim version',
      NEW.claim_version_id, claim_obj_type
      USING ERRCODE = 'P0001';
  END IF;
  IF claim_project IS DISTINCT FROM finding_project THEN
    RAISE EXCEPTION 'finding claim ref: claim version % belongs to a different project',
      NEW.claim_version_id
      USING ERRCODE = 'P0001';
  END IF;
  RETURN NEW;
END;
$$;
-- +goose StatementEnd

CREATE CONSTRAINT TRIGGER finding_claim_versions_ref_guard
  AFTER INSERT OR UPDATE ON finding_claim_versions
  DEFERRABLE INITIALLY DEFERRED
  FOR EACH ROW EXECUTE FUNCTION finding_claim_refs_guard();

-- +goose StatementBegin
CREATE FUNCTION finding_refs_present_guard() RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM finding_claim_versions
                  WHERE finding_version_id = NEW.version_id) THEN
    RAISE EXCEPTION 'finding %: a finding must pin at least one claim version (claim_version_refs)',
      NEW.version_id
      USING ERRCODE = 'P0001';
  END IF;
  RETURN NEW;
END;
$$;
-- +goose StatementEnd

CREATE CONSTRAINT TRIGGER findings_refs_present
  AFTER INSERT OR UPDATE ON findings
  DEFERRABLE INITIALLY DEFERRED
  FOR EACH ROW EXECUTE FUNCTION finding_refs_present_guard();

-- +goose StatementBegin
CREATE FUNCTION finding_version_object_guard() RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM scientific_object_versions
                  WHERE id = NEW.version_id AND object_id = NEW.object_id) THEN
    RAISE EXCEPTION 'finding %: object_id % is not the object of version %',
      NEW.version_id, NEW.object_id, NEW.version_id
      USING ERRCODE = 'P0001';
  END IF;
  RETURN NEW;
END;
$$;
-- +goose StatementEnd

CREATE CONSTRAINT TRIGGER findings_version_object_pairing
  AFTER INSERT OR UPDATE ON findings
  DEFERRABLE INITIALLY DEFERRED
  FOR EACH ROW EXECUTE FUNCTION finding_version_object_guard();

-- +goose StatementBegin
CREATE FUNCTION finding_no_orphan_refs_guard() RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  -- Fires on DELETE and on UPDATE OF version_id. On UPDATE the guard only
  -- has something to say if the identity column actually moved: a rewrite
  -- that keeps it (an upsert echoing version_id = EXCLUDED.version_id, a
  -- no-op assignment) strands nothing and must not be refused.
  IF TG_OP = 'UPDATE' THEN
    IF OLD.version_id IS NOT DISTINCT FROM NEW.version_id THEN
      RETURN NEW;
    END IF;
  END IF;
  IF EXISTS (SELECT 1 FROM finding_claim_versions
              WHERE finding_version_id = OLD.version_id) THEN
    RAISE EXCEPTION 'finding %: its claim version refs must be removed before the projection row that names it goes away or is re-pointed',
      OLD.version_id
      USING ERRCODE = 'P0001';
  END IF;
  RETURN OLD;
END;
$$;
-- +goose StatementEnd

CREATE CONSTRAINT TRIGGER findings_no_orphan_refs
  AFTER DELETE OR UPDATE OF version_id ON findings
  DEFERRABLE INITIALLY DEFERRED
  FOR EACH ROW EXECUTE FUNCTION finding_no_orphan_refs_guard();

-- +goose StatementBegin
CREATE FUNCTION finding_refs_remain_guard() RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  -- Fires on DELETE and on UPDATE OF finding_version_id. On UPDATE the ref
  -- must have been moved to a DIFFERENT finding to be able to strand the
  -- one it left (an upsert echoing finding_version_id stranded nothing).
  IF TG_OP = 'UPDATE' THEN
    IF OLD.finding_version_id IS NOT DISTINCT FROM NEW.finding_version_id THEN
      RETURN NEW;
    END IF;
  END IF;
  IF EXISTS (SELECT 1 FROM findings WHERE version_id = OLD.finding_version_id)
     AND NOT EXISTS (SELECT 1 FROM finding_claim_versions
                      WHERE finding_version_id = OLD.finding_version_id) THEN
    RAISE EXCEPTION 'finding %: removing the last claim version ref leaves the finding without claim refs',
      OLD.finding_version_id
      USING ERRCODE = 'P0001';
  END IF;
  RETURN OLD;
END;
$$;
-- +goose StatementEnd

CREATE CONSTRAINT TRIGGER finding_claim_versions_refs_remain
  AFTER DELETE OR UPDATE OF finding_version_id ON finding_claim_versions
  DEFERRABLE INITIALLY DEFERRED
  FOR EACH ROW EXECUTE FUNCTION finding_refs_remain_guard();


-- ===== 00058_evidence_assertion_guards.sql =====

-- Evidence assertion guards (task T0504).
--
-- Migration 00007 scaffolded the evidence_assertions table with the
-- relation and review-state enums checked; this migration completes the
-- guard surface so the table enforces the whole evidence-assertion
-- schema vocabulary — and the model's one non-enum structural rule, the
-- directed-edge pins — for ANY write path (application code, psql, a
-- leaked credential), in the 00014/00015/00028 discipline: the domain
-- layer validates on the happy path (internal/domain.EvidenceAssertion
-- and internal/rsg/semantics.CheckEvidenceAssertion), the database makes
-- the invariant unconditional.
--
-- Added here, mirroring the schema enums (specs/schemas/evidence-
-- assertion.schema.json) value for value:
--
--   * evidence_type  — experimental, computational, dataset, literature,
--     external_attestation, other;
--   * directness     — direct, indirect, unknown;
--   * inference_nature — observational, associational, causal,
--     mechanistic, predictive, descriptive, unknown;
--   * scope          — a JSON object (jsonb_typeof(scope) = 'object');
--     the schema leaves scope's CONTENT free-form, so "is an object" is
--     the only mechanical check there is.
--
-- Plus one rule the enums do not cover, mirrored from the domain model:
--
--   * the two version pins must DIFFER (target_object_version_id <>
--     evidence_object_version_id) — an assertion is a directed edge
--     between two versions, and domain.EvidenceAssertion.Validate
--     already rejects the self-assertion, so the database makes the
--     same rule unconditional here (this migration's layering: the
--     happy path validates, the schema guarantees).
--
-- The relation and review-state enums are already checked by 00007; the
-- new checks deliberately cover only the rules that lacked them.
--
-- Deliberately NOT constrained here:
--
--   * (target_object_version_id, evidence_object_version_id) uniqueness.
--     The pair is NOT unique BY DESIGN (task acceptance criterion:
--     支持与反驳可同时存在): one evidence version may carry a supports
--     AND a contradicts assertion on the same target version, side by
--     side, each reviewed on its own. A unique constraint on the pair
--     would collapse the two stances into one row and force a winner —
--     exactly the net-position arithmetic the domain forbids.
--   * any weight/score column. docs/10 §4: V1 不自动赋数值权重 — no
--     numeric weight exists, and none is derivable here (CLAUDE.md
--     §9.13: no Truth Score). Stance labels (supporting/contesting/
--     neutral) are computed by a transparent rule in the domain layer,
--     never stored as numbers.
--   * append-only DELETE guards. Reviewing an assertion is a legitimate
--     in-place state change (unreviewed → reviewed → rejected), like the
--     other version-less member rows; the append-only triggers (00014/
--     00015) guard the version LOGS, not member rows.
--
-- Version pinning (the task's version-pin requirement) was already
-- structural in 00007: both endpoints are uuid foreign keys to
-- scientific_object_versions with ON DELETE RESTRICT, so a pinned
-- version cannot disappear while an assertion points at it, and the
-- assertion keeps its meaning when either object moves on. This
-- migration adds the indexes that make the pinned queries fast.
--
-- The indexes serve the two natural query paths:
--   * listing assertions against one target version (the
--     ListEvidenceAssertionsForTarget shape: target, then created
--     order);
--   * finding every assertion a given evidence version backs.

ALTER TABLE evidence_assertions
  ADD CONSTRAINT evidence_assertions_evidence_type_check
    CHECK (evidence_type IN ('experimental', 'computational', 'dataset', 'literature', 'external_attestation', 'other')),
  ADD CONSTRAINT evidence_assertions_directness_check
    CHECK (directness IN ('direct', 'indirect', 'unknown')),
  ADD CONSTRAINT evidence_assertions_inference_nature_check
    CHECK (inference_nature IN ('observational', 'associational', 'causal', 'mechanistic', 'predictive', 'descriptive', 'unknown')),
  ADD CONSTRAINT evidence_assertions_scope_check
    CHECK (jsonb_typeof(scope) = 'object'),
  -- The self-assertion rule, mirrored from domain.EvidenceAssertion.Validate
  -- (target_version_ref == evidence_version_ref is a hard failure there):
  -- an assertion is a DIRECTED edge between two versions, so a row naming
  -- the same version on both ends is meaningless. The domain rejects it on
  -- the happy path; this CHECK makes the rule unconditional for ANY write
  -- path, which is the point of this migration's layering.
  ADD CONSTRAINT evidence_assertions_pins_differ_check
    CHECK (target_object_version_id <> evidence_object_version_id);

CREATE INDEX evidence_assertions_target_idx
  ON evidence_assertions (target_object_version_id, created_at, id);

CREATE INDEX evidence_assertions_evidence_idx
  ON evidence_assertions (evidence_object_version_id);


-- ===== 00059_webhook_endpoints.sql =====

-- Signed webhooks (T1006, docs/18 §4, docs/22 §9): user-registered
-- delivery endpoints that receive signed research events. The pipeline is
-- outbox (00012) -> research_events (dispatcher, T1001) -> per-endpoint
-- fan-out (this migration's cursor on outbox_events) -> signed HTTP
-- delivery with retry (worker Deliverer).
--
-- Three pieces land here:
--
--   1. webhook_endpoints: the endpoint registry. Each endpoint carries its
--      own HMAC secret, generated at creation, returned to the owner ONCE
--      and never again (any API read omits it by construction). The
--      secret is stored as plaintext because the deliverer must sign with
--      it — a hash would make signing impossible (unlike PATs, which are
--      compared, not used as keys). The consecutive_failures counter and
--      enabled flag drive the disable policy: after
--      DefaultConsecutiveFailureLimit failed deliveries the deliverer
--      flips enabled off; the owner may re-enable it.
--
--   2. outbox_events.webhook_fanned_out_at: the fan-out cursor. A row is
--      fanned out exactly once — the deliverer claims published-but-not-
--      fanned rows (FOR UPDATE SKIP LOCKED, the T1001 pattern) and marks
--      them in the same transaction as the delivery inserts, so a crash
--      between insert and mark re-runs the idempotent fan-out (the unique
--      index in 3. makes it a no-op). The cursor lives on the outbox row
--      instead of a watermark on research_events because it needs no
--      ordering assumption: whatever the publisher has published, in
--      whatever order, is fanned out in published order.
--
--   3. webhook_deliveries delivery-log columns: endpoint_id pins which
--      registered endpoint the delivery targets (SET NULL, not CASCADE:
--      even a physical removal keeps the delivery log rows, and the raw
--      endpoint column preserves the fan-out-time URL snapshot for the
--      log — the deliverer posts to the snapshot, so the log always says
--      where the request actually went), event_type is the delivered
--      event's type at fan-out, next_retry_at schedules the retry (NULL +
--      status 'pending' = due now; the deliverer also uses it as the
--      in-flight lease), last_error/delivered_at complete the log. The
--      partial unique index (endpoint_id, event_id) is the fan-out
--      idempotency guarantee: one delivery row per endpoint per event,
--      ever.

CREATE TABLE webhook_endpoints (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id uuid NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
  url text NOT NULL,
  secret text NOT NULL,
  event_filters text[] NOT NULL DEFAULT '{}',
  enabled boolean NOT NULL DEFAULT true,
  consecutive_failures integer NOT NULL DEFAULT 0,
  disabled_at timestamptz,
  deleted_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  CHECK (url <> ''),
  CHECK (secret <> '')
);

COMMENT ON TABLE webhook_endpoints IS
  'User-registered webhook delivery endpoints (T1006). One HMAC secret per endpoint, returned to the owner only at creation/rotation; enabled is the disable-policy switch (deliverer flips it after consecutive failures, the owner may re-enable).';

COMMENT ON COLUMN webhook_endpoints.url IS
  'Delivery target, validated as http(s) with a host and no embedded credentials at the service layer. The delivery-log snapshot in webhook_deliveries.endpoint is what the deliverer actually posts to.';

COMMENT ON COLUMN webhook_endpoints.secret IS
  'HMAC-SHA256 signing secret (generated, 32 random bytes hex-encoded). Plaintext by necessity — the deliverer signs with it; a stored hash could never reproduce a signature. Never rendered by any API read.';

COMMENT ON COLUMN webhook_endpoints.event_filters IS
  'Event types this endpoint receives, exact match; empty means all (public) events. Subscription-target mapping (who receives which project''s events) arrives with T1002 — filters here are the delivery-side half only.';

COMMENT ON COLUMN webhook_endpoints.consecutive_failures IS
  'Consecutive failed deliveries (any status other than delivered). Reset to 0 by a successful delivery; reaching the deliverer''s limit disables the endpoint.';

COMMENT ON COLUMN webhook_endpoints.deleted_at IS
  'Soft delete (docs/04 §6: nothing disappears — state only evolves). DeleteEndpoint stamps it together with enabled=false instead of removing the row: the endpoint answers not-found, receives no fan-out and cannot be redelivered, but its delivery-log rows keep their endpoint_id and stay readable through the list API. NULL = live.';

ALTER TABLE outbox_events
  ADD COLUMN webhook_fanned_out_at timestamptz;

COMMENT ON COLUMN outbox_events.webhook_fanned_out_at IS
  'The webhook fan-out cursor (T1006): set in the same transaction that inserts the delivery rows, so the fan-out is exactly-once per published row — a crash between insert and mark re-runs it as a no-op under webhook_deliveries_endpoint_event_uniq.';

-- The fan-out backlog scan: published rows that no fan-out has consumed.
CREATE INDEX outbox_events_fanout_pending_idx
  ON outbox_events (created_at, id)
  WHERE published_at IS NOT NULL AND webhook_fanned_out_at IS NULL;

ALTER TABLE webhook_deliveries
  ADD COLUMN endpoint_id uuid REFERENCES webhook_endpoints(id) ON DELETE SET NULL,
  ADD COLUMN event_type text NOT NULL DEFAULT '',
  ADD COLUMN created_at timestamptz NOT NULL DEFAULT now(),
  ADD COLUMN next_retry_at timestamptz,
  ADD COLUMN last_error text,
  ADD COLUMN delivered_at timestamptz;

-- A fan-out insert names only (endpoint_id, endpoint, event_id,
-- event_type): every fanned-out delivery starts pending by definition,
-- and the default says so for this and any future writer.
ALTER TABLE webhook_deliveries
  ALTER COLUMN status SET DEFAULT 'pending';

COMMENT ON COLUMN webhook_deliveries.endpoint_id IS
  'The registered endpoint this delivery targets (NULL only for rows predating T1006 — the table exists since 00012 but nothing has ever written it).';

COMMENT ON COLUMN webhook_deliveries.event_type IS
  'The delivered event''s type, pinned at fan-out (the log must read without a join into the append-only event log).';

COMMENT ON COLUMN webhook_deliveries.next_retry_at IS
  'When the next attempt is due (status pending). NULL = due now. Doubles as the in-flight lease: the deliverer claims a row by pushing next_retry_at into the future, so a crash mid-request releases the row after the lease expires instead of blocking it forever.';

COMMENT ON COLUMN webhook_deliveries.last_error IS
  'Why the last attempt failed (bounded text — see the deliverer''s error truncation). The operator''s window onto a stuck delivery, mirroring outbox_events.last_error.';

-- The fan-out idempotency guarantee: one delivery row per (endpoint, event)
-- pair, ever. Retried fan-outs hit ON CONFLICT DO NOTHING and stay no-ops.
CREATE UNIQUE INDEX webhook_deliveries_endpoint_event_uniq
  ON webhook_deliveries (endpoint_id, event_id)
  WHERE endpoint_id IS NOT NULL;

-- The deliverer's due-work scan.
CREATE INDEX webhook_deliveries_due_idx
  ON webhook_deliveries (status, next_retry_at)
  WHERE status = 'pending';


-- ===== 00061_scientific_review_dimensions.sql =====

-- Scientific Review model (task T0404): per-dimension review records on
-- pull requests (docs/09 §5: Scientific Review and Integrity Review are
-- recorded per dimension, "Review 状态可以按维度记录，不用单一 approve
-- 抹平所有差异"; docs/43: "Scientific/Integrity review 各自状态").
--
-- What changes here, and why each piece:
--
--   1. review_kind narrowed to the two documented dimensions
--      ('scientific','integrity'). The base schema (00009) also admitted
--      'rights' and 'ip', but docs/09 §5 defines exactly two review
--      dimensions and no writer ever existed — zero rows are migrated,
--      and a later task (T0604 routing) can re-widen the vocabulary in
--      its own forward migration if a third dimension is spec'd.
--
--   2. decision vocabulary becomes ('approved','changes_requested',
--      'comment') — the task requirement's exact three decisions. The
--      base schema's third token was 'commented'; no row ever carried
--      it (the reviews table had no writer before this task), so the
--      rename costs no data migration.
--
--   3. reviewed_state_id pins the review to the EXACT proposed head the
--      reviewer evaluated: a review is a judgment about one state, not
--      about a moving target. The adapter always fills it from the PR's
--      current proposed_state_id inside the submission transaction, so
--      a review of the current head is one row; after the author
--      updates the head and re-requests review, the next round's
--      decisions are new rows on the new head, and stale decisions can
--      never leak into the new round's projection.
--
--   4. responsibility records which scientific responsibility the
--      reviewer acted under (docs/04 §3: responsibility is for review
--      routing, separate from access roles). The label is resolved by
--      the application's reviewer-responsibility hook (T0604 lands the
--      rule-based resolver); empty means no responsibility label was
--      resolved. Bounded by the domain layer, not here.
--
--   5. UNIQUE(pull_request_id, reviewer_id, review_kind,
--      reviewed_state_id): one person records ONE decision per
--      dimension per head — the acceptance "一人不同 review kind 可
--      记录" encoded as a database fact (different kinds and later
--      heads are never blocked; a duplicate decision about the same
--      head is refused instead of silently double-counted). A review of
--      a state is final: the machine's only path forward after a
--      decision is the author updating the head (docs/43).
--
-- The backfill path for reviewed_state_id keeps the migration valid on
-- a non-empty table (add nullable -> backfill from the owning PR ->
-- set NOT NULL), even though no production row exists.

ALTER TABLE reviews
  DROP CONSTRAINT reviews_review_kind_check,
  ADD CONSTRAINT reviews_review_kind_check
    CHECK (review_kind IN ('scientific','integrity')),
  DROP CONSTRAINT reviews_decision_check,
  ADD CONSTRAINT reviews_decision_check
    CHECK (decision IN ('approved','changes_requested','comment'));

ALTER TABLE reviews
  ADD COLUMN reviewed_state_id uuid REFERENCES project_states(id) ON DELETE RESTRICT;

UPDATE reviews r
SET reviewed_state_id = pr.proposed_state_id
FROM pull_requests pr
WHERE pr.id = r.pull_request_id;

ALTER TABLE reviews
  ALTER COLUMN reviewed_state_id SET NOT NULL;

ALTER TABLE reviews
  ADD COLUMN responsibility text NOT NULL DEFAULT '',
  ADD CONSTRAINT reviews_reviewer_kind_state_key
    UNIQUE (pull_request_id, reviewer_id, review_kind, reviewed_state_id);


-- ===== 00062_contribution_opportunity.sql =====

-- Contribution opportunities (task T0803, docs/02 "Open Network — Open
-- Contribution Opportunity").
--
-- A maintainer marks an issue or a research need (a research_question
-- scientific object) as open for contribution, with difficulty and
-- capability metadata; a suggestion from an agent or a member lands as
-- state 'suggested' and becomes real only through a maintainer's
-- approval. The row's lifecycle and its visibility are two separate
-- machines:
--
--   1. state: suggested → open → closed. 'suggested' is the creation
--      state of a suggestion (suggested_by set); 'open' is the creation
--      state of a maintainer mark (suggested_by NULL — a marked row is
--      not a suggestion, and approved_by only exists on rows that were
--      suggested); 'closed' is terminal (a rejected suggestion, or a
--      fulfilled/withdrawn opportunity — the row stays as history,
--      nothing is deleted; a re-mark creates a new row).
--   2. visibility: internal → public. A new row is ALWAYS internal;
--      publicizing is a docs/12 §3 visibility widening ("任何
--      private→public … 都要求有权限的人显式确认，并产生 audit/event。
--      Agent/MCP 不得自动执行此类扩大操作"): it is a separate,
--      explicit action, stamped with publicized_by/publicized_at, and
--      enforced here for ANY write path — a row becomes public only
--      through the one adapter path that sets the transaction-scoped
--      session flag post.co_publicize='on' (the same sanctioned-path
--      discipline as 00051's PR head refresh), and public is terminal
--      (no un-publish in V1).
--
-- A publicized row is frozen except for its state: metadata (title,
-- description, difficulty, capabilities) and the publicize stamps are
-- immutable once public — the open network may index the row, so its
-- content must not drift underneath it. Metadata updates while internal
-- are allowed on any non-closed row.
--
-- The target is polymorphic (an issue row or a research_question
-- scientific object), so there is no FK on target_id; the deferred
-- constraint trigger below pins target existence project-scoped for any
-- write path (the 00040 discipline: it fires once, at COMMIT, when
-- every row of the transaction is visible). One active (non-closed)
-- opportunity per target is the partial unique index — the key the
-- creation insert conflicts on, so a target can never carry two open or
-- two suggested opportunities, while closed history rows coexist.
--
-- Scope of the publicize flag, stated precisely (the same honesty as
-- 00051's header): the flag blocks IMPLICIT or accidental writes by
-- application code — a rogue UPDATE without the flag fails, and no
-- query in this schema sets the flag. It is NOT a defense against
-- hostile or leaked SQL credentials: any session with UPDATE privilege
-- on contribution_opportunities can run
-- set_config('post.co_publicize','on',true) itself. Everything else in
-- this migration (the CHECKs, the state map, the identity/metadata
-- fixity, the target guard, the partial unique index) is unconditional
-- and holds even against such a session.

CREATE TABLE contribution_opportunities (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  project_id uuid NOT NULL REFERENCES projects(id) ON DELETE RESTRICT,
  target_type text NOT NULL CHECK (target_type IN ('issue','research_question')),
  target_id uuid NOT NULL,
  title text NOT NULL,
  description text NOT NULL DEFAULT '',
  difficulty text NOT NULL CHECK (difficulty IN ('beginner','intermediate','advanced')),
  required_capabilities text[] NOT NULL DEFAULT '{}' CHECK (cardinality(required_capabilities) <= 10),
  state text NOT NULL DEFAULT 'suggested' CHECK (state IN ('suggested','open','closed')),
  visibility text NOT NULL DEFAULT 'internal' CHECK (visibility IN ('internal','public')),
  created_by uuid NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
  suggested_by uuid REFERENCES users(id) ON DELETE RESTRICT,
  approved_by uuid REFERENCES users(id) ON DELETE RESTRICT,
  publicized_by uuid REFERENCES users(id) ON DELETE RESTRICT,
  publicized_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);

-- One active (suggested or open) opportunity per target; closed rows
-- stay as history (invariant 8: nothing disappears, state only evolves).
CREATE UNIQUE INDEX contribution_opportunities_target_active_idx
  ON contribution_opportunities (target_type, target_id)
  WHERE state IN ('suggested','open');

-- +goose StatementBegin
CREATE FUNCTION contribution_opportunity_guard() RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
  valid_transition boolean;
  publicize_allowed boolean;
BEGIN
  IF TG_OP = 'INSERT' THEN
    -- A row is born internal, never public: publicizing is the separate
    -- explicit action below, and no INSERT may pre-stamp it.
    IF NEW.visibility <> 'internal' THEN
      RAISE EXCEPTION 'a contribution opportunity is created internal; publicizing is a separate, explicit action (docs/12 §3)'
        USING ERRCODE = 'P0001';
    END IF;
    IF NEW.publicized_by IS NOT NULL OR NEW.publicized_at IS NOT NULL
       OR NEW.approved_by IS NOT NULL THEN
      RAISE EXCEPTION 'publicized/approved stamps are earned by transitions, never set at creation'
        USING ERRCODE = 'P0001';
    END IF;
    -- A suggested row names its suggester; a maintainer mark is not a
    -- suggestion.
    IF NEW.state = 'suggested' AND NEW.suggested_by IS NULL THEN
      RAISE EXCEPTION 'a suggested opportunity names its suggester'
        USING ERRCODE = 'P0001';
    END IF;
    IF NEW.state = 'open' AND NEW.suggested_by IS NOT NULL THEN
      RAISE EXCEPTION 'a maintainer-marked opportunity is not a suggestion'
        USING ERRCODE = 'P0001';
    END IF;
  END IF;

  IF TG_OP = 'UPDATE' THEN
    -- Identity fixity: project, target and creators never move.
    IF NEW.project_id IS DISTINCT FROM OLD.project_id
       OR NEW.target_type IS DISTINCT FROM OLD.target_type
       OR NEW.target_id IS DISTINCT FROM OLD.target_id
       OR NEW.created_by IS DISTINCT FROM OLD.created_by
       OR NEW.suggested_by IS DISTINCT FROM OLD.suggested_by THEN
      RAISE EXCEPTION 'contribution opportunity identity is fixed: project, target and creators are immutable'
        USING ERRCODE = 'P0001';
    END IF;

    -- Approval is a one-way stamp earned by the suggested -> open move.
    IF NEW.approved_by IS DISTINCT FROM OLD.approved_by THEN
      IF OLD.approved_by IS NOT NULL THEN
        RAISE EXCEPTION 'approved_by is immutable once set'
          USING ERRCODE = 'P0001';
      END IF;
      IF NOT (OLD.state = 'suggested' AND NEW.state = 'open') THEN
        RAISE EXCEPTION 'approved_by is earned only by the suggested -> open approval'
          USING ERRCODE = 'P0001';
      END IF;
    END IF;

    -- The state machine: no skipping, closed is terminal.
    IF NEW.state IS DISTINCT FROM OLD.state THEN
      valid_transition :=
        (OLD.state = 'suggested' AND NEW.state IN ('open','closed'))
        OR (OLD.state = 'open' AND NEW.state = 'closed');
      IF NOT valid_transition THEN
        RAISE EXCEPTION 'illegal contribution opportunity state transition: % -> %',
          OLD.state, NEW.state
          USING ERRCODE = 'P0001';
      END IF;
    END IF;

    -- Visibility: only the explicit, audited internal -> public
    -- publicize, and only for an open row. State changes never touch
    -- visibility and public is terminal.
    IF NEW.visibility IS DISTINCT FROM OLD.visibility THEN
      publicize_allowed :=
        OLD.visibility = 'internal'
        AND NEW.visibility = 'public'
        AND OLD.state = 'open'
        AND coalesce(current_setting('post.co_publicize', true), '') = 'on'
        AND NEW.publicized_by IS NOT NULL
        AND NEW.publicized_at IS NOT NULL;
      IF NOT publicize_allowed THEN
        RAISE EXCEPTION 'a contribution opportunity is publicized only through the explicit publicize action (docs/12 §3: visibility widening is never automatic)'
          USING ERRCODE = 'P0001';
      END IF;
    END IF;

    -- Publicized rows are frozen for the open network: metadata and the
    -- publicize stamps are immutable once public (state may still move
    -- open -> closed, and the row stays public as history).
    IF OLD.visibility = 'public' THEN
      IF NEW.title IS DISTINCT FROM OLD.title
         OR NEW.description IS DISTINCT FROM OLD.description
         OR NEW.difficulty IS DISTINCT FROM OLD.difficulty
         OR NEW.required_capabilities IS DISTINCT FROM OLD.required_capabilities
         OR NEW.publicized_by IS DISTINCT FROM OLD.publicized_by
         OR NEW.publicized_at IS DISTINCT FROM OLD.publicized_at THEN
        RAISE EXCEPTION 'a publicized contribution opportunity is frozen: metadata and publicize stamps are immutable'
          USING ERRCODE = 'P0001';
      END IF;
    END IF;
  END IF;
  RETURN NEW;
END;
$$;
-- +goose StatementEnd

CREATE TRIGGER contribution_opportunity_guard_trigger
  BEFORE INSERT OR UPDATE ON contribution_opportunities
  FOR EACH ROW EXECUTE FUNCTION contribution_opportunity_guard();

-- +goose StatementBegin
CREATE FUNCTION contribution_opportunity_target_guard() RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
  found boolean;
BEGIN
  IF NEW.target_type = 'issue' THEN
    SELECT EXISTS (
      SELECT 1 FROM issues i
       WHERE i.id = NEW.target_id AND i.project_id = NEW.project_id
    ) INTO found;
  ELSE
    SELECT EXISTS (
      SELECT 1 FROM scientific_objects o
       WHERE o.id = NEW.target_id
         AND o.object_type = 'research_question'
         AND o.project_id = NEW.project_id
    ) INTO found;
  END IF;
  IF NOT found THEN
    RAISE EXCEPTION 'contribution opportunity target does not exist in the project (target_type %, project %, target %)',
      NEW.target_type, NEW.project_id, NEW.target_id
      USING ERRCODE = 'P0001';
  END IF;
  RETURN NEW;
END;
$$;
-- +goose StatementEnd

-- Deferred constraint trigger (the 00040 discipline): the check fires
-- once, at COMMIT, when every row of the transaction is visible, so the
-- target and the opportunity may be written in one transaction in any
-- order. Because the identity guard makes the target immutable, only
-- INSERTs can ever trip it in practice.
CREATE CONSTRAINT TRIGGER contribution_opportunity_target_trigger
  AFTER INSERT OR UPDATE ON contribution_opportunities
  DEFERRABLE INITIALLY DEFERRED
  FOR EACH ROW EXECUTE FUNCTION contribution_opportunity_target_guard();


-- ===== 00063_project_milestones.sql =====

-- Project milestones (T0609): research-timeline markers, deliberately a
-- separate object from releases. A release is an immutable snapshot of
-- accepted state (00053); a milestone is a recorded research event —
-- candidate selected, paper submitted, patent filed, external validation,
-- or a custom-labeled marker. A milestone MAY name the release it
-- documents (release_id, nullable — not required); it never depends on
-- one, and a milestone may precede any release entirely.
--
-- Milestones never touch the project lifecycle: no trigger and no column
-- here advances projects.activity_status, which keeps no forced
-- "completed" terminal state (docs/43 §1 — planning → active ↔ paused →
-- archived). Research progress is a timeline of recorded facts, not a
-- lifecycle transition, so no milestone kind is a completion state.
--
-- The kind CHECK carries the canonical vocabulary plus custom; the
-- cross-column CHECK enforces the custom-label rule at the database level
-- (a custom marker without a label has no name — it must not exist, no
-- matter which write path inserts it). A canonical kind may carry a
-- custom display label (e.g. the venue of a paper submission) or none.
--
-- project_milestone_creations is the Idempotency-Key ledger (docs/22: an
-- Idempotency-Key governs create/command/publish/merge/release): a key
-- replays the milestone it created, forever — a retried create is a read,
-- never a duplicate timeline row. Milestones are records, not immutable
-- snapshots, so the pair carries no append-only guards (no update/delete
-- surface exists in V1; a correction surface may add one later).
--
-- The timeline index serves the project timeline scan in research order:
-- occurred_at first (the canonical kinds' natural progression), creation
-- order breaking same-date ties deterministically.

CREATE TABLE project_milestones (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  project_id uuid NOT NULL REFERENCES projects(id) ON DELETE RESTRICT,
  kind text NOT NULL CHECK(kind IN ('candidate_selected','paper_submitted','patent_filed','external_validation','custom')),
  label text,
  occurred_at timestamptz NOT NULL,
  release_id uuid REFERENCES releases(id) ON DELETE RESTRICT,
  created_by uuid NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
  created_at timestamptz NOT NULL DEFAULT now(),
  CHECK (kind <> 'custom' OR (label IS NOT NULL AND btrim(label) <> ''))
);

CREATE INDEX project_milestones_timeline_idx
  ON project_milestones(project_id, occurred_at, created_at, id);

CREATE TABLE project_milestone_creations (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  project_id uuid NOT NULL REFERENCES projects(id) ON DELETE RESTRICT,
  idempotency_key text NOT NULL,
  milestone_id uuid NOT NULL REFERENCES project_milestones(id) ON DELETE RESTRICT,
  created_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE(project_id, idempotency_key)
);


-- ===== 00064_asset_pid_origin.sql =====

-- Research asset persistent identity (T0701): every research asset gets
-- a pid — the persistent identifier its public URLs are built from —
-- and every published asset version pins its origin refs.
--
-- The pid is the asset's public identity, deliberately independent of
-- every mutable attribute: it is random, never derived from the slug,
-- the owning organization, or anything else that can be renamed or
-- transferred (docs/11 §2: 每个 Asset 有 persistent ID; acceptance:
-- asset ID 不随 slug/org 变化). A slug rename and an org transfer both
-- leave the pid — and therefore the persistent URL /assets/{pid} —
-- untouched. The format is the Go package's (internal/assets): 26
-- Crockford base32 characters (lowercase, URL-safe, no padding), the
-- same shape the CHECK below enforces. The DEFAULT is a random uuid's
-- first 26 hex characters — a Crockford subset — so every row the
-- database fills gets a valid, unique pid.
--
-- At this commit no writer supplies a pid: CreateResearchAsset
-- (internal/persistence/queries) inserts four columns and lets the
-- DEFAULT fill pid, and assets.NewPID() has no producer yet. The
-- application-generated path — a create/publish command calling
-- NewPID() — arrives with T0705 (publish); until then the DEFAULT is
-- both the backfill for rows that predate this migration and the source
-- of pids for new rows.
--
-- origin_refs on research_asset_versions is the canonical provenance pin
-- the version schema demands
-- (specs/schemas/research-asset-version.schema.json: origin_refs,
-- minItems 1): where this published version came from, as kind:value
-- refs (internal/assets.OriginRef — project, release, state,
-- object_version). Rows that predate this migration are backfilled from
-- their asset's origin project (the only origin the pre-T0701 model
-- recorded; origin_project_id is NOT NULL (00010), so every version row
-- gets a ref).
--
-- What the storage layer guarantees is narrower than "an origin": NOT
-- NULL (no absent column value), non-empty (at least one element), and
-- no NULL element (every element is a string). That is exactly the
-- schema's own type — array of string, minItems 1 — and no more: the
-- elements are text, so the database stores any string, including one
-- whose kind is unknown or whose value is not a uuid. The kind:value
-- shape is internal/assets.OriginRef's business (NewOriginRef, Valid),
-- enforced on the application path; duplicating that shape as a CHECK
-- here would mean two definitions of the origin vocabulary drifting
-- apart, in a column the schema does not constrain that way.

ALTER TABLE research_assets
  ADD COLUMN pid text NOT NULL
    DEFAULT substr(replace(gen_random_uuid()::text, '-', ''), 1, 26);

ALTER TABLE research_assets
  ADD CONSTRAINT research_assets_pid_format
    CHECK (pid ~ '^[0-9a-hjkmnp-tv-z]{26}$');

CREATE UNIQUE INDEX research_assets_pid_uniq ON research_assets (pid);

ALTER TABLE research_asset_versions
  ADD COLUMN origin_refs text[];

-- The backfill writes one field of existing version rows, which 00014's
-- row trigger forbids — for application writes, and rightly: a version
-- row is immutable history. A schema migration is the schema's own
-- authority, and a backfill of a column the old schema did not have is
-- data repair, not history rewriting (nothing previously stored is
-- changed; an absent field is filled in once). The guard is lifted for
-- exactly this statement and restored before the migration ends; goose
-- applies the whole migration in one transaction, so any failure rolls
-- the disable back with the rest of it, and after this migration no
-- path — application code, psql, a future migration — updates version
-- rows again. The statement-level TRUNCATE guard (00015) is unaffected.
ALTER TABLE research_asset_versions DISABLE TRIGGER research_asset_versions_append_only;

UPDATE research_asset_versions rav
  SET origin_refs = ARRAY['project:' || ra.origin_project_id::text]
  FROM research_assets ra
  WHERE ra.id = rav.asset_id
    AND rav.origin_refs IS NULL;

ALTER TABLE research_asset_versions ENABLE TRIGGER research_asset_versions_append_only;

ALTER TABLE research_asset_versions
  ALTER COLUMN origin_refs SET NOT NULL;

ALTER TABLE research_asset_versions
  ADD CONSTRAINT research_asset_versions_origin_refs_nonempty
    CHECK (cardinality(origin_refs) >= 1);

-- Non-empty is not yet "an origin": ARRAY[NULL] has cardinality 1 while
-- naming nothing. array_position compares with IS NOT DISTINCT FROM, so
-- it finds a NULL element (ARRAY[NULL] -> 1, ARRAY['a',NULL] -> 2) and
-- returns NULL only when no element is NULL — which is the passing
-- case. With this, a stored version row always carries at least one
-- actual string.
ALTER TABLE research_asset_versions
  ADD CONSTRAINT research_asset_versions_origin_refs_no_null
    CHECK (array_position(origin_refs, NULL) IS NULL);


-- ===== 00066_rights_document.sql =====

-- Rights model (T0703): the two rights_json columns hold a rights
-- document — a JSON object — and nothing else.
--
-- A published research asset version and a knowledge publication each
-- carry their rights declaration in rights_json (00010): the standard
-- license id, the custom agreement reference, the usage declarations
-- (commercial use, derivatives, redistribution, model training,
-- attribution, patent grant) and the two access axes. The document's
-- shape is the one specs/policies/rights-template.yaml fixes, modelled in
-- Go by internal/rights (Document, Usage, Visibility — with the JSON tags
-- that make that struct the stored format).
--
-- What the database guarantees is deliberately narrow: the column holds a
-- JSON OBJECT. A scalar or an array in a column named rights_json is not a
-- small document, it is a value of the wrong kind — no reader can take it
-- as a declaration, so every reader would have to special-case it. The
-- rule is the storage boundary's own; it says nothing about the contents,
-- and a reader may still find any field absent.
--
-- The vocabulary is NOT enforced here: no version check, no license-id
-- shape, no usage enum, no cross-field rule. The first reason is the
-- decisive one. The vocabulary has exactly one definition, internal/rights,
-- and a CHECK spelling its values again is a second definition that drifts
-- silently the first time one side changes — the reasoning 00064 gives for
-- leaving the origin ref's kind:value shape to internal/assets. The second
-- is expressiveness: "version is exactly 1", "patent_grant = see_agreement
-- requires custom_agreement_ref", "each usage value is one of three words"
-- are one-line predicates in Go and multi-line JSON-path expressions in
-- SQL, in columns whose only readers are Go.
--
-- {} is accepted, deliberately. It is what the existing fixtures store
-- (tests/integration/asset_core_test.go, append_only_test.go) and what any
-- row written before this model holds; it is not a rights document —
-- internal/rights.Parse refuses it for stating no version — and this
-- migration does not repair it. No application path has ever written these
-- columns (the publish command is T0705), so there is no data to repair,
-- and inventing a declaration for a row that stated none is precisely the
-- upgrade 00064 warns against: a backfill may fill in what the old schema
-- could not express, never decide what a publisher meant. A row that
-- carried a scalar would make this migration fail rather than pass
-- silently — the intended outcome, because such a row is a corrupt
-- document and not a legacy shape.
--
-- Both columns are constrained in the same migration because they are one
-- model: knowledge_publications.rights_json is the same document for a
-- published scientific object version that research_asset_versions
-- .rights_json is for an asset version. A rule applied to one column but
-- not the other is how the two documents' shapes diverge.

ALTER TABLE research_asset_versions
  ADD CONSTRAINT research_asset_versions_rights_json_document
    CHECK (jsonb_typeof(rights_json) = 'object');

ALTER TABLE knowledge_publications
  ADD CONSTRAINT knowledge_publications_rights_json_document
    CHECK (jsonb_typeof(rights_json) = 'object');


-- ===== 00067_asset_manifest_document.sql =====

-- Asset manifest document (T0702): the manifest column of a published
-- asset version holds a manifest — a JSON object — and nothing else.
--
-- One published asset version is described by two documents in adjacent
-- columns of research_asset_versions (00010): the rights declaration in
-- rights_json (00066) and the version manifest in manifest. The manifest
-- carries the two publish-checklist items that belong to the version
-- document rather than to a column of the row (docs/11 §3) — the required
-- metadata of the asset's type, and the exact dependency pins the version
-- was built against (docs/11 §5). Its model is internal/assets.Manifest,
-- whose JSON tags make that struct the stored format; the four asset
-- types' required metadata is internal/assets.RequiredMetadata, held to
-- the object schemas' own field names for dataset and protocol.
--
-- What the database guarantees is deliberately narrow, and narrower than
-- it looks: the column holds a JSON OBJECT. A scalar or an array in a
-- column named manifest is not a small manifest, it is a value of the
-- wrong kind — no reader can take it as a manifest, so every reader would
-- have to special-case it. The rule is the storage boundary's own.
--
-- The vocabulary is NOT enforced here, for the two reasons 00066 gives
-- about rights_json, which apply unchanged. First, the vocabulary has
-- exactly one definition, internal/assets, and a CHECK spelling its
-- values again is a second definition that drifts silently the first time
-- one side changes. Second, expressiveness: "the asset type is one of
-- four", "these five metadata keys are present, each with a value of a
-- shape its requirement allows", "every dependency pin is pid@version and
-- no version is pinned twice" are one-line predicates in Go and
-- multi-line JSON-path expressions in SQL, in a column whose only reader
-- is Go. The hash shape is left out for the same reason: integrity_hash
-- is text, its shape (64 lowercase hex characters) and its meaning (the
-- digest of the canonical manifest bytes) are internal/assets'
-- isSHA256Hex and Manifest.Hash.
--
-- {} is accepted, deliberately — again as in 00066. It is what the
-- existing fixtures store (tests/integration/asset_core_test.go) and what
-- any row written before this model holds. It is NOT a manifest:
-- internal/assets.ParseManifest refuses it (no format version, no asset
-- type, no required metadata), and this migration does not repair it. No
-- application path has ever written this column (the publish command is
-- T0705), so there is no data to repair, and inventing required metadata
-- for a version that declared none is exactly the upgrade 00064 warns
-- against: a migration may fill in what the old schema could not express,
-- never decide what a publisher meant. A row carrying a scalar or an
-- array would make this migration fail rather than pass silently — the
-- intended outcome, because such a row is a corrupt document, not a
-- legacy shape.
--
-- Only research_asset_versions.manifest is constrained. The same column
-- name on releases (00010) holds a RELEASE manifest — the RSG snapshot
-- hash, the git commit, the blob hashes and the schema/policy/rights
-- versions fixed at release time (CLAUDE.md §8) — which is a different
-- document with a different model and no builder yet. Constraining it
-- here would be asserting a shape nothing has decided; 00066 constrained
-- both of its columns because they hold the one rights document.

ALTER TABLE research_asset_versions
  ADD CONSTRAINT research_asset_versions_manifest_document
    CHECK (jsonb_typeof(manifest) = 'object');


-- ===== 00069_semantic_merge.sql =====

-- Semantic merge engine (task T0406): the record of one Research PR merge
-- and the conflicts that merge carries rather than resolves.
--
-- docs/09 §3 freezes main: the only way it advances is a Research PR
-- merge, and this migration is where that merge leaves its trace. A merge
-- row is written in the SAME transaction that commits the merged state
-- (semantic_merges.state_commit_id is NOT NULL by then), so the accepted
-- state and the record of how it was accepted cannot come apart. The row
-- also carries the plan that was executed — the engine's canonical JSON
-- (internal/rsg/merge) and its digest — so an auditor replays what the
-- merge decided without re-deriving it from the states.
--
-- Three things this migration is careful about:
--
--   1. one merge per pull request (UNIQUE(pull_request_id)): the PR state
--      machine reaches `merged` once (00051), and the database refuses a
--      second merge row for the same PR — trying to merge a PR twice
--      cannot double-advance the target branch;
--   2. the carried conflicts are APPEND-ONLY (the 00014 guard): a conflict
--      main accepted as contested/unresolved (docs/09 §8) is a fact of
--      that state. It is never edited away or deleted — the invariant
--      "nothing disappears; state only evolves" (CLAUDE.md §9) applies to
--      the open scientific disagreement exactly as it applies to the
--      content;
--   3. the Git saga columns are a separate, narrow update surface. The
--      GitProvider step happens AFTER the database transaction commits
--      (docs/08: Git is the repository/file truth beside PostgreSQL's
--      semantic truth), so the merge row is written first, the git outcome
--      is recorded second, and a failed git step stays visible and
--      retryable instead of silently diverging. The row itself is
--      otherwise immutable — the trigger below refuses any update outside
--      the saga columns, the same discipline as 00028's branch guard and
--      00051's PR guard.
--
-- The conflict_resolutions CHECK is widened to the FULL docs/09 §8
-- vocabulary. T0407 shipped the five kinds its page offered; T0406 must
-- express all seven actions, so the table has to store them. No existing
-- spelling changes and no row is rewritten — this is a strict widening.

-- 1. docs/09 §8: Accept A / Accept B / Keep both versions / Explicit
-- coexistence / Create validation branch / Request more evidence / Abort
-- proposed change, plus the contested/unresolved state main may keep.
ALTER TABLE conflict_resolutions DROP CONSTRAINT IF EXISTS conflict_resolutions_resolution_check;
ALTER TABLE conflict_resolutions ADD CONSTRAINT conflict_resolutions_resolution_check
  CHECK (resolution IN ('accept_source','accept_target','keep_both','explicit_coexistence',
                        'validation_branch','request_evidence','abort_change','unresolved'));

-- 2. One Research PR merge.
CREATE TABLE semantic_merges (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  project_id uuid NOT NULL REFERENCES projects(id) ON DELETE RESTRICT,
  -- The Research PR this merge executes. NOT NULL on purpose: main (and
  -- every other target branch) advances only this way (docs/09 §3/§4).
  pull_request_id uuid NOT NULL REFERENCES pull_requests(id) ON DELETE RESTRICT,
  source_branch_id uuid NOT NULL REFERENCES branches(id) ON DELETE RESTRICT,
  target_branch_id uuid NOT NULL REFERENCES branches(id) ON DELETE RESTRICT,
  -- The three states the plan was computed over, pinned: base (the PR's
  -- fixed base state), source (the proposed head at merge time), target
  -- (the target branch's head at merge time, under the row lock the merge
  -- holds). A merge is exactly this triple, so it can always be replayed.
  base_state_id uuid NOT NULL REFERENCES project_states(id) ON DELETE RESTRICT,
  source_state_id uuid NOT NULL REFERENCES project_states(id) ON DELETE RESTRICT,
  target_state_id uuid NOT NULL REFERENCES project_states(id) ON DELETE RESTRICT,
  -- The accepted state this merge committed. Written in the merge
  -- transaction (the commit's own write callback receives the state id):
  -- a merge row without a resulting state would be a record of nothing.
  -- The state_commit row that records the transition is the one whose
  -- (branch_id, result_state_id) match this row's target branch and result
  -- state — the commit row is inserted after its own write callback runs,
  -- so it cannot be referenced from inside the transaction that creates
  -- both.
  result_state_id uuid NOT NULL REFERENCES project_states(id) ON DELETE RESTRICT,
  actor_id uuid NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
  -- The executed plan: internal/rsg/merge's canonical JSON. plan_digest is
  -- sha256 over those exact bytes, so "the same three states and the same
  -- decisions produce the same merge" is checkable by recomputing it.
  plan_version text NOT NULL,
  plan jsonb NOT NULL,
  plan_digest text NOT NULL,
  -- What the plan did, rolled up (the PR's merge summary). Withheld counts
  -- the changes this merge did NOT publish — see withheld in the plan.
  applied_count int NOT NULL DEFAULT 0,
  kept_target_count int NOT NULL DEFAULT 0,
  carried_count int NOT NULL DEFAULT 0,
  aborted_count int NOT NULL DEFAULT 0,
  withheld_count int NOT NULL DEFAULT 0,
  -- The Git saga. `pending` is the state the merge transaction leaves: the
  -- database truth is committed, the GitProvider ref update has not
  -- happened yet. `updated` carries the merge commit sha; `failed` carries
  -- the error and stays retryable (attempts is the retry counter, so a
  -- stuck saga is visible instead of silent).
  git_ref text,
  git_sha text,
  git_state text NOT NULL DEFAULT 'pending'
    CHECK (git_state IN ('pending','updated','failed','skipped')),
  git_error text NOT NULL DEFAULT '',
  git_attempts int NOT NULL DEFAULT 0,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  -- A PR merges once (docs/43: `merged` is terminal); a second merge row
  -- for the same PR is a double-advance attempt and is refused here.
  UNIQUE (pull_request_id)
);

CREATE INDEX semantic_merges_project_created_idx
  ON semantic_merges (project_id, created_at DESC, id);

-- The saga's retry scan: merges whose Git step still has to happen.
CREATE INDEX semantic_merges_git_pending_idx
  ON semantic_merges (git_state, created_at)
  WHERE git_state <> 'updated';

-- 3. The conflicts this merge CARRIES instead of resolving (docs/09 §8:
-- keep both versions / explicit coexistence / contested-unresolved left in
-- main). One row per conflict of the detector's report; both side versions
-- are named, and so is the human whose decision kept them.
--
-- This table is append-only (see the trigger below): it is the record that
-- main contains an open scientific disagreement. A later decision is a new
-- merge, never an edit here.
CREATE TABLE semantic_merge_conflicts (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  merge_id uuid NOT NULL REFERENCES semantic_merges(id) ON DELETE RESTRICT,
  project_id uuid NOT NULL REFERENCES projects(id) ON DELETE RESTRICT,
  result_state_id uuid NOT NULL REFERENCES project_states(id) ON DELETE RESTRICT,
  -- The conflict identity: the same classifier key conflict_resolutions
  -- uses, so the carried record and the human decision it came from are
  -- unmistakably the same conflict.
  target_kind text NOT NULL CHECK (target_kind IN ('object','relation')),
  target_id uuid NOT NULL,
  conflict_code text NOT NULL,
  -- The docs/09 §6 category the detector classified it under.
  conflict_category text NOT NULL,
  conflict_fields jsonb NOT NULL DEFAULT '[]'::jsonb,
  conflict_payload_keys jsonb NOT NULL DEFAULT '[]'::jsonb,
  other_object_id uuid,
  detail text NOT NULL DEFAULT '',
  -- The decision that carried it (the two "keep both" actions and the
  -- explicit unresolved state); Accept A/B and Abort never reach here.
  decision text NOT NULL CHECK (decision IN ('keep_both','explicit_coexistence','unresolved')),
  decided_by uuid NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
  note text NOT NULL DEFAULT '',
  -- Both versions stay — that is what carrying the conflict means.
  source_version_id uuid NOT NULL,
  target_version_id uuid,
  created_at timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX semantic_merge_conflicts_merge_idx
  ON semantic_merge_conflicts (merge_id, target_kind, target_id);

-- The read a later decision or the PR page makes: "is this target still
-- contested in the accepted state?"
CREATE INDEX semantic_merge_conflicts_target_idx
  ON semantic_merge_conflicts (project_id, target_kind, target_id, created_at DESC);

CREATE TRIGGER semantic_merge_conflicts_append_only
  BEFORE UPDATE OR DELETE ON semantic_merge_conflicts
  FOR EACH ROW EXECUTE FUNCTION append_only_guard();

-- Row-level triggers do not fire on TRUNCATE (the 00015 lesson): without
-- this, `TRUNCATE semantic_merge_conflicts CASCADE` would erase every
-- carried conflict in one statement.
CREATE TRIGGER semantic_merge_conflicts_no_truncate
  BEFORE TRUNCATE ON semantic_merge_conflicts FOR EACH STATEMENT
  EXECUTE FUNCTION append_only_guard();

-- 4. semantic_merges is mutable in exactly one dimension: the Git saga. The
-- database truth (states, plan, counts, actor) is fixed once written —
-- anything else would let a merge record drift away from the state it
-- claims to have produced.
-- +goose StatementBegin
CREATE FUNCTION semantic_merge_guard() RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  IF TG_OP = 'UPDATE' THEN
    IF NEW.id IS DISTINCT FROM OLD.id
       OR NEW.project_id IS DISTINCT FROM OLD.project_id
       OR NEW.pull_request_id IS DISTINCT FROM OLD.pull_request_id
       OR NEW.source_branch_id IS DISTINCT FROM OLD.source_branch_id
       OR NEW.target_branch_id IS DISTINCT FROM OLD.target_branch_id
       OR NEW.base_state_id IS DISTINCT FROM OLD.base_state_id
       OR NEW.source_state_id IS DISTINCT FROM OLD.source_state_id
       OR NEW.target_state_id IS DISTINCT FROM OLD.target_state_id
       OR NEW.result_state_id IS DISTINCT FROM OLD.result_state_id
       OR NEW.actor_id IS DISTINCT FROM OLD.actor_id
       OR NEW.plan_version IS DISTINCT FROM OLD.plan_version
       OR NEW.plan IS DISTINCT FROM OLD.plan
       OR NEW.plan_digest IS DISTINCT FROM OLD.plan_digest
       -- The counts are "what this merge did" (docs/09 §8's roll-up of the
       -- plan: applied / kept target / carried / aborted / withheld). They
       -- are part of the record exactly as much as the plan they summarise:
       -- a merge whose applied_count could be edited to disagree with the
       -- plan it stored would be a record that lies about the state it
       -- produced. Same for created_at, the merge's place in the history.
       OR NEW.applied_count IS DISTINCT FROM OLD.applied_count
       OR NEW.kept_target_count IS DISTINCT FROM OLD.kept_target_count
       OR NEW.carried_count IS DISTINCT FROM OLD.carried_count
       OR NEW.aborted_count IS DISTINCT FROM OLD.aborted_count
       OR NEW.withheld_count IS DISTINCT FROM OLD.withheld_count
       OR NEW.created_at IS DISTINCT FROM OLD.created_at THEN
      RAISE EXCEPTION 'semantic merge % is immutable: only the Git saga columns move (T0406)', OLD.id
        USING ERRCODE = 'P0001';
    END IF;
    -- A finished Git step is not rewritten: updated is terminal for the
    -- ref it names (a later merge is a new row).
    IF OLD.git_state = 'updated' AND NEW.git_state <> 'updated' THEN
      RAISE EXCEPTION 'semantic merge % already updated its Git refs (sha %); the saga is finished', OLD.id, OLD.git_sha
        USING ERRCODE = 'P0001';
    END IF;
    NEW.updated_at := now();
  END IF;
  RETURN NEW;
END;
$$;
-- +goose StatementEnd

CREATE TRIGGER semantic_merge_guard_trigger
  BEFORE UPDATE ON semantic_merges
  FOR EACH ROW EXECUTE FUNCTION semantic_merge_guard();


-- ===== 00070_merge_governance.sql =====

-- Merge governance (task T0409): the Idempotency-Key ledger for the
-- Research PR merge endpoint.
--
-- docs/22 lists merge among the commands an Idempotency-Key governs: a
-- client that retries `POST /projects/{projectId}/pull-requests/{number}:merge`
-- after a network failure must get the FIRST merge back, not a second
-- one. A second merge is not a second row here — semantic_merges is
-- UNIQUE(pull_request_id) (00069) and the PR state machine reaches
-- `merged` once (00051), so the write itself is already single-shot. What
-- the ledger adds is the ANSWER: without it a retry would be told
-- "PR_ALREADY_MERGED", which is a conflict, not the accepted result the
-- first attempt produced.
--
-- The ledger copies release_creations (00053) exactly, because the
-- contract it implements is the same one (docs/22 §3, idempotent
-- create/command/publish/merge/release):
--
--   * UNIQUE(project_id, idempotency_key) — one key names one merge per
--     project, and the uniqueness is a database guarantee rather than a
--     check-then-insert race between two concurrent retries;
--   * the mesh is read-then-insert INSIDE the merge's transaction, so a
--     concurrent duplicate loses on the unique index and the whole
--     transaction (state commit included) rolls back;
--   * append-only, both halves: the 00014 row guard (no UPDATE/DELETE)
--     and the 00015 TRUNCATE guard. A replay is a read, never a rewrite —
--     the ledger entry is part of the merge's history, so it obeys the
--     same "nothing disappears" rule as the merge row it points at.
--
-- The merge_id FK is ON DELETE RESTRICT rather than CASCADE for the same
-- reason release_creations uses RESTRICT: a ledger entry without its
-- merge would silently turn a replay into a miss (the key would look
-- unused and a retry would try to merge again).

CREATE TABLE merge_creations (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  project_id uuid NOT NULL REFERENCES projects(id) ON DELETE RESTRICT,
  idempotency_key text NOT NULL,
  merge_id uuid NOT NULL REFERENCES semantic_merges(id) ON DELETE RESTRICT,
  created_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE(project_id, idempotency_key)
);

CREATE TRIGGER merge_creations_append_only
  BEFORE UPDATE OR DELETE ON merge_creations
  FOR EACH ROW EXECUTE FUNCTION append_only_guard();

CREATE TRIGGER merge_creations_no_truncate
  BEFORE TRUNCATE ON merge_creations FOR EACH STATEMENT
  EXECUTE FUNCTION append_only_guard();


-- ===== 00072_asset_publish_creations.sql =====

-- Asset publish governance (T0705): the Idempotency-Key ledger for the
-- publication of a research asset version (docs/22: an Idempotency-Key
-- governs create/command/publish/merge/release; docs/23 §4 lists the
-- publish operation itself).
--
-- A publish is a governance write, not a create that can be repeated: it
-- widens a private asset into the network's view and its result — the
-- version row — is immutable (invariant 5, and the 00014 row trigger on
-- research_asset_versions). So a retried publish MUST NOT write a second
-- version, and it must not be answered with a conflict either: the
-- request that already succeeded is the request that is being repeated,
-- and the honest answer is the version it produced. This ledger is what
-- makes that answer possible after the fact — the key maps to the
-- version the FIRST request wrote, and a replay is a read of that row.
--
-- The three existing ledgers cannot carry it, and neither could a shared
-- one:
--
--   - release_creations (00053) has a NOT NULL release_id foreign key:
--     a publish rows nothing into releases.
--   - project_milestone_creations (00063) has a NOT NULL milestone_id:
--     a publish rows nothing into project_milestones.
--   - research_asset_versions itself is keyed by (asset_id, version), and
--     the key that has to replay is the CALLER's opaque string, not a
--     version label the caller chose. Two different keys naming the same
--     version are two different requests (the second is refused by the
--     immutability guard, which is a different outcome than a replay),
--     and one key is scoped to ONE project — the scope the other two
--     ledgers use, and the scope the key is looked up in.
--
-- Append-only, like the version row it points at and like the two other
-- ledgers: a replay is a read, never a rewrite. Both halves of the guard
-- are taken from 00053/00063 — the 00014 row guard (BEFORE UPDATE OR
-- DELETE) and the 00015 TRUNCATE guard (BEFORE TRUNCATE, statement
-- level), because a ledger that can be truncated is not append-only, and
-- TRUNCATE fires no row trigger.
--
-- UNIQUE(project_id, idempotency_key) is the whole correctness claim: the
-- commit of two concurrent publishes carrying one key either creates one
-- ledger row (and one version) or fails the second on this constraint —
-- which the store answers as a replay of the winner, never as a second
-- version. It is a database guarantee, not a check-then-insert race.

CREATE TABLE asset_publish_creations (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  project_id uuid NOT NULL REFERENCES projects(id) ON DELETE RESTRICT,
  idempotency_key text NOT NULL,
  asset_version_id uuid NOT NULL REFERENCES research_asset_versions(id) ON DELETE RESTRICT,
  created_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE(project_id, idempotency_key)
);

CREATE TRIGGER asset_publish_creations_append_only
  BEFORE UPDATE OR DELETE ON asset_publish_creations
  FOR EACH ROW EXECUTE FUNCTION append_only_guard();

CREATE TRIGGER asset_publish_creations_no_truncate
  BEFORE TRUNCATE ON asset_publish_creations FOR EACH STATEMENT
  EXECUTE FUNCTION append_only_guard();


-- ===== 00078_subscriptions.sql =====

-- Subscription model (T1002, docs/18 §3): a user follows a target —
-- Project / Research Asset / Published Knowledge Object / Person /
-- Organization — and chooses which event types reach them and through
-- which channels (docs/18 §4). The table itself predates this migration
-- as a 00012 stub with no vocabulary and no lifetime; this migration
-- turns it into a model and adds the two tables the fan-out needs.
--
-- Three pieces land here:
--
--   1. subscriptions: the target/channel vocabulary as CHECKs, a live-row
--      uniqueness rule, and the soft-delete marker unsubscribing stamps.
--      The channels CHECK is a subset test, not an equality test: the
--      column's own default is '{web}' and a subscriber may add 'email'
--      later without a migration. Every write path also goes through
--      events.ValidateChannels in Go — the CHECK is the second line, for
--      a session that writes SQL directly (the same split 00059 uses for
--      the webhook registry).
--
--      Unsubscribe is a soft delete, not a row removal: the delivery rows
--      a past subscription produced must keep naming it (ON DELETE
--      RESTRICT on subscription_deliveries.subscription_id would refuse a
--      hard delete anyway), and a re-subscribe must be distinguishable
--      from a subscription that never ended. The partial unique index is
--      what makes "one live subscription per (user, target)" true: it
--      covers only rows the user has not unsubscribed from, so the
--      history of ended subscriptions is unbounded while the live set
--      stays unique.
--
--   2. subscription_deliveries: one row per (subscription, event,
--      channel). It is a POINTER, not a copy: event identity, target
--      identity and event type, never event content. Rendering the
--      content is a read of the append-only research event under the
--      renderer's own gate, exactly as webhook_deliveries pins event_type
--      so its log reads without a join. The partial unique index is the
--      fan-out's idempotency guarantee — a retried fan-out re-inserts the
--      same (subscription, event, channel) triple and hits DO NOTHING —
--      the same shape webhook_deliveries_endpoint_event_uniq gives the
--      webhook pipeline (00059).
--
--      Status: 'web' rows are born 'delivered' — the research inbox IS the
--      delivery, so there is nothing left to do (T1003 owns read/unread on
--      top of them) — while 'email' rows are born 'pending' for the
--      digest sender that consumes them (T1005). 'cancelled' is what
--      unsubscribing stamps on the rows still in flight, and what the
--      fan-out stamps when it finds a subscription whose owner can no
--      longer see the target.
--
--   3. subscription_fanned_events: the fan-out's exactly-once cursor, one
--      row per outbox row the subscription fan-out has consumed. The
--      webhook pipeline keeps the same cursor as a column on
--      outbox_events (00059's webhook_fanned_out_at); this one is its own
--      table because outbox_events is modeled by checked-in sqlc queries
--      (internal/persistence/queries/events_audit.sql: SELECT * FROM
--      outbox_events, INSERT ... RETURNING *), so a new column there
--      moves generated code outside this task's scope. The semantics are
--      identical: the cursor row is written in the same transaction that
--      writes the deliveries, so a crash between them re-runs the
--      idempotent fan-out instead of losing the event, and each consumer
--      marks its own progress without ordering assumptions about what the
--      publisher has published so far.

ALTER TABLE subscriptions
  ADD COLUMN updated_at timestamptz NOT NULL DEFAULT now(),
  ADD COLUMN deleted_at timestamptz;

ALTER TABLE subscriptions
  ADD CONSTRAINT subscriptions_target_type_valid
    CHECK (target_type IN ('project', 'asset', 'knowledge', 'user', 'organization')),
  ADD CONSTRAINT subscriptions_target_id_present
    CHECK (target_id <> ''),
  ADD CONSTRAINT subscriptions_channels_valid
    CHECK (cardinality(channels) > 0 AND channels <@ ARRAY['web', 'email']::text[]);

-- The target id's shape per type: a uuid for the four targets the
-- resolution queries cast, the asset pid for an asset (the same regexp
-- research_assets_pid_format enforces on the pid column, migration 00064).
-- events.ValidateTargetID checks the identical shapes on the application
-- path; this is the second line, for a session that writes SQL directly —
-- and it is what makes the uuids above castable inside a query instead of
-- a runtime error the fan-out would have to survive.
ALTER TABLE subscriptions
  ADD CONSTRAINT subscriptions_target_id_shape
    CHECK (CASE target_type
             WHEN 'asset' THEN target_id ~ '^[0-9a-hjkmnp-tv-z]{26}$'
             ELSE target_id ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
           END);

COMMENT ON TABLE subscriptions IS
  'One user following one target (T1002, docs/18 §3). target_type is the canonical target vocabulary; target_id is the target''s stable identity — a uuid for project/knowledge/user/organization, the asset pid for asset (the same identifier /assets/{pid} is built from). deleted_at is the unsubscribe marker: a deleted subscription matches no fan-out, and its in-flight deliveries are cancelled in the same transaction.';

COMMENT ON COLUMN subscriptions.event_filters IS
  'Event types this subscription delivers, exact match (events.ValidateEventFilters); empty means every event the target addresses. The canonical vocabulary is specs/events/event-types.yaml — it is not duplicated here or in code, so an unknown type simply never matches.';

COMMENT ON COLUMN subscriptions.channels IS
  'Output interfaces this subscription delivers through (docs/18 §4): web = the research inbox (a delivered delivery row, T1003), email = the digest sender''s queue (a pending delivery row, T1005). A non-empty subset of the vocabulary.';

COMMENT ON COLUMN subscriptions.deleted_at IS
  'soft-delete marker: set when the owner unsubscribes; NULL = live. Nothing disappears (CLAUDE.md §9.8) — the row keeps its id so the deliveries it produced still name it, and the live-row unique index lets the same (user, target) be followed again as a NEW row.';

-- One live subscription per (user, target). Ended subscriptions are not
-- covered, so a re-subscribe after an unsubscribe inserts a new row.
CREATE UNIQUE INDEX subscriptions_live_uniq
  ON subscriptions (user_id, target_type, target_id)
  WHERE deleted_at IS NULL;

-- The fan-out's candidate scan: live subscriptions for one target. The
-- lookup is by target, so the index leads with the target columns.
CREATE INDEX subscriptions_live_target_idx
  ON subscriptions (target_type, target_id)
  WHERE deleted_at IS NULL;

CREATE TABLE subscription_deliveries (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  subscription_id uuid NOT NULL REFERENCES subscriptions(id) ON DELETE RESTRICT,
  user_id uuid NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
  event_id uuid NOT NULL REFERENCES research_events(id) ON DELETE RESTRICT,
  channel text NOT NULL CHECK (channel IN ('web', 'email')),
  event_type text NOT NULL,
  target_type text NOT NULL,
  target_id text NOT NULL,
  status text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'delivered', 'cancelled')),
  created_at timestamptz NOT NULL DEFAULT now(),
  delivered_at timestamptz,
  cancelled_at timestamptz,
  CHECK ((status = 'delivered') = (delivered_at IS NOT NULL)),
  CHECK ((status = 'cancelled') = (cancelled_at IS NOT NULL))
);

COMMENT ON TABLE subscription_deliveries IS
  'One notification per (subscription, event, channel): the pointer the research inbox (T1003) and the digest sender (T1005) read. It carries NO event content — event_id names the append-only research event and target_type/target_id name the subject, so rendering is a read under the renderer''s own current-authorization gate. The partial unique index makes the fan-out idempotent.';

COMMENT ON COLUMN subscription_deliveries.status IS
  'pending = in flight for a channel that has a sender (email); delivered = delivered (the web channel is delivered the moment the row exists — the inbox row IS the delivery, and read/unread on top of it is T1003); cancelled = withdrawn before delivery, by the owner unsubscribing or by the fan-out finding the subscriber can no longer see the target.';

COMMENT ON COLUMN subscription_deliveries.user_id IS
  'The subscriber the row was fanned out for, denormalized from the subscription so the inbox reads one table and so a cancelled-then-re-followed target cannot re-attribute an old row to a new subscription.';

COMMENT ON COLUMN subscription_deliveries.event_type IS
  'The fanned-out event''s type, pinned at fan-out (the delivery must read without a join into the append-only event log — the same reason webhook_deliveries pins it).';

COMMENT ON COLUMN subscription_deliveries.cancelled_at IS
  'When the row was cancelled. Set together with status = cancelled (the CHECK pairs them), so a withdrawn notification is auditable rather than merely gone.';

-- The fan-out's idempotency guarantee: retried fan-outs hit DO NOTHING.
CREATE UNIQUE INDEX subscription_deliveries_uniq
  ON subscription_deliveries (subscription_id, event_id, channel);

-- The inbox read (T1003): one subscriber's deliveries, newest first.
CREATE INDEX subscription_deliveries_inbox_idx
  ON subscription_deliveries (user_id, status, created_at DESC, id DESC);

-- Unsubscribe and revocation cancel in-flight rows of one subscription.
CREATE INDEX subscription_deliveries_pending_idx
  ON subscription_deliveries (subscription_id)
  WHERE status = 'pending';

CREATE TABLE subscription_fanned_events (
  outbox_event_id uuid PRIMARY KEY REFERENCES outbox_events(id) ON DELETE RESTRICT,
  fanned_at timestamptz NOT NULL DEFAULT now()
);

COMMENT ON TABLE subscription_fanned_events IS
  'The subscription fan-out''s exactly-once cursor (T1002): one row per outbox row the fan-out has consumed, written in the same transaction as that row''s delivery inserts, so a crash between the two re-runs an idempotent fan-out instead of losing an event. It lives in its own table rather than as a column on outbox_events because outbox_events is modeled by checked-in sqlc queries (SELECT * / RETURNING *), which a new column would move.';


-- ===== 00079_research_inbox.sql =====

-- The research inbox (T1003): the read/unread half of the notification
-- row, on top of the delivery rows T1002's subscription fan-out already
-- writes.
--
-- T1002 left the delivery row as a POINTER (subscription, event, channel,
-- target, event type — never event content) and made the web channel born
-- 'delivered', with this note in its own migration: "the web channel is
-- delivered the moment the row exists — the inbox row IS the delivery, and
-- read/unread on top of it is T1003". This migration adds exactly that
-- marker. Nothing else about the delivery changes: the row is still one
-- notification, still owner-scoped, still a pointer.
--
-- Why a column on the delivery rather than a second table (for example a
-- per-user "inbox entries" table that the fan-out would upsert):
--
--   * the delivery row is already the unit a fan-out pass can produce at
--     most once (subscription_deliveries_uniq), so read state lands on a
--     row that cannot be duplicated — no second write path, no second
--     cursor, no window in which a listed notification has no read state;
--   * the AGGREGATION the inbox renders ("12 commits on this project in
--     this hour") is a GROUP BY over these rows, not a stored object: a
--     stored entry would have to be maintained when a delivery is
--     cancelled by the revocation path (T1002's cancelUndeliverable-
--     Deliveries), and every such maintenance is a chance for the inbox
--     to show a notification the authorization rule already withdrew.
--     Derived from live rows, a withdrawn delivery simply stops counting;
--   * read state is per delivery, so "mark this hour's burst read" is an
--     UPDATE over the rows that were actually shown, and a delivery that
--     arrives a second later is NOT silently marked read by it.
--
-- read_at IS NULL means unread. There is no boolean: when it was read is
-- worth keeping (an unread count is a question about the present, the
-- read time is a fact about the past), and NULL is the only value that
-- cannot be confused with a real timestamp.
--
-- The CHECK pairs read_at with 'delivered' the way 00078 pairs
-- delivered_at/cancelled_at with their statuses: a 'pending' row is one
-- the email digest has not sent yet and a 'cancelled' row is one the
-- authorization rule withdrew, so neither has been SHOWN to anyone and
-- neither can be read. The pairing is what keeps "unread" from being
-- satisfiable by rows that were never in the inbox to begin with.
ALTER TABLE subscription_deliveries
  ADD COLUMN read_at timestamptz;

ALTER TABLE subscription_deliveries
  ADD CONSTRAINT subscription_deliveries_read_at_delivered
    CHECK (read_at IS NULL OR status = 'delivered');

COMMENT ON COLUMN subscription_deliveries.read_at IS
  'When the subscriber read this notification; NULL = unread. Set only on delivered rows (the CHECK pairs it with status), and only by the inbox''s own mark-read path (T1003). The inbox aggregates these rows by (target, event type, hour) instead of storing an entry object, so a delivery the T1002 revocation path cancels stops counting toward an entry rather than leaving a stale one behind.';

-- The mass "mark my inbox read" update: one subscriber's unread delivered
-- web rows. The predicate and the leading column are the WHERE clause of
-- markInboxAllRead (internal/events/inbox_store.go) — user_id,
-- channel = 'web', status = 'delivered', read_at IS NULL — so the
-- statement has an index of its own shape to find its rows through.
--
-- The statement also carries an audience test (a (target_type, target_id)
-- IN (…) list built from the caller's visible targets, ruling 5 of T1003),
-- and this index does NOT cover it: the list is per call and not a column
-- of this table, so no index can. It is applied to the rows this index
-- finds, which is the cheap order — the index narrows to one subscriber's
-- unread rows first, and the audience test then removes the few the caller
-- may no longer read.
--
-- It does NOT answer the badge or the "unread" view, and no index of that
-- shape can: the entries read needs the READ rows too (an entry's count is
-- the same in both views, and the "all" view lists read entries), so a
-- partial index whose predicate excludes them can never serve it.
-- subscription_deliveries_inbox_idx (00078) is the index for that read.
CREATE INDEX subscription_deliveries_unread_idx
  ON subscription_deliveries (user_id, created_at DESC, id DESC)
  WHERE channel = 'web' AND status = 'delivered' AND read_at IS NULL;


-- ===== 00080_public_feed_indexes.sql =====

-- Public feed reads (T1004, docs/18 §4 "RSS/Atom（公开对象/项目）").
--
-- This migration adds NO table and NO column: a feed is DERIVED from rows
-- that already exist — a project's publicly published asset versions and
-- knowledge publications — so there is nothing here to keep in sync and
-- nothing that can drift from the canonical store (CLAUDE.md §8: PostgreSQL
-- holds the semantic truth; a feed is a view of it, not a second copy).
--
-- What it adds is the indexing those reads need, and nothing else. The two
-- feed routes are ANONYMOUS: any client on the network may ask for a public
-- project's feed, repeatedly, and the read behind it walks every asset and
-- every object of that project. Without these two indexes both walks are
-- sequential scans of tables that grow with the whole platform's output —
-- the shape docs/27 rules out for a public read, and the reason migration
-- 00036 exists for the RSG query surface.
--
-- Neither index carries semantic content: dropping both leaves every answer
-- identical and only changes how long the database takes to give it.

-- research_assets.origin_project_id is the join key of the project feed
-- ("the public versions of this project's assets") and until now it had no
-- index at all — the column is written once at asset creation (migration
-- 00010) and read by the asset page's pins. The project feed reads it on
-- every anonymous request for the newest N published versions.
CREATE INDEX research_assets_origin_project_idx
  ON research_assets (origin_project_id);

-- The per-asset version read, restricted to the versions a public feed may
-- render. The partial predicate is the feed's own filter
-- (research_asset_versions.visibility, migration 00010), so the index holds
-- exactly the rows a public reader can be served and skips the private ones
-- — which also means the index size tracks the platform's PUBLIC output
-- rather than its total output.
--
-- The ordering columns are the feed's ordering (published_at DESC, id DESC):
-- two entries published in the same instant are ordered by their immutable
-- id, so one state renders one document, byte for byte, on every request.
CREATE INDEX research_asset_versions_public_published_idx
  ON research_asset_versions (asset_id, published_at DESC, id DESC)
  WHERE visibility = 'public';


-- ===== 00081_email_digest.sql =====

-- Email digest (T1005, docs/18 §4: "Email immediate/digest abstraction";
-- docs/20 §9 lists "notification digest" among the Go worker's jobs). The
-- delivery rows this pipeline consumes already exist — subscription_deliveries
-- rows with channel = 'email' are born 'pending' for exactly this sender
-- (00078) — so this migration adds the two things a *sender* needs that a
-- fan-out does not: the subscriber's cadence preference, and the claim state
-- that makes an at-least-once send safe to retry.
--
--   1. notification_preferences: how often ONE account wants its email
--      notifications — immediate (each event on its own), daily or weekly (the
--      events of the interval in one digest). It is a property of the account,
--      not of a subscription: a subscription already chooses channels
--      (00078's channels column is where "email or not" lives), and asking the
--      same user to restate their cadence once per target would be asking them
--      to keep N copies of one preference in sync.
--
--      A missing row is NOT a special case: it means the default cadence, and
--      the sender reads DefaultCadence (events.NotificationPreferences) rather
--      than treating an absent row as "no email". An account that never
--      opened the setting still has one defined behaviour, and it is the
--      sender — not the presence of a settings row — that decides what that
--      behaviour is.
--
--      last_digest_at is the interval anchor: a digest-style cadence
--      (daily/weekly) is due once this much time has passed since the last
--      one, so the schedule is drift-free (a delayed digest does not push the
--      next one out) and needs no per-user timer table. Immediate does not
--      read it — every event is its own digest — and the column is still
--      stamped for it, so a switch from immediate to daily starts its
--      interval from a real send rather than from the row's created_at.
--
--   2. subscription_deliveries.attempts / leased_until: the claim state of
--      the digest sender. The sender cannot hold a database transaction open
--      across a mail submission (a slow SMTP submission inside a transaction
--      is a lock held for a network round trip, for every subscriber in the
--      batch at once), so it claims under a LEASE instead: the claim stamps
--      leased_until, commits, sends, and marks the row delivered. A row whose
--      send failed is simply due again when the lease expires — the same
--      at-least-once shape the webhook deliverer uses (00059's
--      attempts/next_attempt_at), and the reason a crash mid-send costs a
--      duplicate email rather than a lost one.
--
--      attempts bounds that retry: it is what the sender's withdrawal rule
--      counts, so a delivery that can never be sent is withdrawn with a
--      recorded reason instead of being retried forever. The columns are
--      added to subscription_deliveries rather than to a sender-side table
--      because they are the STATE OF THE DELIVERY ROW the sender is working
--      on: a second table keyed by delivery id would be one more thing that
--      has to agree with the row it describes.
--
--      Both columns are read and written by raw SQL (events.NotificationStore,
--      like every other subscription_deliveries reader) — subscription tables
--      are not modeled by checked-in sqlc queries, so this migration moves no
--      generated code.

CREATE TABLE notification_preferences (
  user_id uuid PRIMARY KEY REFERENCES users(id) ON DELETE RESTRICT,
  cadence text NOT NULL DEFAULT 'daily' CHECK (cadence IN ('immediate', 'daily', 'weekly')),
  last_digest_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);

COMMENT ON TABLE notification_preferences IS
  'How often one account receives its email notifications (T1005, docs/18 §4): immediate = one message per event, daily/weekly = one digest per interval. One row per account that has ever changed the setting; NO row means the default cadence (events.DefaultCadence), so absence is never "no email".';

COMMENT ON COLUMN notification_preferences.cadence IS
  'The account''s email cadence (events.CadenceImmediate/CadenceDaily/CadenceWeekly; events.ValidateCadence checks the same vocabulary on the application path). Default daily: docs/18 §3 asks the platform not to notify on every low-level event by default, and email is the channel that leaves the building.';

COMMENT ON COLUMN notification_preferences.last_digest_at IS
  'When this account''s last email digest was actually handed to the mail transport. The interval anchor for a digest cadence: a daily/weekly digest is due once last_digest_at is older than the cadence window (events.DigestDue). NULL = no digest sent yet, which is due immediately — a subscriber never waits a full interval for their first digest.';

ALTER TABLE subscription_deliveries
  ADD COLUMN attempts integer NOT NULL DEFAULT 0,
  ADD COLUMN leased_until timestamptz;

ALTER TABLE subscription_deliveries
  ADD CONSTRAINT subscription_deliveries_attempts_nonnegative CHECK (attempts >= 0);

COMMENT ON COLUMN subscription_deliveries.attempts IS
  'How many times the digest sender has claimed this row (T1005). Counted against the sender''s withdrawal limit: a row that exhausts it is withdrawn with a recorded reason rather than retried forever. Web rows never increment it — the inbox IS their delivery.';

COMMENT ON COLUMN subscription_deliveries.leased_until IS
  'The claim lease the digest sender holds on this row: a pending row whose lease is set and not yet expired is being sent by a worker and is not claimable again. NULL (or expired) = claimable. The lease is what lets the send happen outside a transaction without two senders mailing the same notification.';

-- The digest sender's claim scan: pending email rows, oldest first, whether
-- or not they are currently leased (the claim filters on the lease itself —
-- the index only has to make the partial predicate cheap).
CREATE INDEX subscription_deliveries_email_pending_idx
  ON subscription_deliveries (created_at, id)
  WHERE channel = 'email' AND status = 'pending';


-- ===== 00082_asset_governance_rights_holder.sql =====

-- Asset governance (T0711): the parties a published asset version credits,
-- and the asset's rights-holder chain.
--
-- # The gap this closes
--
-- The publish gate validates the creator ids a publish declares
-- (internal/assets.PublishCandidate.CreatorIDs, checked by
-- validation.CheckAssetContributors) and NOTHING stored them: the version
-- row's only actor is published_by. The platform therefore asked a
-- publisher for a signature list at publish time, checked it, and dropped
-- it — and the asset page could only name the publisher as the credited
-- party, under a role that said so (internal/assets/page.go's PageCreator
-- comment, which names the missing half as "a schema change").
-- asset_version_parties is that half: the declaration lands in a row.
--
-- # Six roles, three shapes, and never one merged "owner"
--
-- docs/11 §6 is one sentence that fixes the whole model: "分离 Rights
-- Holder、Custodian、Maintainer、Creator、Contributor、Originating Project。
-- Ownership transfer 是 append-only governance event；Creator/history 永久
-- 保留。" Six roles, separated — and the two sentences after the commas
-- are why they do not all live in one table:
--
--   - creator, contributor, custodian, maintainer are facts about a
--     VERSION: who is credited for this published artifact. They are part
--     of the immutable version record (00014's row trigger on
--     research_asset_versions), written once, and never revised —
--     "Creator/history 永久保留". That is asset_version_parties.
--   - the rights holder is a fact about the ASSET: who holds it, which
--     CHANGES, and every change is its own append-only event. A transfer
--     publishes no version and touches no version row, so the holder
--     cannot live in a version-scoped table without either falsifying the
--     version it was attached to or forcing every transfer to write a
--     version. That is asset_rights_holder_events.
--   - the originating project is the asset's own origin
--     (research_assets.origin_project_id, NOT NULL since 00010) — a
--     project, which is neither a person nor an organization. Storing it
--     a second time here would give one fact two sources that can
--     disagree, so it is not duplicated; a reader renders it as a party
--     of kind "project" from the column that already owns it.
--
-- The three shapes are deliberate, and so is the absence of a fourth: no
-- polymorphic actor_id column, and no new "party" table that would hold
-- users and organizations in one place again. A party is recorded as
-- WHICH KIND of identity it is AND WHICH ROW — two columns, always
-- together — so no reader can hold an id without knowing whether it names
-- a person or an organization. owner ruling L3-20260916-1 (tasks/
-- decisions.md: "权利人可以是组织；人和组织分开记") is exactly this, and
-- migration 00002 already stores the two kinds in two tables (users,
-- organizations); the kind column is what keeps them apart here.
--
-- # Both tables admit exactly the two IDENTITY kinds — user and organization
--
-- A row of either table names a person or an institution, and the kind
-- column says which. Neither admits a project, and that is the point
-- rather than an omission: docs/11 §6 lists Originating Project as one of
-- the six roles precisely because it is NOT a person and NOT an
-- organization, and its value (and every reader of it) is
-- research_assets.origin_project_id, which owns that fact. A party id
-- pointing into projects from here would be a second home for the
-- originating project, in a table whose readers would then have to decide
-- which of the two was authoritative.
--
-- The vocabulary of kinds is three (internal/domain.PartyKind: user,
-- organization, project — the three identity tables the platform has),
-- and each storage site admits the subset it can hold. That asymmetry is
-- deliberate and stated in both places rather than implied by one.
--
-- The writer that exists today is the publish path, whose declaration is
-- a list of user ids (internal/assets.validCreatorIDs: "the version
-- credits at least one user"), so 'user' is what it writes; 'organization'
-- is admitted because the rights-holder ruling L3-20260916-1 requires an
-- organization to be recordable as a holder, and because group and
-- institutional credit is a party kind this model must be able to say.
--
-- # Neither table carries a foreign key to its party, deliberately
--
-- A (kind, id) reference cannot be a single-column foreign key: the id
-- points into users for one kind and organizations for the other (and
-- projects for the third). The alternative — a trigger, or a CHECK
-- against a subquery, which PostgreSQL forbids — would put a second
-- definition of "a party exists" in the database, where the two tables it
-- would have to read are the very thing the kind column exists to keep
-- apart. The reference's integrity is the writing command's business, and
-- the two writing paths guarantee different halves of it:
--
--   - asset_version_parties (a credit) is written by the publish
--     transaction, whose gate checks the id's SHAPE and nothing else
--     (internal/assets.validCreatorIDs: a uuid, because the column is
--     one). The gate cannot look anything up, and the publish path does
--     not resolve the user either, so a credit may name a user id no
--     users row holds.
--   - asset_rights_holder_events is written by
--     internal/application/assetrights, which resolves the named party
--     against the table its kind names BEFORE it writes, and refuses a
--     kind/id that names no row.
--
-- 00066 says the same thing about the rights document's vocabulary: the
-- one definition lives in Go, and a second spelling of it in SQL drifts.
--
-- # Append-only, both tables, both halves
--
-- Both tables are history: a credit is part of a version's permanent
-- record, and a held relationship is a governance event that a later
-- event supersedes rather than edits. Both therefore take the 00014 row
-- guard (BEFORE UPDATE OR DELETE) and the 00015 statement guard (BEFORE
-- TRUNCATE — a row trigger does not fire on TRUNCATE, and a table that
-- can be truncated is not append-only). "转移之后，转移之前的持有关系仍要
-- 读得出来" is the acceptance this enforces: the previous holder is a row
-- that cannot be overwritten.

CREATE TABLE asset_version_parties (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  asset_version_id uuid NOT NULL REFERENCES research_asset_versions(id) ON DELETE RESTRICT,
  role text NOT NULL CHECK (role IN ('creator', 'contributor', 'custodian', 'maintainer')),
  party_kind text NOT NULL CHECK (party_kind IN ('user', 'organization')),
  party_id uuid NOT NULL,
  -- position is the order the declaring caller sent this party in. It is
  -- stored rather than reconstructed from created_at or from the row id,
  -- because the acceptance for a credit list is that it reads back
  -- "逐项一致" (item by item) with the request: a signature list has an
  -- order, an unordered set does not reproduce one, and gen_random_uuid
  -- does not sort the way anyone declared anything.
  position integer NOT NULL CHECK (position >= 0),
  -- recorded_by is the authenticated actor whose request declared the
  -- credit (the publisher, for the publish path). NOT NULL: a credit with
  -- no attributable declarer would be an anonymous assertion about
  -- someone else's authorship.
  recorded_by uuid NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
  recorded_at timestamptz NOT NULL DEFAULT now(),
  -- One party per role per position, and no party twice in one role: a
  -- declaration that names the same user as creator at two positions is a
  -- malformed list, not a stronger claim, and the database refusing it is
  -- cheaper than every reader having to decide which of two identical
  -- rows to render.
  UNIQUE (asset_version_id, role, party_id),
  UNIQUE (asset_version_id, role, position)
);

COMMENT ON TABLE asset_version_parties IS
  'The parties one published asset version credits, per docs/11 §6 roles (creator, contributor, custodian, maintainer). Append-only: a credit is part of the immutable version record and is never revised — "Creator/history 永久保留". Written by the publish path (T0711) inside the publish transaction, so a version either carries its declared credits or does not exist.';

CREATE TRIGGER asset_version_parties_append_only
  BEFORE UPDATE OR DELETE ON asset_version_parties
  FOR EACH ROW EXECUTE FUNCTION append_only_guard();

CREATE TRIGGER asset_version_parties_no_truncate
  BEFORE TRUNCATE ON asset_version_parties FOR EACH STATEMENT
  EXECUTE FUNCTION append_only_guard();

CREATE INDEX asset_version_parties_version_role
  ON asset_version_parties (asset_version_id, role, position);

CREATE TABLE asset_rights_holder_events (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  asset_id uuid NOT NULL REFERENCES research_assets(id) ON DELETE RESTRICT,
  -- ordinal orders the chain. It is a per-asset sequence rather than a
  -- timestamp because the chain's whole meaning is an order, and two
  -- events in one transaction share now() exactly: ordering by
  -- recorded_at alone would leave the current holder to a tie-break
  -- nobody declared. The transfer takes the asset row lock
  -- (SELECT … FOR UPDATE) before reading the current maximum, so the
  -- sequence is serialized per asset rather than computed in a race.
  ordinal integer NOT NULL CHECK (ordinal >= 1),
  holder_kind text NOT NULL CHECK (holder_kind IN ('user', 'organization')),
  holder_id uuid NOT NULL,
  -- The holder this event supersedes. NULL means "there was no holder
  -- before this event" — the first designation of an asset nobody held.
  -- It is an honest absence and never a fabricated party: the column
  -- admits no default, and the pair is all-or-nothing (the CHECK below).
  previous_holder_kind text CHECK (previous_holder_kind IN ('user', 'organization')),
  previous_holder_id uuid,
  -- who asked for the change (the owner whose request it was), and when.
  recorded_by uuid NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
  recorded_at timestamptz NOT NULL DEFAULT now(),
  -- One event per ordinal: the chain is a sequence, and two events at one
  -- position would make "the event after this one" ambiguous.
  UNIQUE (asset_id, ordinal),
  -- The previous holder is a kind AND an id, or neither.
  CONSTRAINT asset_rights_holder_events_previous_complete
    CHECK ((previous_holder_kind IS NULL) = (previous_holder_id IS NULL)),
  -- A change that changes nothing is not a change. Refusing it here, and
  -- not only in the command, means the chain never carries an event whose
  -- before and after are the same party — which is what makes "the
  -- previous holder" a real fact about every row after the first.
  CONSTRAINT asset_rights_holder_events_previous_differs
    CHECK (previous_holder_kind IS NULL
           OR (previous_holder_kind, previous_holder_id) IS DISTINCT FROM (holder_kind, holder_id))
);

COMMENT ON TABLE asset_rights_holder_events IS
  'The append-only chain of rights-holder designations and transfers for one research asset (docs/11 §6: "Ownership transfer 是 append-only governance event"; docs/26 §5 lists ownership transfer among the highest-risk audited actions). Each row is one event: the holder it names, the holder it supersedes (NULL for the first), who asked and when. The current holder is the row with the greatest ordinal; every earlier holder remains readable, which is the acceptance "转移之后，转移之前的持有关系仍要读得出来". Nothing here is updated or deleted — a later transfer appends.';

CREATE TRIGGER asset_rights_holder_events_append_only
  BEFORE UPDATE OR DELETE ON asset_rights_holder_events
  FOR EACH ROW EXECUTE FUNCTION append_only_guard();

CREATE TRIGGER asset_rights_holder_events_no_truncate
  BEFORE TRUNCATE ON asset_rights_holder_events FOR EACH STATEMENT
  EXECUTE FUNCTION append_only_guard();

CREATE INDEX asset_rights_holder_events_asset_ordinal
  ON asset_rights_holder_events (asset_id, ordinal DESC);


-- ===== 00083_knowledge_publication_identity.sql =====

-- Published knowledge object identity and publish idempotency (T0805).
--
-- knowledge_publications has existed since 00010 with no writer at all: the
-- table was created for the publication of a scientific object version
-- (docs/03 §: a Published Knowledge Object is a Research Question /
-- Hypothesis / Claim / Finding version explicitly published to the
-- network), the event name has been in specs/events/event-types.yaml since
-- the vocabulary was written, and the public read route has been in the
-- contract — but nothing had ever inserted a row. T0805 is the publish
-- path, and this migration adds the two things that path needs and the
-- table cannot express.
--
-- 1. pid — the publication's persistent identifier.
--
-- The published knowledge object is the thing that is referenced across
-- projects (docs/05 §: every page displays a persistent identity) and the
-- thing GET /knowledge/{knowledgeId} resolves. Its identity is minted ONCE,
-- at publication, exactly as a research asset's pid is minted at its
-- publication (00064): 26 lowercase Crockford base32 characters, random,
-- never derived from the version label, the title, the object, or the
-- project — all of which are revisable, and an identifier derived from a
-- revisable attribute is not persistent (00064's own acceptance: asset ID
-- 不随 slug/org 变化).
--
-- The column sits on the PUBLICATION rather than on scientific_objects, and
-- that is the shape of the domain and not a preference:
--
--   - docs/03 defines the Published Knowledge Object as a VERSION, not as
--     the object that carries it; what is published (and what a foreign
--     project cites) is one version.
--   - owner ruling L3-20260916-1 #3 (tasks/decisions.md) makes a version
--     publishable exactly once, so publication and version are 1:1 and the
--     publication's pid IS that version's public identity.
--   - the same ruling is what removes the ambiguity the public read would
--     otherwise have: resolving a pid yields exactly one row, so
--     GET /knowledge/{knowledgeId} never has to invent a rule for which row
--     of a multi-row publication history to answer with.
--
-- A pid on scientific_objects would instead hand out a public identity to
-- objects nobody has published (the identity must mean "this is out on the
-- network"), and would still leave a pid naming several published versions.
--
-- The DEFAULT is a random uuid's first 26 hex characters — a Crockford
-- subset — so a row inserted by anything that does not go through the
-- application still gets a valid, unique pid. It is a fallback, not the
-- path: the publish command mints the pid with assets.NewPID() (the
-- generator 00064 names as "the application-generated path ... arrives with
-- the publish command"), and the CHECK below is the Go predicate's mirror.
-- The table is empty at this commit — no code path has ever written a row —
-- so the NOT NULL + DEFAULT is a column addition, never a backfill.
--
-- 2. knowledge_publication_creations — the Idempotency-Key ledger.
--
-- docs/22 gives an Idempotency-Key to create/command/publish/merge/release,
-- and the knowledge publish carries one (specs/api/openapi.yaml, the same
-- header the asset publish declares). A publish is a governance write whose
-- result is immutable, so a retried publish must NOT write a second
-- publication and must not be answered with a conflict either: the request
-- that already succeeded is the request being repeated, and the honest
-- answer is the publication it produced. This ledger is what makes that
-- answer possible after the fact — the key maps to the publication the
-- FIRST request wrote, and a replay is a read of that row.
--
-- The four existing ledgers cannot carry it: release_creations (00053) and
-- project_milestone_creations (00063) both have a NOT NULL foreign key to
-- the row their operation creates (a publish writes no release and no
-- milestone), and asset_publish_creations (00072) is scoped to a
-- research_asset_versions row, a different table with a different subject.
-- The scope is the project, as it is for all three.
--
-- Append-only, like the row it points at and like the other ledgers: both
-- halves of the guard are taken from 00053/00063/00072 — the 00014 row guard
-- (BEFORE UPDATE OR DELETE) and the 00015 TRUNCATE guard (BEFORE TRUNCATE,
-- statement level), because a ledger that can be truncated is not
-- append-only and TRUNCATE fires no row trigger.
--
-- UNIQUE(project_id, idempotency_key) is the whole correctness claim: two
-- concurrent publishes carrying one key either create one ledger row (and
-- one publication) or fail the second on this constraint, which the store
-- answers as a replay of the winner, never as a second publication.

ALTER TABLE knowledge_publications
  ADD COLUMN pid text NOT NULL
    DEFAULT substr(replace(gen_random_uuid()::text, '-', ''), 1, 26);

ALTER TABLE knowledge_publications
  ADD CONSTRAINT knowledge_publications_pid_format
    CHECK (pid ~ '^[0-9a-hjkmnp-tv-z]{26}$');

CREATE UNIQUE INDEX knowledge_publications_pid_uniq ON knowledge_publications (pid);

-- One publication per object version (owner ruling L3-20260916-1 #3).
--
-- This is an APPLICATION rule and it is enforced there: the command reads
-- the version's publication before it writes and refuses a second one,
-- because the table's own UNIQUE(object_version_id, public_version) (00010)
-- only forbids reusing the same NAME — publishing the same version again
-- under a different public_version would satisfy it and still be the second
-- publication the ruling forbids. A unique index on object_version_id alone
-- would express the rule exactly, and it is deliberately NOT added here:
-- the ruling is a product rule ("同一个知识对象版本只能对外发布一次"), and
-- encoding a product rule as a schema constraint makes it unchangeable by
-- any later ruling that allows, say, a corrected republication under a new
-- public_version. The application refuses it, with a test that pins the
-- refusal (tests/integration/knowledge_publish_test.go), and that test is
-- what the reviewer checks — not a constraint nobody can cite.

CREATE TABLE knowledge_publication_creations (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  project_id uuid NOT NULL REFERENCES projects(id) ON DELETE RESTRICT,
  idempotency_key text NOT NULL,
  publication_id uuid NOT NULL REFERENCES knowledge_publications(id) ON DELETE RESTRICT,
  created_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE(project_id, idempotency_key)
);

CREATE TRIGGER knowledge_publication_creations_append_only
  BEFORE UPDATE OR DELETE ON knowledge_publication_creations
  FOR EACH ROW EXECUTE FUNCTION append_only_guard();

CREATE TRIGGER knowledge_publication_creations_no_truncate
  BEFORE TRUNCATE ON knowledge_publication_creations FOR EACH STATEMENT
  EXECUTE FUNCTION append_only_guard();


-- ===== 00084_research_owner_routing.sql =====

-- Scientific responsibility and Research Owners routing (task T0604,
-- docs/04 §3 "Scientific Responsibility").
--
-- docs/04 §3 is two sentences and both are normative here:
--
--   「不与 Access Role 混合。项目可配置：Experimental Reviewer、
--     Computational Reviewer、Data Reviewer、Project Lead、IP Reviewer
--     等责任标签。责任用于 Review routing，不自动赋予更高访问权限。」
--   「类似 CODEOWNERS 的 Research Owners 规则可按对象类型/Schema/领域
--     匹配 reviewer。」
--
-- So the responsibility LABELS and the routing RULES are PROJECT DATA,
-- not code: the label set is open ("等" — "etc."), and which label owns
-- which change is a per-project mapping. Two tables carry that data, and
-- neither of them is a permission table:
--
--   1. research_owner_rules — the CODEOWNERS-like mapping: a change to
--      objects matched by object_type, by schema (schema_ref.id: a
--      canonical type schema or a project schema profile, T0213) or by
--      the object payload's `domain` field (the protocol schema's
--      subject-area field, docs/04 §3's 「领域」) is routed to a
--      responsibility label. Several rules may match one change; the
--      change then requires every matched label (union, never
--      first-match-wins: a rule is a requirement, and dropping one
--      because another matched first would relax the routing).
--
--   2. responsibility_assignments — who holds which label in which
--      project. UNIQUE(project_id, user_id, responsibility): holding a
--      label is one fact, and re-assigning it is idempotent rather than
--      a second row.
--
-- NEITHER table takes part in any authorization decision. docs/04 §3:
-- 「责任用于 Review routing，不自动赋予更高访问权限」. Access is decided
-- by the permission matrix (specs/policies/permissions-matrix.csv,
-- internal/authz) alone; internal/authz does not read these tables at
-- all. What a label buys its holder is exactly one thing: the
-- right to submit a review where the matrix says 'conditional'
-- (submit_scientific_review for viewer/contributor/authenticated
-- non-member), and the attribution of that review to the responsibility
-- it was signed under.
--
-- Both tables are ordinary project configuration, not governance
-- history: a rule that no longer applies is DELETED (the project owner's
-- decision), which is why neither carries the append-only guards of
-- 00014/00015. Every write is audited (the application writes its
-- audit_log row in the same transaction — T0110's discipline), so the
-- history of the mapping survives in the audit log, not in the table.
-- (What the tables DO share with the rest of the schema is the FK
-- discipline: every reference is ON DELETE RESTRICT. Nothing in POST
-- hard-deletes a project or a user — docs/09's 「Nothing disappears」
-- — so a cascade would only ever be a silent data-loss path.)
--
-- Bounds are enforced here as well as in the domain layer (the same
-- two-layer discipline as migration 00061's reviews columns): a label or
-- a match value is 1..200 characters and not blank, and a match value
-- must equal its trimmed self (a rule whose key carries invisible
-- whitespace would match nothing and silently stop routing).

CREATE TABLE research_owner_rules (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  project_id uuid NOT NULL REFERENCES projects(id) ON DELETE RESTRICT,
  match_kind text NOT NULL,
  match_value text NOT NULL,
  responsibility text NOT NULL,
  created_by uuid NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT research_owner_rules_match_kind_check
    CHECK (match_kind IN ('object_type', 'schema', 'domain')),
  CONSTRAINT research_owner_rules_match_value_check
    CHECK (char_length(match_value) BETWEEN 1 AND 200 AND match_value = btrim(match_value)),
  CONSTRAINT research_owner_rules_responsibility_check
    CHECK (char_length(responsibility) BETWEEN 1 AND 200 AND responsibility = btrim(responsibility)),
  -- One rule row per (project, kind, value, label): the same mapping
  -- written twice is the same requirement twice, which would make the
  -- required-review projection count it twice. A different LABEL for the
  -- same match is a different row on purpose — that is how one change
  -- acquires two responsible reviewers.
  UNIQUE (project_id, match_kind, match_value, responsibility)
);

CREATE INDEX research_owner_rules_project_idx ON research_owner_rules (project_id);

CREATE TABLE responsibility_assignments (
  project_id uuid NOT NULL REFERENCES projects(id) ON DELETE RESTRICT,
  user_id uuid NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
  responsibility text NOT NULL,
  created_by uuid NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT responsibility_assignments_responsibility_check
    CHECK (char_length(responsibility) BETWEEN 1 AND 200 AND responsibility = btrim(responsibility)),
  PRIMARY KEY (project_id, user_id, responsibility)
);

-- The routing resolver's read: "which labels does this user hold here?"
-- (the reviewer-responsibility hook) and "who holds this label?"
-- (the assignment list a project owner reads).
CREATE INDEX responsibility_assignments_project_idx
  ON responsibility_assignments (project_id, responsibility);


-- ===== 00086_external_fork.sql =====

-- External fork lineage and the cross-project pull request (T0804).
--
-- docs/04 §2 states the rule this migration records structurally: "Public
-- Project 的非成员用户不是 Contributor role，但可 Fork 并从自己的空间发起外部
-- PR" — a non-member forks a public project into their OWN space and
-- proposes from there. specs/policies/permissions-matrix.csv writes the same
-- rule as three cells for authenticated_nonmember (create_branch =
-- external_fork_only, write_scientific_state = own_fork_only, open_pr =
-- allow_from_fork); this migration creates the two facts those conditions
-- are resolved against, so the application layer resolves a condition rather
-- than guessing one.
--
--   1. project_forks: the lineage record. One row per fork project. The
--      relation name is the canonical vocabulary's — 'forked_from', the
--      lineage/network type of internal/rsg/relationcatalog (docs/44) and a
--      member of asset_lineage's CHECK (00010); the CHECK here pins it so a
--      second, invented relation name cannot appear in the column, and the
--      column exists at all so the lineage's vocabulary is a stored fact
--      rather than an implication of the table's name.
--
--      A fork is a research-space relationship between two PROJECTS: the
--      fork project (child) and the project it was forked from (parent).
--      docs/31 Gate C requires "Asset PID/version/lineage/…/fork 工作"; the
--      project-level half of that lineage is what this table carries. The
--      asset-level half stays asset_lineage's (00010) — the two are
--      different subjects and this table does not touch that one.
--
--      The row is append-only except for ONE cell: forked_sha, the parent
--      commit the import landed in the fork's repository, is written once,
--      by the import, from NULL to a value. That one-shot update is the
--      compare-and-swap the import's idempotency is built on (the same
--      shape internal/persistence/main_freeze_store.go uses: an atomic
--      UPDATE, zero rows meaning "already done", then one read to explain
--      the outcome). Everything else — which projects, which branches, who
--      forked — is identity and never moves; the guard below enforces it
--      for ANY update path, application code and psql alike.
--
--      UNIQUE (parent_project_id, forked_by) is what makes a repeated fork
--      request idempotent at the database level: the second request's
--      INSERT hits the constraint, the service reads the existing row back
--      and returns it, and no second lineage row, audit row or event is
--      written. Two concurrent requests can never both win.
--
--   2. pull_request_fork_gate: the database half of "an external PR comes
--      from a fork". pull_requests has always carried source_branch_id and
--      target_branch_id with no constraint tying them to the PR's project —
--      the same-project rule lived only in the store — so an external PR is
--      representable. This gate makes the representation HONEST: a PR whose
--      source branch belongs to another project is refused unless that
--      project is a fork of the PR's project forked by the PR's creator.
--      It is a canonical-store-level constraint in the same discipline as
--      00042's semantic gates: it holds for any INSERT path, and it is what
--      keeps "allow_from_fork" from degrading into "allow from anywhere".
--
--      It sits BEFORE INSERT on pull_requests, beside 00042's
--      pull_request_semantic_gate — which checks the SOURCE branch's
--      semantic completeness. The two gates are complementary and both are
--      needed for the fork path: this one decides whether the source branch
--      may propose to this project at all, that one decides whether the
--      source branch's recorded content is understood well enough to open a
--      formal PR.
--
-- No existing constraint is changed or dropped.

CREATE TABLE project_forks (
  -- The fork project: the project created in the forker's own space. One
  -- fork project has one parent (PRIMARY KEY), so a fork can never claim
  -- two origins.
  fork_project_id uuid PRIMARY KEY REFERENCES projects(id) ON DELETE RESTRICT,
  -- The project the fork was taken from.
  parent_project_id uuid NOT NULL REFERENCES projects(id) ON DELETE RESTRICT,
  -- The actor who forked. Resolution of the matrix's fork conditions is
  -- about THIS actor's own fork (docs/04 §2: "从自己的空间"), so the row
  -- names them rather than inferring ownership from a membership role that
  -- can change under the row.
  forked_by uuid NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
  -- The canonical lineage relation name (internal/rsg/relationcatalog,
  -- docs/44). A fork is a 'forked_from' edge and nothing else in V1.
  relation_type text NOT NULL DEFAULT 'forked_from'
    CHECK (relation_type = 'forked_from'),
  -- The parent branch the content was imported from, and the fork branch
  -- that received it. Both are the branches the import binds together; the
  -- lineage is not a bare project-to-project edge, it names the research
  -- paths the content travelled along.
  source_branch_id uuid NOT NULL REFERENCES branches(id) ON DELETE RESTRICT,
  fork_branch_id uuid NOT NULL REFERENCES branches(id) ON DELETE RESTRICT,
  -- The parent commit the import landed in the fork's repository. NULL
  -- until the import has run; the import's compare-and-swap writes it
  -- exactly once (see the guard below). It is a recorded observation of the
  -- provider-side fact, which is why it is nullable and not derived.
  forked_sha text,
  created_at timestamptz NOT NULL DEFAULT now(),
  -- A project cannot be a fork of itself: the row would be a cycle of one.
  CHECK (fork_project_id <> parent_project_id),
  -- The two branches are different research paths in different projects.
  CHECK (source_branch_id <> fork_branch_id),
  -- The idempotency key: one fork of a parent per actor. A repeated fork
  -- request collides here instead of creating a second project, lineage
  -- row, audit row or event; two concurrent requests cannot both win. The
  -- store's claim infers this index by its columns
  -- (ON CONFLICT (parent_project_id, forked_by) DO NOTHING) — the name is
  -- pinned so a later migration that moved the key could not leave that
  -- clause silently inferring a different index.
  CONSTRAINT project_forks_parent_actor_key UNIQUE (parent_project_id, forked_by)
);

COMMENT ON TABLE project_forks IS
  'External fork lineage (T0804): the fork project created in a non-member''s own space, the parent project it was forked from, the actor who forked, and the branch pair the content was imported along. relation_type is the canonical vocabulary''s ''forked_from'' (docs/44). Append-only except forked_sha, which the import writes once under a compare-and-swap.';

COMMENT ON COLUMN project_forks.forked_sha IS
  'The parent commit the fork import landed in the fork project''s GitProvider repository. NULL until the import has run; written once (NULL -> value) by the import''s compare-and-swap, never updated again.';

-- The parent side of the lineage read (a parent's forks, newest first).
CREATE INDEX project_forks_parent_idx
  ON project_forks (parent_project_id, created_at DESC, fork_project_id);

-- +goose StatementBegin
CREATE FUNCTION project_fork_guard() RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'project_forks is append-only: DELETE is forbidden (a fork is lineage; nothing disappears, state only evolves)'
      USING ERRCODE = 'P0001';
  END IF;

  -- Identity is immutable: which projects, which branches, who forked, the
  -- relation name and when the fork happened never move after the insert.
  IF NEW.fork_project_id IS DISTINCT FROM OLD.fork_project_id
     OR NEW.parent_project_id IS DISTINCT FROM OLD.parent_project_id
     OR NEW.forked_by IS DISTINCT FROM OLD.forked_by
     OR NEW.relation_type IS DISTINCT FROM OLD.relation_type
     OR NEW.source_branch_id IS DISTINCT FROM OLD.source_branch_id
     OR NEW.fork_branch_id IS DISTINCT FROM OLD.fork_branch_id
     OR NEW.created_at IS DISTINCT FROM OLD.created_at THEN
    RAISE EXCEPTION 'project_forks identity is immutable: only forked_sha may be set, once, from NULL'
      USING ERRCODE = 'P0001';
  END IF;

  -- The one-shot compare-and-swap cell. A second write to it is refused
  -- whatever it would say — the import that lost the race reads the winner's
  -- value instead of overwriting it.
  IF OLD.forked_sha IS NOT NULL AND NEW.forked_sha IS DISTINCT FROM OLD.forked_sha THEN
    RAISE EXCEPTION 'project_forks.forked_sha is write-once: it is already % and cannot move to %',
      OLD.forked_sha, NEW.forked_sha
      USING ERRCODE = 'P0001';
  END IF;

  RETURN NEW;
END;
$$;
-- +goose StatementEnd

CREATE TRIGGER project_forks_guard
  BEFORE UPDATE OR DELETE ON project_forks
  FOR EACH ROW EXECUTE FUNCTION project_fork_guard();

-- Row-level triggers do not fire on TRUNCATE (00015): the immutability
-- above could still be bypassed wholesale with `TRUNCATE ... CASCADE`. The
-- statement-level half reuses the shared append_only_guard() function.
CREATE TRIGGER project_forks_no_truncate
  BEFORE TRUNCATE ON project_forks FOR EACH STATEMENT
  EXECUTE FUNCTION append_only_guard();

-- pull_request_fork_gate: an external pull request comes from a fork of the
-- project it proposes to, forked by the person opening it.
--
-- The same-project case is the ordinary one and passes untouched. For a
-- source branch in another project the gate demands a project_forks row
-- binding exactly (fork project = the source branch's project, parent
-- project = the PR's project, forked_by = the PR's creator) — so the
-- matrix's allow_from_fork is backed by a stored fact, and a PR can never
-- be opened across two unrelated projects, from a third party's fork, or
-- with the fork's other members' branches as its source.
--
-- A row that names a branch the gate cannot resolve (impossible through the
-- FK, kept as a fail-open only for the same-project case which is decided
-- before the lookup) is left to the application layer; the gate only ever
-- REFUSES a cross-project source it cannot justify.
-- +goose StatementBegin
CREATE FUNCTION pull_request_fork_gate() RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
  source_project uuid;
BEGIN
  SELECT b.project_id INTO source_project
    FROM branches b
   WHERE b.id = NEW.source_branch_id;

  -- Same project: the ordinary internal pull request. Nothing to say.
  IF source_project IS NULL OR source_project = NEW.project_id THEN
    RETURN NEW;
  END IF;

  IF NOT EXISTS (
    SELECT 1
      FROM project_forks f
     WHERE f.fork_project_id = source_project
       AND f.parent_project_id = NEW.project_id
       AND f.forked_by = NEW.created_by
  ) THEN
    RAISE EXCEPTION 'pull request on project % cannot take its source branch from project %: a cross-project pull request must come from the opener''s own fork of this project (docs/04 §2, open_pr = allow_from_fork)',
      NEW.project_id, source_project
      USING ERRCODE = 'P0001';
  END IF;

  RETURN NEW;
END;
$$;
-- +goose StatementEnd

CREATE TRIGGER pull_request_fork_gate_trigger
  BEFORE INSERT ON pull_requests
  FOR EACH ROW EXECUTE FUNCTION pull_request_fork_gate();


-- ===== 00087_contribution_ledger_projection.sql =====

-- Contribution Ledger projection (T0807, docs/13).
--
-- contribution_events has existed since 00011 with no writer anywhere in
-- the repository: the table, its append-only guard (00014/00015) and
-- docs/13 §1's list of what a contribution event carries were all in place,
-- and nothing had ever produced a row. T0807 is the projection that turns
-- the domain event log (research_events) into ledger rows, and this
-- migration adds the three things that projection needs and the two tables
-- cannot express.
--
-- 1. The source event: contribution_events.research_event_id.
--
-- A ledger row is the projection of exactly ONE domain event, and the
-- column pins which (docs/13 §2/§3: a correction is a NEW event and the
-- original is never edited; CLAUDE.md §9 invariant 14). The partial unique
-- index below is what makes the projection IDEMPOTENT: a re-run — the
-- projection is a rebuildable read of the append-only log, so re-running it
-- is normal, not exceptional — inserts ON CONFLICT DO NOTHING and adds
-- nothing, exactly as the outbox publish step does one table over
-- (00046: research_events.outbox_event_id + research_events_outbox_event_uniq,
-- the shape this one is copied from).
--
-- The index is PARTIAL for 00046's own reason: NULL is never a conflict, so
-- a row written by a path that is not the projection (a direct ledger write
-- with no source event) stays legal, and every projection-written row is
-- non-NULL. The projection never writes a NULL source.
--
-- The FK is ON DELETE RESTRICT like every other reference to history in
-- this schema, and it points at research_events rather than at outbox_events
-- because research_events is the append-only log the projection reads:
-- release.published, research_asset.version_published and
-- knowledge.version_published are written into it DIRECTLY (the persistence
-- stores' RecordResearchEvent), with no outbox row at all.
--
-- 2. via — the channel the contribution arrived through (docs/13 §1).
--
-- docs/13 §1 names seven things every contribution event carries; six of
-- them are columns of 00011 already (actor person id, affiliation at time,
-- project/object refs, role tags, timestamp, accepted/released context) and
-- the seventh — "via agent/client" — was never a column. This adds it.
--
-- The vocabulary is the CHANNEL one, not the authentication one:
-- state_commits.via (00004: web, api, mcp, claude_code, git_compat, system;
-- internal/domain/state.go, StateVia) is "which channel did this write come
-- through", while audit_log.via (00012: session, password, oidc, internal;
-- internal/domain/audit.go) is "how was the actor authenticated". docs/13 §1
-- says agent/client — that is the channel.
--
-- No CHECK, deliberately: the vocabulary lives in Go (the domain constant
-- list), and a CHECK here would be a second definition of it that drifts.
-- This is the convention four existing migrations state verbatim for their
-- own vocabularies (00064, 00066, 00067, 00045), and role_codes follows it
-- too — docs/04 §4's thirteen contribution roles are a Go-side vocabulary
-- with no database CHECK either.
--
-- NULL is legal and means "the source event carried no channel" — never a
-- guessed default. A guessed 'api' would read exactly like a recorded fact.
--
-- 3. The envelope chain: outbox_events.via and research_events.via.
--
-- A ledger row's via may not be re-derived from the event payload: the
-- envelope rule 00046 states for the publish step is verbatim "the publisher
-- must copy them from the outbox row, never re-derive them from the
-- payload", and the reason it gives (a private event must not be publishable
-- as a public one) is about envelope columns in general — the payload is
-- producer-written data about the event, the envelope column is the record
-- the write path made. A ledger column that read payload->>'via' would be
-- trusting the same data the rule refuses to trust one table earlier.
--
-- So the channel travels as a column at every hop: the outbox row carries
-- it from the write path, the publisher copies it into the research event,
-- and the projection copies it into the ledger row that names that event.
-- Both columns land here so the chain has somewhere to live.
--
-- HONEST STATE OF THE CHAIN, since a column nothing writes is worth naming:
-- the two write paths that would set outbox_events.via belong to
-- internal/events (the outbox recorder's INSERT and the publisher's
-- envelope copy), which is outside T0807's write scope. Until that
-- one-field change lands, research_events.via is NULL on tonight's writes
-- and every projected via is NULL — which is the truthful answer ("the
-- source event carries no channel"), not a fabricated one. The projection
-- reads the column and copies it verbatim; it never invents a value, and
-- the moment the recorder sets it the ledger fills in with no change here.
--
-- Nothing else changes. contribution_events keeps its shape otherwise (00011
-- designed it; T0807 does not), its append-only guard already covers every
-- new write path (00014/00015: the guard is on the table, not on a
-- statement, so INSERT-only is enforced for this projection exactly as for
-- anything else), and no aggregate, counter, weight or rank column is added
-- — docs/13 §4 forbids a single score, docs/13 §6 forbids raw counts as
-- quality proxies, and CLAUDE.md §9 invariant 13 forbids a Truth Score. The
-- ledger records facts; a Reputation Profile derives from them elsewhere.

ALTER TABLE contribution_events
  ADD COLUMN research_event_id uuid REFERENCES research_events(id) ON DELETE RESTRICT,
  ADD COLUMN via text;

COMMENT ON COLUMN contribution_events.research_event_id IS
  'The research_events row this ledger row projects (T0807). The partial unique index contribution_events_research_event_uniq makes the projection idempotent: a re-run of the projection conflicts on this key and inserts nothing. NULL for a ledger row written directly, with no source event — the projection never writes one.';

COMMENT ON COLUMN contribution_events.via IS
  'The channel the contribution arrived through (docs/13 §1 "via agent/client"): the state_commits.via vocabulary (00004: web, api, mcp, claude_code, git_compat, system), NOT the audit_log.via authentication vocabulary (00012). Defined in Go (internal/domain/state.go StateVia), no CHECK here by the 00064/00066/00067/00045 convention. Copied verbatim from the source research_event''s via column, which the publisher copies from the outbox row (00046: envelope columns are copied, never re-derived from the payload). NULL means the source event carries no channel — never a guessed default.';

-- The projection dedupe: one ledger row per source event, ever.
CREATE UNIQUE INDEX contribution_events_research_event_uniq
  ON contribution_events (research_event_id)
  WHERE research_event_id IS NOT NULL;

-- Two columns 00011 created without a producer now have one, and their
-- content is pinned here rather than left to whoever reads them next:
-- event_type is the domain event the row projects (the vocabulary of
-- specs/events/event-types.yaml, the machine-readable event list), and
-- object_refs is an array of canonical "kind:value" strings naming the
-- subject entities of that event — the same text form research_asset_versions
-- .origin_refs uses (00064), with the kinds this subsystem defines.
COMMENT ON COLUMN contribution_events.event_type IS
  'The domain event this ledger row projects: a name from specs/events/event-types.yaml (the machine-readable event vocabulary), e.g. scientific_object.version_created, pull_request.merged, contribution.accepted. docs/13 §1 lists the ledger''s event categories in prose and ends it with 等; the spec''s list is the closed, checkable one, and the row also pins its exact source in research_event_id. Written by the T0807 projection.';

COMMENT ON COLUMN contribution_events.object_refs IS
  'The subject entities of the projected event, as an array of canonical "kind:value" strings (the text form research_asset_versions.origin_refs uses; the kinds are internal/contribution''s LedgerRefKind set). Read from the event''s own payload — an id the payload does not carry contributes no ref — and never from a later read of current state: the ledger records what the event said. Written by the T0807 projection.';

ALTER TABLE outbox_events
  ADD COLUMN via text;

COMMENT ON COLUMN outbox_events.via IS
  'The channel the write that produced this event arrived through, in the state_commits.via vocabulary (00004) — the envelope column the publisher copies verbatim into research_events.via (00046: envelope columns are copied from the outbox row, never re-derived from the payload). NULL means the writing path did not record a channel; the outbox recorder (internal/events) is the path that sets it.';

ALTER TABLE research_events
  ADD COLUMN via text;

COMMENT ON COLUMN research_events.via IS
  'The channel the write that produced this event arrived through, in the state_commits.via vocabulary (00004), copied verbatim from the outbox row it was published from (00046). Read by the Contribution Ledger projection (T0807) into contribution_events.via — the ledger never re-derives a channel from an event payload. NULL means no channel was carried.';


-- ===== 00089_pull_request_creation_key.sql =====

-- Pull-request creation idempotency (T0410).
--
-- specs/api/openapi.yaml declares the Open-pull-request route with
-- components.parameters.IdempotencyKey — `required: true`, `minLength: 8`.
-- A required header the server demands and then discards is worse than no
-- header at all: the client believes a retry is safe, the server creates a
-- second proposal, and the contract's own promise is the thing that broke.
-- The four writes that already carry this parameter solved it the same way
-- (merge 00070, release 00053, milestone 00063, asset publish 00072,
-- knowledge publish 00083): a UNIQUE key on the project, with the second
-- request returning the row the first one produced.
--
-- Those five are ledgers, because the entity they create is not the row the
-- request is addressed to (a merge record, a release, a publication). A pull
-- request is different: the created entity IS the pull_requests row, so the
-- key's home is that row and no second table is needed. One key names one
-- proposal per project, which is exactly the uniqueness the contract asks
-- for and exactly what UNIQUE(project_id, number) already is for the number.
--
-- The index is PARTIAL on `creation_key <> ''`:
--
--   * '' is the absent key — every row written before this migration and
--     every creation that sends no key at all (the domain service's own
--     callers, the store's tests, the fork service's import). Those must not
--     collide with each other, and a plain UNIQUE would let at most one of
--     them exist per project.
--   * column default '' rather than NULL keeps the wire/adapter types plain
--     (a go string, not a nullable one) without making "no key" a value a
--     caller could store by accident.
--
-- Forward-only and additive: no existing row changes, no column is dropped,
-- and a database that never sends a key behaves exactly as before.
ALTER TABLE pull_requests ADD COLUMN creation_key text NOT NULL DEFAULT '';

CREATE UNIQUE INDEX pull_requests_creation_key_idx
  ON pull_requests (project_id, creation_key)
  WHERE creation_key <> '';

COMMENT ON COLUMN pull_requests.creation_key IS
  'The Idempotency-Key the creation request carried (specs/api/openapi.yaml components.parameters.IdempotencyKey); empty when the request sent none. UNIQUE per project among non-empty keys: a repeated request returns the proposal the first one opened instead of opening a second.';


-- ===== 00090_search_projection_consumer.sql =====

-- T0901. Two pieces of the search projection land here: the consumer's
-- cursor, and the target shape a knowledge subscription is addressed by.
--
--   1. search_projected_events: the search projection's exactly-once
--      cursor, one row per outbox row the projector has consumed. It is
--      the third consumer to keep a cursor of its own — the webhook
--      fan-out keeps one as a column on outbox_events
--      (00059's webhook_fanned_out_at), the subscription fan-out keeps one
--      as this table's twin (00078's subscription_fanned_events) — and it
--      is a table rather than a column on outbox_events for the same
--      reason 00078 chose a table: outbox_events is modeled by checked-in
--      sqlc queries (SELECT * / INSERT ... RETURNING *), so a new column
--      there moves generated code. The semantics are the other two's,
--      exactly: the cursor row is written in the same transaction as the
--      projected document, so a crash between the two re-runs an idempotent
--      upsert instead of losing an event, and no consumer's progress is
--      visible to another's.
--
--   2. subscriptions_target_id_shape: a knowledge target becomes
--      PID-addressed, exactly as an asset target already is. 00078's
--      CHECK gave the asset pid its own branch because the asset page
--      addresses an asset by its pid and the pid never changes; the
--      knowledge publication has the same identity shape (00083's
--      knowledge_publications_pid_format carries the identical regexp),
--      but its row uuid never leaves the process — the public read
--      resolves a publication BY PID (cmd/api/knowledgehttp: "Read
--      resolves one published knowledge object by its pid") — so the uuid
--      a knowledge target used to demand was an identifier no user could
--      ever hold, and a knowledge subscription could not be created at all.
--      events.ValidateTargetID carries the same rule on the application
--      path; this CHECK is the second line, for a session that writes SQL
--      directly.

CREATE TABLE search_projected_events (
  outbox_event_id uuid PRIMARY KEY REFERENCES outbox_events(id) ON DELETE RESTRICT,
  projected_at timestamptz NOT NULL DEFAULT now()
);

COMMENT ON TABLE search_projected_events IS
  'The search projection''s exactly-once cursor (T0901): one row per outbox row the projector has consumed, written in the same transaction as the search_documents upsert, so a crash between the two re-runs an idempotent upsert instead of losing an event. It mirrors subscription_fanned_events (00078) and webhook_fanned_out_at (00059): every consumer of the outbox keeps its own progress.';

-- The knowledge branch of the target-id shape moves from the uuid form to
-- the 26-character Crockford base32 PID — the same regexp the asset branch
-- has carried since 00078, and the one knowledge_publications_pid_format
-- (00083) enforces on the pid column itself.
--
-- The data step is not optional: a knowledge target_id written under the
-- old rule is the publication's ROW UUID, and that uuid fails the new
-- CHECK. Every such row names a real publication — the subscribe path
-- resolves the target's audience through TargetAudience before it writes,
-- and a publication row is referenced by knowledge_publication_creations
-- (ON DELETE RESTRICT, 00083) so it cannot be deleted — which is why the
-- conversion below is total: it rewrites every existing row's target_id to
-- the pid of the publication the old uuid named, and the constraint that
-- follows accepts every row. A row whose uuid named no publication cannot
-- exist (the subscribe would have been refused with AudienceNone), so the
-- ALTER ADD CONSTRAINT below is not a step that can fail on live data.
ALTER TABLE subscriptions
  DROP CONSTRAINT subscriptions_target_id_shape;

UPDATE subscriptions s
SET target_id = kp.pid
FROM knowledge_publications kp
WHERE s.target_type = 'knowledge' AND s.target_id = kp.id::text;

ALTER TABLE subscriptions
  ADD CONSTRAINT subscriptions_target_id_shape
    CHECK (CASE target_type
             WHEN 'asset' THEN target_id ~ '^[0-9a-hjkmnp-tv-z]{26}$'
             WHEN 'knowledge' THEN target_id ~ '^[0-9a-hjkmnp-tv-z]{26}$'
             ELSE target_id ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
           END);

COMMENT ON TABLE subscriptions IS
  'One user following one target (T1002, docs/18 §3). target_type is the canonical target vocabulary; target_id is the target''s stable identity — a uuid for project/user/organization, the asset pid for asset (the same identifier /assets/{pid} is built from), the publication pid for knowledge (the same identifier /api/v1/knowledge/{pid} is built from, 00083). deleted_at is the unsubscribe marker: a deleted subscription matches no fan-out, and its in-flight deliveries are cancelled in the same transaction.';


-- ===== 00091_external_evidence_network.sql =====

-- External evidence on the network (task T0806, docs/10 §7):
--
--   "Published Knowledge Object 页面区分 Origin Evidence、Reviewed
--    External Evidence、Unreviewed External Evidence。原发布者不能删除
--    外部反证；只能对其本项目 assessment 负责。"
--
-- The three classes are a READ-SIDE classification and they are NOT stored
-- here. They are derived from two axes that already exist:
--
--   1. origin vs external — whether the project that owns the assertion is
--      the project that owns the published version it targets. Both ends
--      are readable (evidence_assertions.project_id, and the publication's
--      object_version_id -> scientific_object_versions.object_id ->
--      scientific_objects.project_id chain, 00005/00010), so the axis is
--      computed at read time by internal/domain.ClassifyEvidenceNetwork.
--      A stored three-valued column would be a third thing to keep in sync
--      and would drift from review_state the moment either moved.
--   2. reviewed vs unreviewed — evidence_assertions.review_state, which
--      00007 has carried since the table was created.
--
-- What this migration adds is the rest of the evidence-assertion schema
-- docs/10 §3 names ("... external/internal、visibility、created transition")
-- and the one thing the table is missing at the storage layer: the fact
-- that an assertion is never deleted.
--
-- 1. evidence_origin (docs/10 §3's "external/internal").
--
-- Values: 'internal' means the asserting project IS the project that owns
-- the published version the assertion targets — the endpoint's Origin
-- Evidence side. 'external' means another project asserted it (Reviewed /
-- Unreviewed External Evidence, decided afterwards by review_state).
--
-- The column is the assertion's own PROVENANCE RECORD, written once by the
-- write path from the same comparison the read recomputes; it is never
-- client input, and the read side deliberately does not consult it (a
-- declaration that could be edited must not be able to move a row between
-- buckets). DEFAULT 'internal' is the neutral member: a row written by
-- anything that does not go through the application records the origin
-- side, and the read still decides on the two facts it reads itself.
--
-- 2. visibility (docs/10 §3).
--
-- Values are the platform's visibility vocabulary ('public','private',
-- exactly as projects/branches declare it). It is the assertion's own
-- visibility axis: whether the assertion may be rendered by the PUBLIC
-- network read (GET /knowledge/{knowledgeId}, which is `security: []`).
-- DEFAULT 'private' is the fail-closed direction — an assertion nothing
-- explicitly made public is not rendered anywhere (docs/12 §5: missing
-- information is never a reason to widen).
--
-- The write path derives it from the axes that already exist rather than
-- from the request: public only when the asserting project AND the branch
-- the assertion was committed to are both public. There is no
-- client-supplied visibility in the request shape (specs/mcp/tools.json,
-- evidence.create_assertion), so there is nothing to trust and nothing to
-- override.

ALTER TABLE evidence_assertions
  ADD COLUMN evidence_origin text NOT NULL DEFAULT 'internal'
    CONSTRAINT evidence_assertions_evidence_origin_check
    CHECK (evidence_origin IN ('internal', 'external')),
  ADD COLUMN visibility text NOT NULL DEFAULT 'private'
    CONSTRAINT evidence_assertions_visibility_check
    CHECK (visibility IN ('public', 'private'));

-- 3. DELETE is refused; UPDATE is not.
--
-- 00058 deliberately did NOT take the append-only pair on this table, and
-- its header says why: reviewing an assertion is a legitimate in-place
-- state change (unreviewed → reviewed → rejected), and the 00014 pair
-- guards the version LOGS (scientific_object_versions and friends), not
-- version-less member rows. That reasoning still holds, and this migration
-- does not undo it: the 00014 row guard (BEFORE UPDATE OR DELETE) is
-- deliberately NOT taken, so the review transition stays legal and the
-- UPDATE half of the pair is never claimed.
--
-- What is taken is the DELETE half and the 00015 TRUNCATE half, because
-- the requirement being met is not about reviews: 原发布者不能删除外部反证.
-- A raw `DELETE FROM evidence_assertions` was legal before this
-- migration — there is no guard on the table at all — so any holder of a
-- connection could erase another project's counter-evidence without
-- leaving a trace, which is exactly the act the domain forbids. The guard
-- is the 00014/00015 discipline reused verbatim (append_only_guard(), the
-- same function and the same SQLSTATE P0001 the other guarded tables
-- raise, so an operator reads one message shape everywhere).
--
-- The guard is actor-agnostic because the database knows no actor: it
-- refuses the DELETE of an assertion row, whoever asks. It is therefore
-- strictly stronger than "the origin maintainer may not delete external
-- evidence" — nobody deletes an assertion, which is CLAUDE.md §9.8
-- ("Nothing disappears; state only evolves") read at the storage layer,
-- and which no write path in this build contradicts: the product has no
-- delete route and no Delete query (the application half of the same
-- requirement), and a rejected assertion leaves the picture by its
-- review_state, in place, the way 00058 already describes.
--
-- A guard that instead tried to compute "is this row external?" from the
-- project comparison would be bypassable by exactly the actor it is aimed
-- at: raw SQL could UPDATE evidence_assertions.project_id to the deleter's
-- own project first (the column is an ordinary FK column) and then delete.
-- Refusing the DELETE outright has no such precursor.

CREATE TRIGGER evidence_assertions_delete_guard
  BEFORE DELETE ON evidence_assertions
  FOR EACH ROW EXECUTE FUNCTION append_only_guard();

CREATE TRIGGER evidence_assertions_no_truncate
  BEFORE TRUNCATE ON evidence_assertions FOR EACH STATEMENT
  EXECUTE FUNCTION append_only_guard();


-- ===== 00092_search_embedding_metadata.sql =====

-- T0902. search_documents gains the PROVENANCE of its embedding, and
-- nothing else about the table changes.
--
-- 00013 created search_documents.embedding vector(1536) and left it NULL
-- forever: no query, no worker and no migration in this tree ever read or
-- wrote it. Filling it needs a second fact on the same row, because an
-- embedding is only valid for the model that produced it — a vector is a
-- pair (model identity, vector), not a number list. Without the identity a
-- row cannot answer "is this vector current?", which is the question every
-- recompute pass asks and the question "recompute after a model change"
-- turns into a job.
--
-- # Why columns on this table rather than a table of its own
--
-- search_documents is a PROJECTION, not history: 00014's append-only guard
-- deliberately excludes it, 00015 leaves it out of the truncate guard, and
-- tests/integration/append_only_truncate_test.go pins that TRUNCATE
-- search_documents succeeds. A projection's rows may be thrown away and
-- derived again, so adding columns to it raises NO backfill question:
-- existing rows are simply rows whose vector has not been computed yet
-- (NULL, below), and a rebuild re-derives them. A separate row-per-version
-- table would instead introduce exactly the consistency problem this table
-- is valuable for NOT having: every read of a document would have to decide
-- which of its version rows is the one it means, and a rebuild would have to
-- keep the two in step.
--
-- # Why the columns are nullable
--
-- NULL is a real state, not a missing one: it says "no vector has been
-- computed for this row under any model" (every row, until T0902's batch
-- job runs). This is the same stance internal/rights/usage.go takes on an
-- unspecified usage — an omitted fact is the answer "not specified", and
-- inventing a placeholder value for it would be inventing a fact. There is
-- deliberately no DEFAULT: a default provider would claim every unembedded
-- row had been embedded by it.
--
-- # Why not structured jsonb
--
-- search_documents.structured is an open bag of a document's own facets. A
-- field that decides "must this row be recomputed?" is a predicate the
-- recompute pass compares against the configured model on every scan, and
-- inside an open bag its absence is indistinguishable from any other key's
-- absence while its type is whatever the last writer put there. A tracked
-- fact belongs in a typed column (docs/52: an external provider's identity
-- never becomes a domain primary identity — here it is a recorded attribute
-- of a derived row, addressed by the entity_ref the row is already keyed
-- by).
--
-- # What the three columns are
--
--   embedding_provider  which implementation computed the vector
--   embedding_model     which model of it (the provider's own name)
--   embedding_version   which revision of that model
--
-- All three are text and none is parsed by POST: the provider owns what it
-- calls its revision, and POST's job is to store it verbatim so that a
-- change is detectable. The complete triple, not just the version, is what
-- the recompute pass compares — a different implementation can ship the
-- same version label.
--
-- # No index, deliberately
--
-- pgvector supports ivfflat/hnsw indexes; ADR-005 sets no threshold and
-- docs/68 pins only "PostgreSQL + pgvector". An index is a measurable
-- performance decision, not a semantic one, and at V1 scale the exact scan
-- it would replace is exact (an approximate index can be less accurate than
-- the scan, never more). The recompute pass reads search_documents
-- unordered by embedding_provider anyway, and the retrieval query does not
-- exist yet (T0904/T0905). Left out as a decision, not by omission.

ALTER TABLE search_documents
  ADD COLUMN embedding_provider text,
  ADD COLUMN embedding_model    text,
  ADD COLUMN embedding_version  text;

COMMENT ON COLUMN search_documents.embedding IS
  'The document''s embedding, 1536 wide (00013). NULL means no vector has been computed for this row.';
COMMENT ON COLUMN search_documents.embedding_provider IS
  'Who computed embedding. NULL means no vector has been computed for this row — never "unknown provider".';
COMMENT ON COLUMN search_documents.embedding_model IS
  'The provider''s own name for the model that produced embedding.';
COMMENT ON COLUMN search_documents.embedding_version IS
  'The provider''s own revision of embedding_model. Stored verbatim: POST does not renumber an external identity.';

-- The vector and its provenance travel together, and the database says so.
-- A row with a vector and no provenance would be re-embedded by every
-- recompute pass forever (its metadata never matches any model), and a row
-- with provenance and no vector would be a row that claims an embedding it
-- does not have. Both are unrepresentable here rather than merely
-- unwritten: the batch job has one write path, and this is the second line
-- for a session that writes SQL directly (the same reason 00078's target
-- CHECK repeats what the application already validates).
ALTER TABLE search_documents
  ADD CONSTRAINT search_documents_embedding_complete CHECK (
    (embedding IS NULL) = (embedding_provider IS NULL)
    AND (embedding IS NULL) = (embedding_model IS NULL)
    AND (embedding IS NULL) = (embedding_version IS NULL)
  );


-- ===== 00100_scientific_object_abort_record.sql =====

-- The abort record on the append-only object version log (T0602).
--
-- docs/46 (Abort、Retention 与"不删除"原则) fixes what an abort must record,
-- verbatim: "Abort 必须记录 actor、time、reason code、human explanation、
-- replacement/superseding ref(optional)、review/approval if main object."
-- and how a main-line abort travels: "main 中对象 Abort 必须 branch → PR →
-- merge". docs/43's object lifecycle is "active → aborted → reopened →
-- active；可 superseded…但不物理删除", and the migration that installed the
-- append-only triggers (00014) names abort as the canonical example of a
-- correction that APPENDS a row instead of mutating one.
--
-- # Where the record lives, and why not in `payload`
--
-- The six columns below are added to scientific_object_versions — the table
-- that already carries the lifecycle_state the abort moves. They are NOT
-- folded into `payload`, and that is the load-bearing decision of this
-- migration: `payload` is the schema-governed SCIENTIFIC content of the
-- version, and its sha256 is the version's integrity_hash (docs/23 §3,
-- docs/21 §10 — "accepted state is content-addressed"). An abort is a
-- GOVERNANCE act about a version, not a change to what the version says:
-- aborted versions store the aborted version's payload byte-for-byte, so the
-- aborted row's content hash equals the content hash it had, and the
-- lifecycle move is the only thing the row changes. Folding the record into
-- the payload would make every abort a content change that invalidates the
-- hash it was accepted under, and would force every per-type schema in
-- packages/schemas/ to tolerate governance keys inside scientific content.
--
-- # Nullable, and grouped by one constraint
--
-- Every column is NULL for every version that is not an abort (and for every
-- row written before this migration — there are none on main, but the log is
-- append-only and the column set must not pretend otherwise). The
-- abort_record_shape CHECK keeps the record all-or-nothing: a row either
-- carries the whole record (reason code + explanation + deciding actor +
-- deciding time; the replacement ref and the request key stay optional) or
-- none of it. A half-written record is refused by the database, not by
-- convention.
--
-- aborted_by / aborted_at are deliberately NOT the row's created_by /
-- created_at. For the version the abort command writes, the two pairs agree.
-- For the version a Research PR MERGE writes onto main, they do not: the
-- merge materializes the source version's content into a new row whose
-- created_by is the MERGING actor (internal/application/merge materialize —
-- the merge is the write). docs/46:7's "actor, time" are facts about the
-- abort DECISION, so they get their own columns and survive the merge with
-- their original values.
--
-- # The request key replaces a ledger table
--
-- The contract's Idempotency-Key is honored on the state itself, exactly as
-- migration 00089 did for pull-request creation: the entity the request
-- produces IS a scientific_object_versions row, so the key's home is that
-- row and no second bookkeeping table is needed. The index is PARTIAL and
-- scoped to the object (one key names one abort of one object; NULL is the
-- absent key, and NULLs never collide in a unique index). A repeated request
-- therefore reads the row the first one wrote instead of appending a second
-- — no second audit row, no second scientific_object.aborted event.
--
-- Forward-only and additive: no existing column, constraint or row is
-- touched; a database that never aborts an object behaves exactly as before
-- and every existing query keeps working (the new columns are simply absent
-- from their projections).
ALTER TABLE scientific_object_versions
  ADD COLUMN abort_reason_code text,
  ADD COLUMN abort_explanation text,
  ADD COLUMN abort_replacement_ref text,
  ADD COLUMN aborted_by uuid REFERENCES users(id) ON DELETE RESTRICT,
  ADD COLUMN aborted_at timestamptz,
  ADD COLUMN abort_request_key text;

-- The reason code is an OPEN string in V1 (the T0602 ruling). Both specs
-- that require the field name it and neither enumerates values: docs/46:7
-- says the abort MUST record a reason code, and specs/mcp/tools.json's
-- object.abort_proposal passes `reason_code` in as a CALLER ARGUMENT. So the
-- column stores whatever token the caller used, and this CHECK only fixes
-- the SHAPE — a bounded lowercase token — never a vocabulary. No list of
-- accepted codes exists in this migration, in Go, or anywhere else; adding
-- one later is a normal narrowing, and the cost of not having one is named
-- in the T0602 result: V1 cannot break aborts down by reason.
ALTER TABLE scientific_object_versions
  ADD CONSTRAINT scientific_object_versions_abort_reason_code_shape
  CHECK (abort_reason_code IS NULL OR abort_reason_code ~ '^[a-z0-9_]{1,64}$');

-- The human explanation is the part a machine cannot reconstruct, so it must
-- be present and non-blank whenever a record exists. The upper bound is the
-- same 4 KiB order as the other free-text fields the platform stores; it
-- keeps one row from carrying an unbounded document.
ALTER TABLE scientific_object_versions
  ADD CONSTRAINT scientific_object_versions_abort_explanation_shape
  CHECK (abort_explanation IS NULL
         OR (length(btrim(abort_explanation)) BETWEEN 1 AND 4096));

-- The optional pointers (docs/46:7's "replacement/superseding ref"): absent
-- is NULL, never ''. An empty string would make "no replacement given" and
-- "a replacement given as nothing" indistinguishable on read.
ALTER TABLE scientific_object_versions
  ADD CONSTRAINT scientific_object_versions_abort_replacement_ref_shape
  CHECK (abort_replacement_ref IS NULL
         OR (length(btrim(abort_replacement_ref)) BETWEEN 1 AND 512));

-- The idempotency key follows the contract's own bound
-- (specs/api/openapi.yaml, components.parameters.IdempotencyKey: minLength
-- 8): a stored key is a deliberate token, never a stray empty string.
ALTER TABLE scientific_object_versions
  ADD CONSTRAINT scientific_object_versions_abort_request_key_shape
  CHECK (abort_request_key IS NULL OR length(abort_request_key) >= 8);

-- All-or-nothing, and tied to the state it describes: a row carrying abort
-- metadata is a row whose lifecycle_state IS 'aborted'. The record can
-- therefore never be attached to an active version, and an aborted version
-- written without a record (a payload-only lifecycle move, e.g. a fixture)
-- stays legal — this migration constrains the record's shape, it does not
-- mandate that every aborted row has one.
ALTER TABLE scientific_object_versions
  ADD CONSTRAINT scientific_object_versions_abort_record_shape
  CHECK (
    NOT (abort_reason_code IS NULL) = NOT (abort_explanation IS NULL)
    AND NOT (abort_reason_code IS NULL) = NOT (aborted_by IS NULL)
    AND NOT (abort_reason_code IS NULL) = NOT (aborted_at IS NULL)
    AND (abort_reason_code IS NULL OR lifecycle_state = 'aborted')
  );

CREATE UNIQUE INDEX scientific_object_versions_abort_request_key_idx
  ON scientific_object_versions (object_id, abort_request_key)
  WHERE abort_request_key IS NOT NULL;

COMMENT ON COLUMN scientific_object_versions.abort_reason_code IS
  'The abort''s reason code (docs/46:7). An OPEN caller-supplied token in V1 — no vocabulary is defined by any spec, and this platform does not invent one; the column CHECKs the shape (^[a-z0-9_]{1,64}$) and records the value as given.';
COMMENT ON COLUMN scientific_object_versions.abort_explanation IS
  'The human explanation the abort recorded (docs/46:7) — the part no machine can reconstruct. Non-blank when the record exists.';
COMMENT ON COLUMN scientific_object_versions.abort_replacement_ref IS
  'The optional replacement/superseding ref (docs/46:7). NULL means none was given; it is never stored as an empty string.';
COMMENT ON COLUMN scientific_object_versions.aborted_by IS
  'The actor who decided the abort (docs/46:7 "actor"). Not the row''s created_by: after a Research PR merge materializes the abort onto main, created_by is the merging actor while this stays the aborting one.';
COMMENT ON COLUMN scientific_object_versions.aborted_at IS
  'Server-derived time of the abort decision (docs/46:7 "time"); never caller-supplied. Travels with the record when a merge materializes the abort onto main.';
COMMENT ON COLUMN scientific_object_versions.abort_request_key IS
  'The Idempotency-Key the abort request carried (specs/api/openapi.yaml components.parameters.IdempotencyKey); NULL when none. UNIQUE per object among non-NULL keys, so a repeated request reads the row the first one wrote instead of appending a second (the migration-00089 pattern). Not carried onto main by a merge: it names a request, not history.';


-- ===== 00101_research_profile_indexes.sql =====

-- Research Profile / Organization Profile read paths (task T0808, docs/42).

-- The Research Profile page (docs/42 "Research Profile": "Affiliations、public
-- contribution dimensions、accepted/released/reused/reproduced evidence、
-- assets/projects、confidential verified contribution summaries") and the
-- Organization Profile page (docs/05 §3 /orgs/{org}, "institutional research
-- identity") are the first readers that ask these tables "everything about
-- THIS person / THIS organization". Until now every read of them went the
-- other way round — by project, by asset, by state — so the columns the new
-- reads filter on carry no index at all, and every profile view would be a
-- sequential scan of an append-only table that only ever grows.
--
-- Five indexes, one per path the profile reads take. Nothing else changes:
-- no column, no constraint, no table. The two vocabulary columns that have
-- no CHECK keep having none (role_codes, event_type — the 00064/00066/00067/
-- 00045 convention), and no aggregate, counter, weight or rank column is
-- added anywhere, because docs/13 §4 forbids a single score and CLAUDE.md §9
-- invariant 13 forbids a Truth Score: the profile derives its dimensions from
-- rows, and a column that held a total would be the score this schema is not
-- allowed to have.

-- 1. A person's contributions (docs/13 §1): the ledger rows one actor wrote,
-- newest first. contribution_events has been read by actor exactly never —
-- 00087 gave it one index, the partial unique on research_event_id that makes
-- the projection idempotent — so this is the first index on the read path
-- that answers "what has this person contributed".
--
-- The order (actor_id, occurred_at DESC, id DESC) is the read's own: a
-- profile renders the newest rows first, and id closes the sort so two rows
-- written in the same transaction have a deterministic order.
CREATE INDEX contribution_events_actor_occurred_idx
  ON contribution_events (actor_id, occurred_at DESC, id DESC);

-- 2. An organization's public research activity (docs/05 §3, docs/42): the
-- ledger rows recorded while the actor was affiliated with one organization
-- — organization_id_at_time, which 00011 named for exactly that question
-- ("affiliation at time", docs/13 §1) and the projection resolves at event
-- time (internal/contribution/ledger_store.go).
--
-- This is also the index that makes "离职后个人历史保留" answerable at all: a
-- membership that ends stops resolving NEW events to the organization, and
-- the rows already written keep naming it, so the organization's history is
-- readable without consulting the membership table for anything but dates.
CREATE INDEX contribution_events_org_occurred_idx
  ON contribution_events (organization_id_at_time, occurred_at DESC, id DESC);

-- 3. The assets a person or an organization is credited on (docs/11 §6:
-- "Creator/history 永久保留"; asset_version_parties, 00082). The table's only
-- index is by version (asset_version_parties_version_role), which is the
-- direction the asset page reads it in — "who is credited on this version".
-- The profile asks the reverse, "which versions is this party credited on",
-- and party_id is not a leading column of anything.
--
-- (party_kind, party_id) leads with the kind because a party id is only
-- meaningful with it (00082: "no reader can hold an id without knowing
-- whether it names a person or an organization") — the index says the same
-- thing the column pair does.
CREATE INDEX asset_version_parties_party_idx
  ON asset_version_parties (party_kind, party_id);

-- 4. The reproductions a person asserted (docs/10 §4's relation vocabulary,
-- docs/13 §4's "independent reproductions" dimension): evidence_assertions
-- rows created by one author whose relation is reproduces /
-- fails_to_reproduce. 00041 indexed this table by target and by evidence —
-- the directions the evidence network reads it in — and created_by has no
-- index, so "the assertions this person made" is a scan today.
--
-- relation_type is the second column because the profile's read is always
-- the same pair ("this author, these two relations"), and the two columns
-- together are exactly the predicate.
CREATE INDEX evidence_assertions_author_relation_idx
  ON evidence_assertions (created_by, relation_type);

-- 5. The reuses of a version (docs/13 §4's "assets reused" dimension): the
-- asset_dependencies rows that name one asset version — "who publicly uses
-- this version". The table's primary key is (project_id, asset_version_id,
-- dependency_type), which answers the project-side question the publish path
-- and the asset preview ask; a lookup by asset_version_id alone is not a
-- prefix of it, so both this task's profile read and the asset page's
-- used_by block (internal/assets.PageUsage) scan today.
CREATE INDEX asset_dependencies_version_idx
  ON asset_dependencies (asset_version_id);


-- ===== 00103_credit_attribution_dispute.sql =====

-- Credit attribution and credit disputes (T0809; docs/13 §2, §3).
--
-- # Two halves, and why they are stored differently
--
-- docs/13 §2: "Asset/Finding/Release 可声明 creators/major contributors/
-- method designer 等高层 credit。它可以被纠正，但 correction 作为新 event，
-- 旧 attribution 和 dispute history 保留。" and docs/13 §3: "Contributor 可
-- 发起 dispute，附带 ledger evidence；Maintainer/Organization governance
-- 处理。不得直接改原事件。Dispute 本身不参与公共 reputation 排名直到
-- resolution."
--
-- So there are two records with two different shapes, and the shapes are
-- not interchangeable:
--
--   - a HIGH-LEVEL CREDIT DECLARATION is never revised. A correction is a
--     new declaration, and the one it corrects stays readable ("旧
--     attribution ... 保留"). That is an append-only chain, exactly like
--     the rights-holder chain 00082 built for the same sentence's other
--     half, so it takes the same 00014 row guard and 00015 statement
--     guard: credit_attribution_statements is the declaration and
--     credit_attribution_parties its items, and NEITHER is ever updated or
--     deleted by any path.
--
--   - a DISPUTE has a current state (open → resolved | rejected) and a
--     history. The current state is 00011's credit_disputes row, updated in
--     place when governance closes it — that table is on
--     tests/integration/append_only_test.go's "mutable by design" list and
--     closing a dispute by updating that row is the design, not a hole. The
--     history is NOT the row: it is the pair of domain events
--     credit.dispute_opened / credit.dispute_resolved
--     (specs/events/event-types.yaml), which the Contribution Ledger
--     projects into the append-only contribution_events (00014's trigger).
--     "dispute history 可查" therefore reads from the ledger, and the
--     ledger row is the copy nothing can rewrite.
--
-- The split is what docs/13 §2's "correction 作为新 event，旧 attribution 和
-- dispute history 保留" asks for: the immutable half is append-only, the
-- mutable half is state, and closing a dispute writes an EVENT rather than
-- editing a record of one.
--
-- # What this migration adds to credit_disputes: the state machine
--
-- 00011 created credit_disputes with no guard at all, so "结案就地更新" was
-- also "任何 UPDATE 都行": a resolver could rewrite the claim it was
-- resolving, re-open a closed dispute, or stamp a resolution without a
-- state. The guard below pins the one transition the design has —
-- open → resolved | rejected, terminal — and pins the identity and the
-- claim of the row for every write path. It does NOT make the table
-- append-only: state, resolution and resolved_at are exactly the three
-- columns it leaves open, which is what "mutable by design" means here.
-- The distinction is the point of this paragraph: the guard makes the
-- current-state table honest, it does not turn it into history.
--
-- # Two target refs, one canonical shape
--
-- Both tables address what they are about with the "kind:value" text ref
-- this repository already spells in research_asset_versions.origin_refs
-- (00064) and in the Contribution Ledger's object_refs
-- (internal/contribution/ledger.go, RefTexts): the kind names the entity
-- class and the value its identity. The three kinds are docs/13 §2's own
-- list, nothing wider:
--
--   - "asset:<pid>"      — the asset's persistent identifier, the identity a
--                          citation resolves (00064), not its row id;
--   - "release:<uuid>"   — a releases row id;
--   - "finding:<uuid>"   — a findings row id (00057; its primary key is the
--                          finding's scientific_object_versions row).
--
-- An unknown kind is refused by the CHECK rather than by a reader's
-- judgement, and target_ref is stored with its kind attached so no row can
-- hold an id without saying what the id names — the same rule 00082 applies
-- to party ids.
--
-- There is deliberately NO foreign key to the target: one column cannot
-- reference three tables, and the alternative (three nullable columns plus
-- a CHECK that exactly one is set) would put the kind in the database twice
-- with two chances to disagree. Integrity is the writing command's
-- business, and it resolves the ref against the table its kind names
-- BEFORE it writes — the discipline internal/application/assetrights
-- established for asset_rights_holder_events (00082's header).
--
-- # The credit role vocabulary is two values, and the omission is deliberate
--
-- docs/13 §2 names three roles and leaves the list open: "creators/major
-- contributors/method designer 等". The open end is a product decision
-- about scientific semantics (who counts as a major contributor; whether
-- the 13 contribution roles of docs/04 §4 — which docs/04 §4 itself calls
-- "不是身份，不赋权，不计固定分值" — may double as credit titles). That
-- decision is recorded as an open L3 in tasks/decisions.md and is NOT made
-- here. This table admits exactly the two roles the task requires —
-- creator, major_contributor — and refuses every other value, INCLUDING
-- "method_designer" and anything the 等 could later name: fail closed on
-- the undecided end of the list, so no unratified credit title can be
-- written while the question is open. Widening the CHECK is the migration
-- that ratifies one.
--
-- The first role is not invented: "creator" is already a credit role in
-- this schema (asset_version_parties, 00082, from docs/11 §6), and this
-- table spells it identically so the two surfaces cannot disagree about
-- the word. "major_contributor" is the task requirement's own term.
--
-- The platform stores DECLARATIONS, never a computed ranking: nothing here
-- derives a credit from the ledger, from a count, or from any other fact
-- (docs/13 §4 forbids a single reputation score, §6 refuses raw counts as
-- proxies, CLAUDE.md §9 invariant 13 forbids a Truth Score). What lands is
-- what a person declared, attributable to the person who declared it.
--
-- # No party foreign key, and no project column on the items
--
-- credit_attribution_parties carries the same (party_kind, party_id) pair
-- asset_version_parties does, for the same reason (00082's header): the id
-- points into users for one kind and organizations for the other, so it
-- cannot be a single-column foreign key, and the writing command resolves
-- it against the table its kind names. A credit names a person or an
-- institution; 'project' is not a credit role here (docs/13 §2 names
-- people-shaped roles, and the originating project is already a column on
-- research_assets — storing it twice would give one fact two homes).

CREATE TABLE credit_attribution_statements (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  -- The research boundary the declaration belongs to. NOT NULL: a credit
  -- declaration is a governance act inside a project, and the project is
  -- what the actor's membership — and therefore the authorization — is
  -- resolved against.
  project_id uuid NOT NULL REFERENCES projects(id) ON DELETE RESTRICT,
  -- target_kind is carried as a column AND inside target_ref. The
  -- duplication is deliberate and is what makes the pair checkable: the
  -- CHECK below refuses a row whose two spellings disagree, so a reader may
  -- use either without trusting the other.
  target_kind text NOT NULL CHECK (target_kind IN ('asset', 'release', 'finding')),
  target_ref text NOT NULL,
  CONSTRAINT credit_attribution_statements_target_ref_kind
    CHECK (target_ref LIKE target_kind || ':%' AND length(target_ref) > length(target_kind) + 1),
  -- ordinal orders the declarations about one target. It is a per-target
  -- sequence rather than a timestamp, for the reason 00082 gave the
  -- rights-holder chain the same column: the chain's whole meaning is an
  -- order, two declarations in one transaction share now() exactly, and
  -- "the declaration a correction corrects" would otherwise be left to a
  -- tie-break nobody declared. The writing command takes a row lock on the
  -- target before reading the current maximum, so the sequence is
  -- serialized per target rather than computed in a race.
  ordinal integer NOT NULL CHECK (ordinal >= 1),
  -- recorded_by is the actor whose request declared the credit. NOT NULL: a
  -- credit with no attributable declarer would be an anonymous assertion
  -- about someone else's authorship (00082's rule for the same column).
  recorded_by uuid NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
  recorded_at timestamptz NOT NULL DEFAULT now(),
  -- One declaration per position: two rows at one ordinal would make "the
  -- declaration after this one" ambiguous.
  UNIQUE (project_id, target_kind, target_ref, ordinal)
);

COMMENT ON TABLE credit_attribution_statements IS
  'One high-level credit declaration for one target (docs/13 §2: Asset/Finding/Release 可声明 creators/major contributors/method designer 等高层 credit). Append-only: "它可以被纠正，但 correction 作为新 event，旧 attribution ... 保留" — a correction is a NEW row at the next ordinal, and every earlier declaration stays readable. Never updated, never deleted, by any path (00014 row guard + 00015 statement guard).';

CREATE TABLE credit_attribution_parties (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  statement_id uuid NOT NULL REFERENCES credit_attribution_statements(id) ON DELETE RESTRICT,
  -- The admitted vocabulary is two values, deliberately (see the header):
  -- widening it is a product decision, not a code change.
  role text NOT NULL CHECK (role IN ('creator', 'major_contributor')),
  party_kind text NOT NULL CHECK (party_kind IN ('user', 'organization')),
  party_id uuid NOT NULL,
  -- position is the order the declaring caller sent this party in, stored
  -- rather than reconstructed, for the reason 00082 gives the identical
  -- column: a declaration is a list, and an unordered set does not
  -- reproduce one.
  position integer NOT NULL CHECK (position >= 0),
  -- One party per role per position, and no party twice inside one role: a
  -- declaration naming the same person twice is a malformed list, not a
  -- stronger claim.
  UNIQUE (statement_id, role, party_id),
  UNIQUE (statement_id, role, position)
);

COMMENT ON TABLE credit_attribution_parties IS
  'The parties one credit declaration names, per role (docs/13 §2). Append-only, and scoped to its declaration: the current credit for a target is the party rows of that target''s greatest-ordinal statement (credit_attribution_statements), while every earlier declaration''s rows remain readable. Never updated, never deleted, by any path.';

CREATE TRIGGER credit_attribution_statements_append_only
  BEFORE UPDATE OR DELETE ON credit_attribution_statements
  FOR EACH ROW EXECUTE FUNCTION append_only_guard();

CREATE TRIGGER credit_attribution_statements_no_truncate
  BEFORE TRUNCATE ON credit_attribution_statements FOR EACH STATEMENT
  EXECUTE FUNCTION append_only_guard();

CREATE TRIGGER credit_attribution_parties_append_only
  BEFORE UPDATE OR DELETE ON credit_attribution_parties
  FOR EACH ROW EXECUTE FUNCTION append_only_guard();

CREATE TRIGGER credit_attribution_parties_no_truncate
  BEFORE TRUNCATE ON credit_attribution_parties FOR EACH STATEMENT
  EXECUTE FUNCTION append_only_guard();

CREATE INDEX credit_attribution_statements_target_ordinal
  ON credit_attribution_statements (project_id, target_kind, target_ref, ordinal DESC);

CREATE INDEX credit_attribution_parties_statement
  ON credit_attribution_parties (statement_id, role, position);

-- The dispute state machine. It is a targeted guard rather than the
-- append-only pair, because credit_disputes is a CURRENT-STATE table by
-- design (tests/integration/append_only_test.go, "Exempt tables (mutable by
-- design)"): state, resolution and resolved_at are the three columns this
-- function lets a write touch, and it lets it touch them exactly once per
-- dispute.
--
-- A row is BORN open: a dispute that starts resolved would have no
-- opening, so the record of who raised it — the credit.dispute_opened
-- event — could not exist, and the ledger would show a resolution of a
-- dispute that was never opened.
-- +goose StatementBegin
CREATE FUNCTION credit_dispute_state_guard() RETURNS trigger AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.state <> 'open' THEN
      RAISE EXCEPTION 'credit_disputes: a dispute is born open (state=%, credit_disputes is INSERT-immutable in its state)', NEW.state;
    END IF;
    IF NEW.resolution IS NOT NULL OR NEW.resolved_at IS NOT NULL THEN
      RAISE EXCEPTION 'credit_disputes: a newly opened dispute carries no resolution (credit_disputes is INSERT-immutable in resolution/resolved_at)';
    END IF;
    RETURN NEW;
  END IF;

  -- The identity of the dispute and the claim it makes are immutable:
  -- rewriting either would rewrite what the recorded open event is about
  -- (docs/13 §3 "不得直接改原事件" — a resolution answers the claim, it
  -- never edits it).
  IF NEW.id IS DISTINCT FROM OLD.id
     OR NEW.project_id IS DISTINCT FROM OLD.project_id
     OR NEW.opened_by IS DISTINCT FROM OLD.opened_by
     OR NEW.target_ref IS DISTINCT FROM OLD.target_ref
     OR NEW.claim IS DISTINCT FROM OLD.claim
     OR NEW.opened_at IS DISTINCT FROM OLD.opened_at THEN
    RAISE EXCEPTION 'credit_disputes: the dispute identity, its target and its claim are immutable (credit_disputes is UPDATE-immutable in id/project_id/opened_by/target_ref/claim/opened_at)';
  END IF;

  -- Terminal means terminal: a closed dispute is not re-opened and not
  -- re-decided. A later claim is a new dispute, which is the same rule
  -- docs/13 §2 applies to attribution corrections.
  IF OLD.state <> 'open' THEN
    RAISE EXCEPTION 'credit_disputes: a closed dispute is terminal (state % cannot be updated; credit_disputes is UPDATE-immutable once closed)', OLD.state;
  END IF;
  IF NEW.state NOT IN ('resolved', 'rejected') THEN
    RAISE EXCEPTION 'credit_disputes: the only transition is open -> resolved|rejected (credit_disputes is UPDATE-immutable in state, got %)', NEW.state;
  END IF;
  -- A close states its resolution: "resolved" with no reasoning would be a
  -- decision nobody can read, and resolved_at is the instant the decision
  -- was taken — the pair travels with the state or the row is not closed.
  IF NEW.resolution IS NULL OR btrim(NEW.resolution) = '' THEN
    RAISE EXCEPTION 'credit_disputes: closing a dispute requires a resolution (credit_disputes is UPDATE-immutable in resolution)';
  END IF;
  IF NEW.resolved_at IS NULL THEN
    RAISE EXCEPTION 'credit_disputes: closing a dispute requires resolved_at (credit_disputes is UPDATE-immutable in resolved_at)';
  END IF;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;
-- +goose StatementEnd

CREATE TRIGGER credit_disputes_state_guard
  BEFORE INSERT OR UPDATE ON credit_disputes
  FOR EACH ROW EXECUTE FUNCTION credit_dispute_state_guard();

-- The dispute reads: one project's disputes, newest first, and the open
-- ones for a target. Both are indexed because the dispute list is a
-- governance surface an operator scans, not a point lookup.
CREATE INDEX credit_disputes_project_opened
  ON credit_disputes (project_id, opened_at DESC);

CREATE INDEX credit_disputes_target
  ON credit_disputes (target_ref, opened_at DESC);


-- ===== 00104_discussions.sql =====

-- Discussion threads, comments and promotions (T0811).
--
-- docs/09 §4 and docs/42 §PR list "discussion" among a pull request's
-- parts, and the tree had no table, store, route or component for it: the
-- only hits for comment/discussion in infra/migrations before this file
-- are DDL `COMMENT ON` statements and 00009's review DECISION vocabulary
-- ('commented' → 00061's 'comment'), which is a reviewer's verdict on a
-- proposed head, not a conversation. This migration is the table set.
--
-- # What a discussion is, structurally: a version-less member row
--
-- A thread or a comment carries NO version number, NO state_id and no
-- branch. It is not a scientific object, it never takes part in a state
-- commit (internal/application/states.Service.Commit — 00004's
-- project_states + the version logs), and nothing here is registered in an
-- append-only ledger:
--
--   * nothing in this file writes scientific_object_versions (00005),
--     relation_versions (00006) or contribution_events (00011, guarded
--     append-only by 00014/00015). Commenting therefore cannot change
--     scientific state — the property is structural, not conventional:
--     there is no column, trigger or path here that reaches those tables;
--   * the repo's provenance representation is a RELATION (relation_versions
--     with a provenance relation type, docs/44), and its endpoints are
--     foreign keys to scientific_object_versions. A discussion has no
--     version, so it cannot be an endpoint of a relation — not by
--     preference but because the column would not accept it. Promoting a
--     discussion therefore records its provenance in an explicit
--     promotion row (discussion_promotions below), never as a relation.
--
-- # target_type / target_id: a discussion hangs on three surfaces
--
-- A thread names what it is about. Three target kinds exist because three
-- surfaces have a discussion today (the task's requirement): a project, a
-- published knowledge object, and a pull request. target_id is TEXT and
-- holds the target's identity IN ITS OWN ADDRESSING SCHEME — the project
-- uuid, the publication's pid, the pull request's per-project number —
-- because that is the identity the surface that carries the discussion
-- already shows a caller: the knowledge page addresses a publication by
-- pid (00083), the PR page by number (00009), the project page by its
-- uuid. A polymorphic uuid column would have forced every client to
-- translate what it holds into an internal row id first.
--
-- The target is NOT a foreign key: one column cannot reference three
-- tables. The command resolves and verifies the target inside the thread's
-- project before any row is written (fail closed, docs/45 — an unknown or
-- foreign target is one not-found answer), and the project_id column is
-- what every read, authorization and scope check uses. The CHECK below
-- pins the one case that CAN be pinned in the schema: a thread whose
-- target is its own project must carry that project's uuid — the column
-- pair cannot disagree no matter which write path inserts it.
--
-- # Comments: never physically deleted
--
-- A comment carries deleted_at/deleted_by, NULL while it stands. CLAUDE.md
-- §9.8 ("nothing disappears; state only evolves") is why there is no
-- physical delete: the row, its author and its time survive, the body is
-- simply withheld from the wire after deletion, and a promotion that
-- points at a since-deleted comment still resolves to the author who made
-- the proposal. The pair moves together or not at all (the CHECK below).
--
-- # Promotions: the explicit provenance chain
--
-- One row per promotion: which comment was proposed, what it became, who
-- promoted it and when. The promoted object is named by promoted_ref in
-- the same shape as audit_log.target_ref ("<kind>:<uuid>"), so the REF is
-- derived from the kind exactly once (the CHECK) and a promotion whose
-- kind and ref disagree cannot exist. The reverse read — the promoted
-- object answering "which discussion, whose comment" — is a query on this
-- table joined to discussion_comments (the author column there), which is
-- how an Issue, a promoted Hypothesis and an external-evidence proposal
-- all answer the same question the same way.
--
-- No append-only trigger guards this table: a promotion is a member row
-- like a milestone, not a version log (00014/00015 guard the logs). No
-- update/delete surface exists in V1 either, so the rows only accumulate.

CREATE TABLE discussion_threads (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  project_id uuid NOT NULL REFERENCES projects(id) ON DELETE RESTRICT,
  target_type text NOT NULL CHECK (target_type IN ('project','knowledge','pull_request')),
  target_id text NOT NULL CHECK (btrim(target_id) <> ''),
  created_by uuid NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
  created_at timestamptz NOT NULL DEFAULT now(),
  -- A thread on the project it lives in names that project, spelled the
  -- same way projects.id renders as text. Any other kind of target is
  -- resolved by the command (the CHECK can only see this one pair).
  CHECK (target_type <> 'project' OR target_id = project_id::text)
);

-- The target scan: every thread of one (project, target), oldest first.
CREATE INDEX discussion_threads_target_idx
  ON discussion_threads(project_id, target_type, target_id, created_at, id);

CREATE TABLE discussion_comments (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  thread_id uuid NOT NULL REFERENCES discussion_threads(id) ON DELETE RESTRICT,
  project_id uuid NOT NULL REFERENCES projects(id) ON DELETE RESTRICT,
  body text NOT NULL CHECK (btrim(body) <> ''),
  created_by uuid NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
  created_at timestamptz NOT NULL DEFAULT now(),
  deleted_at timestamptz,
  deleted_by uuid REFERENCES users(id) ON DELETE RESTRICT,
  -- Deletion is recorded as a pair: a tombstone names when and by whom, or
  -- it is no tombstone at all.
  CHECK ((deleted_at IS NULL) = (deleted_by IS NULL))
);

-- The conversation read: one thread's comments in creation order. The
-- creation order (created_at, id) is a total order, so the rendering never
-- depends on insertion timing ties.
CREATE INDEX discussion_comments_thread_idx
  ON discussion_comments(thread_id, created_at, id);

CREATE TABLE discussion_promotions (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  project_id uuid NOT NULL REFERENCES projects(id) ON DELETE RESTRICT,
  thread_id uuid NOT NULL REFERENCES discussion_threads(id) ON DELETE RESTRICT,
  comment_id uuid NOT NULL REFERENCES discussion_comments(id) ON DELETE RESTRICT,
  promoted_kind text NOT NULL CHECK (promoted_kind IN ('issue','hypothesis','external_evidence')),
  promoted_ref text NOT NULL,
  promoted_by uuid NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
  promoted_at timestamptz NOT NULL DEFAULT now(),
  -- The ref IS "<kind>:<uuid>": the prefix is the kind's own name and what
  -- follows it is not empty. A promotion cannot name a kind it is not, and
  -- cannot name nothing.
  CHECK (promoted_ref = promoted_kind || ':' ||
         substring(promoted_ref FROM length(promoted_kind) + 2))
);

-- The reverse read: which discussion proposed the object an id names.
CREATE INDEX discussion_promotions_ref_idx
  ON discussion_promotions(project_id, promoted_kind, promoted_ref, promoted_at, id);

-- And the forward one: what one comment has become so far.
CREATE INDEX discussion_promotions_comment_idx
  ON discussion_promotions(comment_id, promoted_at, id);


-- ===== 00107_activity_research_event_scope.sql =====

-- The research-event half of the Project Activity feed (T0607).
--
-- The Activity page reads two registries as ONE key-set-paginated sequence
-- on (occurred_at, id): the project's governance rows in audit_log and its
-- research events in research_events (docs/26 §1 keeps the two apart —
-- the page reads both, it does not merge them). The audit half already has
-- the index that makes that read a range scan:
--
--   audit_log_project_occurred_idx (project_id, occurred_at DESC, id DESC)  -- 00020
--
-- research_events had no index at all beyond its primary key. Its only
-- readers so far ask by identity — the asset page joins on
-- payload->>'asset_id', the webhook and notification fan-outs join on
-- outbox_event_id or deliver by id — so every one of them is served by a
-- key or a join, and the table has been small enough that nobody noticed.
-- The Activity feed asks the question those readers never ask: "this
-- project's events, newest first, from this cursor". Without an index that
-- is a sequential scan of every event on the platform per page, and it is
-- the only read in the feed whose cost grows with the platform rather than
-- with the project.
--
-- The column order mirrors the audit index exactly, because the queries
-- are the same query: (project_id) is the scope predicate, and the
-- (occurred_at DESC, id DESC) suffix is the ordering the keyset cursor
-- rides, so one index serves the ORDER BY and the
-- `(occurred_at, id) < (before_ts, before_id)` predicate at once.
--
-- DESC on both trailing columns is what makes the page a forward walk
-- rather than a sort: the feed is always read newest-first, and a
-- backwards index would have PostgreSQL read the whole project's history
-- to answer the first page. NULLS are not a consideration — both columns
-- are NOT NULL (00012).
--
-- project_id is nullable in research_events (an event need not be
-- project-scoped), which is why this is a plain b-tree and not a partial
-- index: the feed's scope predicate is equality on a non-null id, so the
-- NULL rows are simply outside every range this index is asked for, and
-- excluding them from the index would buy nothing the range already does.
CREATE INDEX research_events_project_occurred_idx
  ON research_events (project_id, occurred_at DESC, id DESC);

COMMENT ON INDEX research_events_project_occurred_idx IS
  'The project Activity feed''s research-event branch (T0607): the project''s research events newest-first, the shape the (occurred_at, id) keyset cursor of internal/persistence.ListProjectActivity rides. Mirrors audit_log_project_occurred_idx (00020) so both halves of the merged feed are range scans.';


-- ===== 00110_ranking_factor_indexes.sql =====

-- T0905. One index, and the reason it is the only schema change this task
-- needs.
--
-- T0905 orders T0904's retrieval candidates by the six factors docs/14 §3
-- names (query/scope match, evidence profile, review state, independent
-- reproduction, contradictory evidence, version/freshness). Each factor is
-- a READ of rows that already exist — evidence_assertions (00007),
-- reviews (00009/00061), relation_versions (00006) and
-- scientific_object_versions (00005). Nothing new has to be stored: the
-- ranking is a view over facts the platform already keeps, which is what
-- makes it re-derivable and what makes a "ranking model" that silently
-- accumulated its own state unnecessary (and would be a second copy of the
-- truth).
--
-- What those reads need is an index, and exactly one of them is missing.
--
-- # The review-state read, and why it had no index
--
-- A candidate's review state is read from the reviews recorded on the
-- project STATE its object version was created in: reviews.reviewed_state_id
-- (00061) is the exact head a reviewer judged, and
-- scientific_object_versions.state_id (00005) is the state a version was
-- created in. Joining the two is the only way to answer "was this version
-- reviewed", because reviews are recorded per pull request and per state,
-- never per object version — deliberately, since a review is a judgment
-- about one proposed state, not about a moving target.
--
-- reviews carries exactly two indexes and neither can serve that join:
--
--   1. its primary key on id;
--   2. reviews_reviewer_kind_state_key, the UNIQUE
--      (pull_request_id, reviewer_id, review_kind, reviewed_state_id) from
--      00061 — which LEADS with pull_request_id, so a lookup by
--      reviewed_state_id alone cannot use it (a B-tree is usable from its
--      leading column onward, never from the middle).
--
-- So the read was a sequential scan of the whole table per ranking pass.
-- The table is small today, which is exactly why this is the moment to add
-- the index rather than later: the write cost is one index entry per review,
-- and a table that only grows is a table whose seq scan only gets worse.
--
-- # Why not an index for the evidence read
--
-- evidence_assertions already has evidence_assertions_target_idx
-- (target_object_version_id, created_at, id) from the migration that added
-- its guards, and that is the leading column this task's read filters on.
-- The contradiction read over relation_versions is served by 00006's
-- relation_versions_source_idx / relation_versions_target_idx, and the
-- version ordinal by scientific_object_versions' UNIQUE (object_id,
-- version_no). Adding a second index for any of them would be an index
-- nothing selects by.
--
-- # What this index is NOT
--
-- It is not a uniqueness rule and carries no predicate: every review row is
-- indexed, so a future read by state (a review round's own listing, T0604's
-- responsibility routing) can use it too. It is also not a new grant —
-- reviews are read only through queries that join them onto rows the
-- caller's scope already admitted, and this index changes no predicate
-- anywhere.
CREATE INDEX reviews_reviewed_state_idx ON reviews (reviewed_state_id);

COMMENT ON INDEX reviews_reviewed_state_idx IS
  'The review-state lookup for T0905''s scientific ranking: reviews of one project state (reviews.reviewed_state_id, 00061), which the table''s UNIQUE constraint cannot serve because it leads with pull_request_id.';


-- ===== 00111_dependency_impact.sql =====

-- T1007. ONE index: the idempotency of the dependency-impact alert. No
-- table, no column, and — measured, not assumed — no second index. The
-- reason is the task's own subject.
--
-- docs/18 §5 (Dependency Watch) asks the platform to analyse the downstream
-- of an upstream change and create an alert, "只标记 review required，不自动
-- 改科学结论". An alert is therefore a MESSAGE, not a record with a
-- lifecycle: it has no acknowledgement to store, no assignee, no state to
-- transition. The message carrier already exists and is already registered
-- — `dependency.impact_detected` (specs/events/event-types.yaml:29) — and
-- the delivery pipeline that carries messages is built: the outbox (00012,
-- 00046), the fan-outs (00078) and the digest. A dependency_impacts table
-- would be a second copy of "what the log already says", with its own
-- write path, its own drift and its own retention question, and nothing in
-- the product would read it that cannot read the event log instead.
--
-- The idempotency, however, is the analysis's own problem and the schema is
-- where it has to be solved.

-- The analysis is a consumer of the event log, and it is the one consumer
-- whose output is derived from its input rather than willed by a caller:
-- for one trigger event it emits one `dependency.impact_detected` per
-- affected downstream, and the same upstream change replayed — a restarted
-- worker, a re-scan, a second process over the same log — must not produce
-- a second alert. The dedupe belongs in the DATABASE for the reason the
-- ledger projection's does (00087: "no lock, no claim, no bookkeeping
-- row"): the log is append-only, the analysis holds no mutable state, and
-- the only thing that has to agree between two concurrent analyses is the
-- row they write.
--
-- The key is (trigger event, affected entity): one alert per pair, ever.
-- It is read out of the payload — trigger_event_id names the research_events
-- row that caused the analysis, affected_kind/affected_id name the entity
-- the alert is about — because those three fields ARE the identity of the
-- alert (the payload's own definition, pinned by a test in
-- internal/application/dependencyimpact). A conflict on them is the replay,
-- and the insert's ON CONFLICT DO NOTHING turns it into a no-op rather than
-- an error.
--
-- The index is PARTIAL on the event type: a bare unique index over
-- payload->>'…' would constrain every other producer's outbox rows against
-- keys they do not carry (three NULLs are never a conflict in a unique
-- index, but a future producer that happened to carry these keys under a
-- different meaning would be silently deduplicated against an alert it has
-- nothing to do with).
CREATE UNIQUE INDEX outbox_events_dependency_impact_uniq
  ON outbox_events (
    event_type,
    (payload->>'trigger_event_id'),
    (payload->>'affected_kind'),
    (payload->>'affected_id')
  )
  WHERE event_type = 'dependency.impact_detected';

COMMENT ON INDEX outbox_events_dependency_impact_uniq IS
  'One dependency.impact_detected per (trigger event, affected entity), ever: the analysis is derived from the event log, so replaying it must be a no-op (T1007, docs/18 §5).';

-- What this migration deliberately does NOT add, and how that was checked.
--
-- The analysis reads two tables. Both directions already have the index the
-- read needs, and a second one would be a write cost for nothing:
--
--   * THE OBJECT SIDE. The walk is a recursive CTE over relation_versions,
--     which carries relation_versions_source_idx
--     (source_object_version_id, relation_type) and
--     relation_versions_target_idx (target_object_version_id,
--     relation_type) from 00006/00008 — exactly the two directions the
--     walk follows, and the second column is the relation-type filter
--     itself.
--
--   * THE ASSET SIDE. The analysis reads asset_dependencies in the
--     direction its primary key does not serve — asset_dependencies' PK is
--     (project_id, asset_version_id, dependency_type), which leads with the
--     project, so "which projects depend on this fixed version" cannot use
--     it. But that direction was already indexed: 00101 (T0808) added
--     asset_dependencies_version_idx ON asset_dependencies
--     (asset_version_id) for the asset page's used_by block, which asks
--     this very question. The analysis's read is the same probe over the
--     same column, so it uses the same index, and a covering variant
--     (asset_version_id, dependency_type) would buy nothing at this
--     cardinality while adding a second B-tree to every write to a table
--     the publisher writes on every publish. It was written, then removed
--     once 00101 turned out to be sitting there — which is what
--     TestFreshInstallCatalog's explicit-index inventory would have caught
--     either way.


-- ===== 00120_attestations.sql =====

-- Private Evidence / Public Attestation, the storage model (T0812).
--
-- # What an attestation is
--
-- A minimal public statement a project makes about a PUBLIC object version
-- it did not author: "we validated this, this way, and the result was
-- this". It is the one thing a private project may publish about its own
-- private work — docs/12 §2 逐字: "Private Project：project/RSG/private
-- blobs 默认不可见；可显式 Publish Asset/Knowledge/Attestation" — and
-- docs/22 §28 lists create attestation among the high-risk commands that
-- need server-side authorization plus policy validation.
--
-- # Attestation != evidence, and this table is where that is structural
--
-- `evidence_assertions` (00007, guards in 00058) is the evidence model: an
-- assertion pins TWO versions (target and evidence), and carries the
-- substance — directness, inference_nature, scope, reasoning_note. An
-- attestation pins ONE version and carries none of those. It has no
-- evidence_object_version_id column at all, and no free-text field a
-- private detail could be smuggled through: the public half of a row is
-- exactly the four enumerated values below plus the target pin.
--
-- That is the whole privacy argument, and it is STRUCTURAL rather than
-- procedural: there is no column on this table that names the underlying
-- private evidence or its content. What the row does record of the
-- private side — which project attested, which of that project's states
-- the attestation rests on, which internal review authorised it — is
-- cited by id, never by value, and is never projected publicly (see
-- internal/application/attestations.Present, which has no field for it).
--
-- # The private side, cited and not disclosed
--
--   * attesting_project_id  — the project that attests. A project id is
--                             not a public identity: nothing renders it.
--   * basis_state_id        — the attesting project's OWN state that the
--                             attestation rests on (the private evidence
--                             lives in that state's manifest). This is the
--                             "underlying private evidence" the task
--                             requires not to be exposed.
--   * internal_review_id    — the review that authorised the attestation,
--                             on a pull request of the attesting project
--                             and of exactly that state.
--
-- The two triggers below make "the cited private facts are the attester's
-- own" unconditional for ANY write path (application code, psql, a leaked
-- credential), in the 00014/00015/00028 discipline: the domain layer
-- validates on the happy path, the database makes the invariant
-- unconditional. A row whose basis state or whose review belongs to some
-- other project would be an attestation resting on somebody else's private
-- work — the one shape this table must not be able to hold.
--
-- # The target: exactly one pin, and no stored kind
--
-- A target is pinned to a scientific object version (the requirement's
-- Protocol/Claim) or to a research asset version (its Asset). Exactly one
-- of the two columns is set — the CHECK below — and the KIND is DERIVED
-- from which one it is, never stored. A stored target_kind column could
-- disagree with the row it points at (a 'protocol' label on a claim
-- version); the joined row cannot. This is the same decision
-- internal/application/evidencenetwork records for the evidence classes
-- ("the classes are computed, never stored").
--
-- # The public half: four enumerated values
--
--   * validation_type   — what kind of validation was performed
--   * validation_result — confirmed / refuted / inconclusive
--   * org_visibility    — whether the attesting organization is named
--
-- validation_result is deliberately three-valued and NOT numeric: no
-- weight, no score, nothing derivable (CLAUDE.md §9.13, docs/10 §4 "V1 不
-- 自动赋数值权重"). Two attestations on one version keep their own
-- results side by side, exactly as two contradictory evidence assertions
-- do.
--
-- # org_visibility AND the organization's standing setting
--
-- organizations.attestation_attribution is the organization's own standing
-- answer to "may we be named"; the attestation's org_visibility is the
-- choice made for THIS statement. The public projection names the
-- organization only when BOTH say so, and it re-reads the setting on
-- every read (internal/application/attestations.Present). Two independent
-- gates, each with its own failure mode:
--
--   * the recorded value is a PROMISE. An attestation issued while the
--     organization was anonymous stays anonymous even after the setting
--     flips to named — a standing setting must not retroactively break a
--     promise made under it.
--   * the setting is a FLOOR. An organization that flips to anonymous
--     stops being named on every attestation it ever issued — otherwise a
--     setting would be unable to retract a disclosure it exists to
--     control.
--
-- DEFAULT 'anonymous' is the conservative direction, and it is the
-- direction docs/12 §3 requires: "任何 private→public … 都要求有权限的人
-- 显式确认". Being named is a widening; an organization that has not
-- chosen it is not named.
--
-- # What is deliberately NOT here
--
--   * No uniqueness on (attesting_project_id, target_object_version_id,
--     validation_type). A second row with the same shape has a legitimate
--     reading — a re-validation after a first inconclusive result is a
--     new judgment about the same pair — and refusing it in the schema
--     would refuse the honest case to prevent the dishonest one. Nothing
--     sums these rows either (CLAUDE.md §9.13), so a duplicate buys
--     nothing; anti-gaming is a separate concern (docs/13 §6).
--   * No visibility column. An attestation is written already-published:
--     there is no draft state, and a "private attestation" would be a
--     second kind of row on a table whose whole point is that what is here
--     is public.
--   * No revocation. V1 does not retract (the same conservative default
--     the knowledge publication took); history is not deleted anyway
--     (CLAUDE.md §9.8), so a retraction would be a new row that the
--     projection reads — a later task's design, not this one's guess.

ALTER TABLE organizations
  ADD COLUMN attestation_attribution text NOT NULL DEFAULT 'anonymous'
    CHECK (attestation_attribution IN ('anonymous', 'named'));

COMMENT ON COLUMN organizations.attestation_attribution IS
  'standing answer to "may this organization be named on an attestation it issues": anonymous (default) or named. The attestation records its own org_visibility as well; the public projection names the organization only when both say named (migration 00120, T0812)';

CREATE TABLE attestations (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  -- pid is the attestation's public identity: the id a client addresses and
  -- cites. Same 26-character lowercase Crockford base32 vocabulary and the
  -- same CHECK as asset pids (00064) and knowledge publication pids
  -- (00083), so one predicate in Go (assets.ValidPID) reads all three.
  --
  -- The DEFAULT stays for rows written before the command could mint one;
  -- the command passes the pid it minted explicitly, because a persistent
  -- identifier that two writers derive differently is not a persistent
  -- identity (00064 records the same decision).
  pid text NOT NULL DEFAULT substr(replace(gen_random_uuid()::text, '-', ''), 1, 26),

  -- The public target: exactly one of these two, enforced below.
  target_object_version_id uuid REFERENCES scientific_object_versions(id) ON DELETE RESTRICT,
  target_asset_version_id  uuid REFERENCES research_asset_versions(id) ON DELETE RESTRICT,

  -- The private side. Cited by id; never projected.
  attesting_project_id      uuid NOT NULL REFERENCES projects(id) ON DELETE RESTRICT,
  attesting_organization_id uuid REFERENCES organizations(id) ON DELETE RESTRICT,
  basis_state_id            uuid NOT NULL REFERENCES project_states(id) ON DELETE RESTRICT,
  internal_review_id        uuid NOT NULL REFERENCES reviews(id) ON DELETE RESTRICT,

  -- The public half.
  validation_type text NOT NULL,
  validation_result text NOT NULL,
  org_visibility text NOT NULL,

  created_by uuid NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
  created_at timestamptz NOT NULL DEFAULT now(),

  CONSTRAINT attestations_validation_type_check
    CHECK (validation_type IN ('reproduction', 'method_validation', 'data_audit', 'rights_review')),
  CONSTRAINT attestations_validation_result_check
    CHECK (validation_result IN ('confirmed', 'refuted', 'inconclusive')),
  CONSTRAINT attestations_org_visibility_check
    CHECK (org_visibility IN ('anonymous', 'named')),
  CONSTRAINT attestations_pid_format
    CHECK (pid ~ '^[0-9a-hjkmnp-tv-z]{26}$'),
  -- Exactly one target pin. Both NULL is an attestation about nothing; both
  -- set is an attestation about two things, and no read could say which one
  -- the validation_result is about. `<>` on two booleans, not OR: the
  -- columns are nullable, so the two IS NULL tests are the only total form.
  CONSTRAINT attestations_exactly_one_target
    CHECK ((target_object_version_id IS NULL) <> (target_asset_version_id IS NULL))
);

CREATE UNIQUE INDEX attestations_pid_uniq ON attestations (pid);

-- The two natural target reads: "the attestations about this object
-- version", newest first (the shape a public listing rides), and the same
-- for an asset version. The keyset order is (created_at DESC, id DESC) so
-- the read walks the index rather than sorting.
CREATE INDEX attestations_target_object_idx
  ON attestations (target_object_version_id, created_at DESC, id DESC);
CREATE INDEX attestations_target_asset_idx
  ON attestations (target_asset_version_id, created_at DESC, id DESC);

-- The attesting project's own read (a member listing what this project has
-- attested) — a stable forward walk, not a keyset page.
CREATE INDEX attestations_attesting_project_idx
  ON attestations (attesting_project_id, created_at, id);

-- The private-side guard. Two facts must hold for ANY write path:
--
--   1. the basis state is a state of the ATTESTING project, and
--   2. the internal review is a review on a pull request of the attesting
--      project, of EXACTLY that basis state.
--
-- (2) is the same pinning reviews.reviewed_state_id carries since 00061
-- ("a review is a judgment about one state, not about a moving target"):
-- here it says the review the attestation cites is the review of the state
-- the attestation rests on, not a review of some other state of the same
-- project. Without it, a project could cite an unrelated approved review.
--
-- Cross-table invariants cannot be CHECK constraints, so they are triggers
-- — the same layering 00004/00005/00058 use, and the same reason: the
-- domain layer refuses these on the happy path, and the database refuses
-- them unconditionally.
-- +goose StatementBegin
CREATE FUNCTION attestations_private_side_guard() RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM project_states ps
    WHERE ps.id = NEW.basis_state_id
      AND ps.project_id = NEW.attesting_project_id
  ) THEN
    RAISE EXCEPTION 'attestation: basis state % is not a state of the attesting project % (the private evidence an attestation rests on is the attesting project''s own)',
      NEW.basis_state_id, NEW.attesting_project_id
      USING ERRCODE = 'P0001';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM reviews r
    JOIN pull_requests pr ON pr.id = r.pull_request_id
    WHERE r.id = NEW.internal_review_id
      AND pr.project_id = NEW.attesting_project_id
      AND r.reviewed_state_id = NEW.basis_state_id
  ) THEN
    RAISE EXCEPTION 'attestation: internal review % is not a review of basis state % on a pull request of project % (an attestation cites the review that judged the state it rests on)',
      NEW.internal_review_id, NEW.basis_state_id, NEW.attesting_project_id
      USING ERRCODE = 'P0001';
  END IF;

  IF NEW.attesting_organization_id IS NOT NULL THEN
    IF NOT EXISTS (
      SELECT 1 FROM projects p
      WHERE p.id = NEW.attesting_project_id
        AND p.organization_id = NEW.attesting_organization_id
    ) THEN
      RAISE EXCEPTION 'attestation: organization % does not own the attesting project % (an attestation is made in its own organization''s name)',
        NEW.attesting_organization_id, NEW.attesting_project_id
        USING ERRCODE = 'P0001';
    END IF;
  ELSE
    IF EXISTS (
      SELECT 1 FROM projects p
      WHERE p.id = NEW.attesting_project_id
        AND p.organization_id IS NOT NULL
    ) THEN
      RAISE EXCEPTION 'attestation: attesting project % belongs to an organization, so the attestation must record it',
        NEW.attesting_project_id
        USING ERRCODE = 'P0001';
    END IF;
  END IF;

  RETURN NEW;
END;
$$;
-- +goose StatementEnd

CREATE TRIGGER attestations_private_side
  BEFORE INSERT OR UPDATE ON attestations
  FOR EACH ROW EXECUTE FUNCTION attestations_private_side_guard();

-- Append-only. An attestation is a statement made in public: it is never
-- edited and never deleted (CLAUDE.md §9.8 — nothing disappears; state
-- only evolves). The same guard function 00014 installed for the version
-- logs and ledgers, and the same statement-level TRUNCATE closure 00015
-- added, because row triggers do not fire on TRUNCATE.
CREATE TRIGGER attestations_append_only
  BEFORE UPDATE OR DELETE ON attestations
  FOR EACH ROW EXECUTE FUNCTION append_only_guard();

CREATE TRIGGER attestations_no_truncate
  BEFORE TRUNCATE ON attestations FOR EACH STATEMENT
  EXECUTE FUNCTION append_only_guard();


-- ===== 00121_search_answer_record.sql =====

-- The record of one search and the answer it produced (T0906).
--
-- docs/22 §8 (Search API) is one sentence long and it is the whole reason
-- this table exists: "接受 raw query + structured optional filters；服务端保存
-- query plan、selected entity ids、answer citations". Before this file, nothing
-- in the tree saved a search at all — POST /search did not exist, and the
-- contract already carries POST /search/{searchId}:start-project
-- (specs/api/openapi.yaml), a route that cannot be served without a record to
-- address a searchId to. The three things the spec names are the columns
-- below: the plan, the selected refs, the citations.
--
-- # A record, not a cache
--
-- The row is written once, when the answer is produced, and is never updated
-- and never read to answer the same question again. Reusing a stored answer
-- would publish a claim at its old age: the ranking is a function of the
-- corpus AS OF NOW (ranking/doc.go), so an answer whose sources have since
-- been superseded is a statement the platform would no longer make. What the
-- row is FOR is the two things that need the search to still exist after the
-- response was sent: the citation trail (an answer cites entity versions, and
-- a reader must be able to see which search produced a citation — docs/54
-- ranks a fabricated or unauthorized citation as a top-severity scenario), and
-- the start-project flow, which resumes a search's sources as a draft
-- research context rather than re-running the search under a different corpus.
--
-- # citations ⊆ selected_refs, enforced by the database
--
-- The package's central invariant is that an answer may cite only what
-- retrieval returned (internal/search/answer/doc.go, docs/22 §8's last
-- clause, docs/54 #7). The Go guard refuses a document that cites anything
-- else, and this CHECK is the second, independent refusal: a row whose
-- citations name a ref the search did not return cannot be inserted by ANY
-- writer, including one added later that has not read the guard. Containment
-- is the whole of it: it forbids a citation outside selected_refs and says
-- nothing about how many there are, so an empty citation list satisfies it on
-- any search — which is correct, because an empty list is exactly what a
-- fallback means (see the citations column below).
--
-- # What is jsonb and why
--
-- plan, signals and answer are documents, and they are stored as documents
-- rather than decomposed into rows. None of them is a fact the database has a
-- question about: nothing joins to a plan's narrowing or to a signal report,
-- and the answer is the answer layer's own canonical document — its shape is
-- that package's schema (internal/search/answer/schema.go, versioned by
-- answer_version), not this schema's. Decomposing them here would give the
-- platform a second, drifting definition of what an answer is. The two
-- columns that DO carry relational meaning — the selected refs and the
-- citations — are text[] precisely because the invariant above is a statement
-- about them as sets of refs.
--
-- plan is nullable and signals/answer are not: a deployment with no planner
-- configured still searches (planner.New requires a provider — planning's
-- absence changes what is READ), so "no plan" is a real state of a real
-- search; a search that ran always has a signal report and always has an
-- answer document, even when that answer is the structured fallback.
--
-- # No index
--
-- Reads of this table are by primary key (one searchId at a time), and that
-- is the only read the contract has. An index for a read that does not exist
-- is a write cost paid on every search for nothing; the catalog fixture
-- (tests/integration/catalog_test.go) requires the explicit index set to
-- match exactly, so an index added here would also be a schema change nobody
-- asked for.
CREATE TABLE search_records (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  -- The actor whose scope the search ran under. The record belongs to the
  -- person who asked: the scope resolved from this id decided which rows were
  -- readable (internal/search/scope.go is the only constructor of it), so an
  -- answer read back under a different actor would be a claim made about
  -- rows that actor may not read.
  actor_id uuid NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
  query text NOT NULL CHECK (btrim(query) <> ''),
  -- The structured filters the caller sent, verbatim and uninterpreted:
  -- an unknown shape is refused by the planner, not repaired here.
  filters jsonb,
  -- The query plan, when a planner ran.
  plan jsonb,
  -- The retrieval's own SignalReport[] — which signals ran, which were
  -- skipped and why. It is stored because it is what the answer's coverage
  -- limitations are derived from: without it, "the vector signal did not run"
  -- is a sentence in a saved answer that nothing can check.
  signals jsonb NOT NULL,
  -- The entity version refs the result selected, in rank order, in the
  -- retrieval's own "<kind>:<identity>@<version>" spelling. This is the set
  -- the answer may cite and the set start-project resumes.
  selected_refs text[] NOT NULL,
  -- The refs the answer cites: the subset of selected_refs the written summary
  -- leans on. It is non-empty exactly when a MODEL wrote that summary: the
  -- answer schema requires an answered document to cite at least one ref
  -- (internal/search/answer/schema.go), and every fallback is constructed
  -- with no citations at all (generator.go's fallback), so a fallback row's
  -- citations are always empty. Empty is a real state (a fallback over a
  -- result the model never saw).
  citations text[] NOT NULL,
  -- The answer document (internal/search/answer, answer_version 1).
  answer jsonb NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  -- The invariant, in the database. See the header.
  CHECK (citations <@ selected_refs)
);
